INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C1','soc',3,2,'u1',1,'사회의 변화와 원인 — 사회의 모습은 끊임없이 변해 사라지는 모습, 새로 생기는 모습, 다른 모습으로 바뀌는 모습이 있음 · 원인: 사람 수의 변화, 평균 수명의 증가, 사람들의 생각 변화, 과학 기술의 발달, 다른 나라와의 교류(실제로는 여러 원인이 얽힘) · 옛 학교: 학생은 많고 교실은 부족해 오전반·오후반, 점심 도시락, 이름은 국민학교, 교실 난로 → 오늘날 급식·초등학교 · 학생이 줄어 문을 닫는 학교, 노인 복지관, 청소 로봇, 세계 음식 가게',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C2','soc',3,2,'u1',2,'저출산으로 달라진 생활 — 저출산은 태어나는 아이의 수가 줄어 출산율이 감소하는 현상 · 그래프(우리나라에서 연도별 태어나는 아이의 수, 가로 연도·세로 만 명): 1970년 101만 → 1980년 86만 → 1990년 65만 → 2000년 64만 → 2010년 47만 → 2020년 27만, 점점 줄어듦 · 까닭: 결혼하지 않거나 아이를 낳아 기르는 데 부담을 느끼는 사람이 많아짐 · 영향: 학생 수와 일할 수 있는 사람 수가 줄어듦 · 노력: 아이를 낳고 키우는 데 필요한 돈과 물품 지원, 안전하고 쾌적한 보육 시설, 부모가 일을 쉴 수 있는 제도',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C3','soc',3,2,'u1',3,'고령화로 달라진 생활 — 65세 이상을 노인이라 함 · 의학 기술이 발달하고 깨끗한 환경에서 생활하게 되어 오래 살게 됨 · 고령화는 전체 사람 수에서 노인의 수가 차지하는 비율이 높아지는 현상(비율 = 일정한 양을 기준으로 어떤 양이 차지하는 정도) · 100명 마을이라면 노인이 1980년 4명 정도 → 2020년 16명 정도 → 2050년(예상) 40명 정도 · 달라진 모습: 노인 복지관, 노인 전문 병원·요양 시설, 노인 배움 프로그램, 일하는 노인 · 노력: 복지 제도, 알맞은 일자리, 노인을 위한 물건 개발, 노후 생활 준비 지원',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C4','soc',3,2,'u1',4,'지능정보화로 달라진 생활 — 정보 통신 기술은 전화·컴퓨터 같은 기기로 정보를 주고받는 기술, 인공지능은 사람처럼 정보를 익히고 처리해 여러 상황에 적용하는 컴퓨터 시스템 · 지능정보화는 인공지능을 활용한 다양한 기술이 사회 전반에 폭넓은 영향을 미치는 현상 · 편리해진 점: 배달 로봇, 맞춤 교육, 목소리 인식 기기, 안전 운전 도움 · 문제: 사이버 범죄, 거짓 정보 확산, 인터넷·스마트폰 과의존, 일자리 감소 · 노력: 사이버 범죄 감시, 올바른 사용 습관 지원, 인공지능 활용 능력 교육, 직업 환경 대응 교육 · 장점은 누리고 단점은 보완 · 개인 정보를 함부로 공유하지 않기, 인터넷 정보를 비판 없이 믿지 않기, 정해진 규칙에 따라 사용하기',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C5','soc',3,2,'u1',5,'세계화로 달라진 생활 — 세계화는 세계 여러 나라가 다양한 분야에서 교류하며 전 세계가 하나로 연결되는 현상 · 모습: 다른 나라 음식·과일·영화, 함께하는 행사, 세종 학당(한국어와 한국에 관한 내용을 가르침), 한류(대한민국과 관련 있는 것들이 다른 나라에서 인기를 얻는 현상) · 물건은 다른 나라에서 들어오기도 하고(초콜릿·포도·청바지) 우리나라 회사가 다른 나라에 공장을 짓기도 함(라면·초코과자) — 서로 주고받으며 연결 · 문제: 각 나라의 전통적인 생활 양식 약화, 감염병이 빠르게 퍼짐 · 태도: 다른 나라의 생활 양식을 장단점을 따져 받아들이기, 우리 생활 양식 소중히 여기기, 세계 여러 나라의 문제를 함께 해결하려는 자세',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C6','soc',3,2,'u1',6,'사회 변화로 달라진 생활 정리 — 저출산·고령화·지능정보화·세계화의 뜻과 달라진 모습, 문제, 대응 방안을 차례로 정리(주제 → 모습 → 문제 → 대응 방안) · 복지 제도·정보 통신 기술·출산율 같은 낱말 · 카드 뉴스·포스터로 나타내기 · 사회 변화로 나타난 문제를 해결하려면 우리 모두 관심을 갖고 함께 노력해야 함',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C7','soc',3,2,'u1',7,'문화의 뜻과 특징 — 문화는 한 사회의 사람들이 지닌 공통의 생활 양식(사람들이 함께 생활하며 만들어지고 오래 전해져 내려오기도 함) · 배고파서 먹기·졸려서 자기처럼 태어날 때부터 하는 행동은 문화가 아님 · 의식주(옷·음식·집), 말과 글, 음악, 미술, 종교, 규범(마땅히 따르고 지켜야 할 생각이나 행동의 기준) 등 · 지역의 환경에 따라 생활 양식이 다양함(추운 곳 털옷, 햇볕 강한 곳 긴 옷) · 각 사회의 문화는 비슷한 점도 있고 다른 점도 있음(새 학년 시작 달, 인사 방법, 공부하는 과목) · 축제는 한 사회의 문화를 잘 드러냄',ARRAY['[4사03-02] 우리 사회에 나타나는 다양한 문화의 모습을 살펴보고, 문화의 다양성을 존중하는 태도를 기른다(차시 머리 주석 기준)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C8','soc',3,2,'u1',8,'우리 사회의 다양한 문화 — 이주민은 다른 지역에서 옮겨 와 사는 사람 · 외국인 이주민 수가 늘어남(111만 명 → 213만 명), 세계화의 영향으로 직장·공부·결혼 등 여러 목적 · 1인 가구는 가족과 같이 살지 않고 혼자 사는 경우, 결혼에 관한 생각 변화·혼자 사는 노인 증가로 늘어남 · 반려동물은 사람과 더불어 살며 친밀감과 안정감을 주는 동물, 반려동물 놀이터·공원·행사가 생김 · 한 동네에 여러 문화가 함께 있음',ARRAY['[4사03-02] 우리 사회에 나타나는 다양한 문화의 모습을 살펴보고, 문화의 다양성을 존중하는 태도를 기른다(차시 머리 주석 기준)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C9','soc',3,2,'u1',9,'다양한 문화 확산의 영향 — 좋은 점과 문제가 함께 나타남 · 외국인 이주민: 세계 여러 나라 문화를 경험할 기회가 늘어남 / 종교·언어·피부색이 다르다는 까닭으로 부당한 대우, 편견과 차별 · 1인 가구: 작은 가전제품·적은 양 포장 상품·장보기 등을 대신하는 활동 / 외로움·불안함, 도움을 청할 사람이 없음 · 반려동물: 마음의 안정, 수의사·훈련사·미용사 같은 직업 / 소음·배설물·냄새로 이웃 간 갈등(소음이 가장 많음), 버려지는 동물 · 편견은 공정하지 못하고 한쪽으로 치우친 생각, 차별은 편견을 가지고 다르게 대우하는 것',ARRAY['[4사03-02] 우리 사회에 나타나는 다양한 문화의 모습을 살펴보고, 문화의 다양성을 존중하는 태도를 기른다(차시 머리 주석 기준)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C10','soc',3,2,'u1',10,'문제를 해결하려는 노력과 존중하는 태도 — 만화 영화 속 미나는 피부색을 이상하게 여길까 봐 모자를 씀 · 사회의 노력: 한국 생활에 필요한 정보를 다양한 언어로 제공, 국가 인권 위원회(편견과 차별을 막는 제도·기관), 1인 가구 프로그램과 안전 지원, 반려견 산책 때 입마개·목줄, 유니버설 디자인(누구나 쓰기 쉽게 디자인) · 바람직한 태도: 편견을 갖지 않고 차별하지 않기, 다른 문화의 사람들이 겪는 어려움에 관심, 서로 다름을 인정하고 존중 — 바람직하지 못한 태도(무시·경계, 이상하게 여기기, 비난)가 하나라도 있으면 안 됨',ARRAY['[4사03-02] 우리 사회에 나타나는 다양한 문화의 모습을 살펴보고, 문화의 다양성을 존중하는 태도를 기른다(차시 머리 주석 기준)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u1-C11','soc',3,2,'u1',11,'다양한 문화에 대한 이해와 존중 정리 — 문화·이주민·1인 가구·반려동물·편견과 차별에 관한 설명이 알맞은지 가리기 · 축제 초대장 만들기: 주제 정하기 → 프로그램 계획 → 내용과 장소 정하기 → 초청하는 글 쓰기 · 이주민·1인 가구·반려동물 축제 프로그램 · 다양한 문화를 대할 때는 서로 다름을 인정하고 존중',ARRAY['[4사03-02] 우리 사회에 나타나는 다양한 문화의 모습을 살펴보고, 문화의 다양성을 존중하는 태도를 기른다(차시 머리 주석 기준)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X01','soc',3,'u1',ARRAY['SO3-2-u1-C1']::text[],'사회의 모습은 한번 정해지면 변하지 않는다고, 또는 사라지거나 생기는 것 가운데 한쪽만 있다고 여긴다','사라지고 · 생기고 · 바뀌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X02','soc',3,'u1',ARRAY['SO3-2-u1-C1']::text[],'사회가 변하는 원인을 한 가지로만 보거나, 사회와 관계없는 일(해가 뜨는 것 등)을 원인으로 여긴다','사람 수 · 수명 · 생각 · 기술 · 교류') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X03','soc',3,'u1',ARRAY['SO3-2-u1-C1']::text[],'옛날과 오늘날의 학교·생활 모습을 바꾸어 안다(옛날에 급식을 먹었다고 여기는 등)','옛날 도시락 · 오늘날 급식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X04','soc',3,'u1',ARRAY['SO3-2-u1-C2']::text[],'저출산의 뜻을 거꾸로 안다(태어나는 아이의 수가 늘어나는 현상으로 여기는 등)','태어나는 아이가 줄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X05','soc',3,'u1',ARRAY['SO3-2-u1-C2','SO3-2-u1-C3']::text[],'그래프·그림 자료를 잘못 읽는다(가로·세로·단위를 헷갈리거나, 거의 같으면 변하지 않았다고 여기는 등)','제목 · 가로 · 세로 · 단위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X06','soc',3,'u1',ARRAY['SO3-2-u1-C2']::text[],'저출산이 계속될 때 달라지는 모습을 거꾸로 안다(학생 수나 일할 사람이 늘어난다고 여기는 등)','학생 수 · 일할 사람이 줄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X07','soc',3,'u1',ARRAY['SO3-2-u1-C2']::text[],'저출산 문제를 해결하려는 노력을 잘못 안다(학교 문을 닫는 것을 노력으로 여기는 등)','지원 · 보육 시설 · 쉴 수 있는 제도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X08','soc',3,'u1',ARRAY['SO3-2-u1-C3']::text[],'고령화를 노인의 수만 늘어나는 것으로, 또는 노인의 비율이 낮아지는 것으로 여긴다','전체에서 노인이 차지하는 비율이 높아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X09','soc',3,'u1',ARRAY['SO3-2-u1-C3']::text[],'사람들이 오래 살게 된 까닭을 잘못 안다','의학 기술 · 깨끗한 환경') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X10','soc',3,'u1',ARRAY['SO3-2-u1-C3']::text[],'고령화로 달라진 모습이나 대비하려는 노력을 거꾸로 안다(노인을 위한 시설이 줄어든다고 여기는 등)','시설 · 프로그램 · 일자리가 늘어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X11','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'정보 통신 기술·인공지능·지능정보화의 뜻을 서로 바꾸어 안다','주고받는 기술 · 생각하는 컴퓨터 · 넓은 영향') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X12','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'지능정보화로 편리해진 점과 생겨난 문제를 바꾸어 짝짓는다','누려요 · 보완해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X13','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'지능정보화를 한쪽으로만 본다(편리하니 문제는 걱정 없다, 또는 문제가 있으니 아예 쓰지 말자)','장점은 누리고 단점은 보완해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X14','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'인터넷·태블릿 컴퓨터를 쓸 때 지킬 점을 잘못 안다(개인 정보를 올리거나 정보를 그대로 믿는 등)','개인 정보 · 비판하며 · 규칙대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X15','soc',3,'u1',ARRAY['SO3-2-u1-C5']::text[],'세계화의 뜻을 잘못 안다(다른 나라 물건을 사기만 하는 것, 한 나라하고만 교류하는 것으로 여기는 등)','여러 나라가 하나로 연결돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X16','soc',3,'u1',ARRAY['SO3-2-u1-C5']::text[],'세계화로 다른 나라에서 들어오기만 한다고 여겨, 우리나라가 다른 나라에 영향을 주는 모습(한류·공장)을 놓친다','들어오고 나가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X17','soc',3,'u1',ARRAY['SO3-2-u1-C5']::text[],'세계화로 생긴 문제나 대응 태도를 잘못 안다(다른 나라 생활 양식을 무조건 따르거나 모두 거부하는 등)','장단점을 따져 받아들여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X18','soc',3,'u1',ARRAY['SO3-2-u1-C6','SO3-2-u1-C2','SO3-2-u1-C3','SO3-2-u1-C4','SO3-2-u1-C5']::text[],'저출산·고령화·지능정보화·세계화의 뜻이나 모습을 서로 바꾸어 짝짓는다','아이 · 노인 · 인공지능 · 여러 나라') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X19','soc',3,'u1',ARRAY['SO3-2-u1-C6']::text[],'사회 변화로 생긴 문제는 나라만 해결하면 되고 우리와는 관계없다고 여긴다','모두 관심을 갖고 함께 노력해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X20','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'배고파서 먹기·졸려서 자기처럼 태어날 때부터 하는 행동을 문화라고 여긴다','함께 만든 공통의 생활 양식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X21','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'문화를 의식주만으로 좁게 보거나, 의식주·규범 같은 낱말의 뜻을 바꾸어 안다','말과 글 · 음악 · 종교 · 규범도 문화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X22','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'다른 사회의 문화는 잘못되었다고, 또는 모든 사회의 문화가 똑같다고 여겨 비슷한 점과 다른 점을 놓친다','비슷한 점도 있고 다른 점도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X23','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'지역의 환경에 따라 생활 양식이 달라진다는 점을 놓친다','추운 곳 · 더운 곳 · 햇볕 강한 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X24','soc',3,'u1',ARRAY['SO3-2-u1-C8']::text[],'이주민·1인 가구·반려동물의 뜻을 서로 바꾸어 안다','옮겨 와 사는 사람 · 혼자 사는 집 · 더불어 사는 동물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X25','soc',3,'u1',ARRAY['SO3-2-u1-C8']::text[],'우리 사회의 다양한 문화가 늘어난 까닭이나 변화를 거꾸로 안다(1인 가구가 줄어든다고 여기는 등)','늘어나고 있어요 · 까닭이 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X26','soc',3,'u1',ARRAY['SO3-2-u1-C9']::text[],'다양한 문화가 확산된 영향을 한쪽으로만 본다(좋은 점만 있다, 또는 문제가 있는 문화는 없애야 한다)','밝은 면과 그늘 면이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X27','soc',3,'u1',ARRAY['SO3-2-u1-C9']::text[],'편견과 차별의 뜻을 바꾸어 안다(편견을 행동으로, 차별을 생각으로 여기는 등)','편견은 생각 · 차별은 행동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X28','soc',3,'u1',ARRAY['SO3-2-u1-C9']::text[],'다양한 문화가 확산된 영향을 사람들(이주민·1인 가구·반려동물과 함께 사는 사람)과 잘못 짝짓는다','누구와 관계있는 모습일까요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X29','soc',3,'u1',ARRAY['SO3-2-u1-C10']::text[],'문제를 해결하려는 사회의 노력을 잘못 알거나, 노력이 필요 없다고 여긴다','다양한 언어 · 인권 위원회 · 유니버설 디자인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X30','soc',3,'u1',ARRAY['SO3-2-u1-C10']::text[],'다른 문화를 무시하거나 이상하게 여기는 바람직하지 못한 태도를 괜찮다고 여긴다','하나라도 있으면 탑이 기울어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X31','soc',3,'u1',ARRAY['SO3-2-u1-C10']::text[],'다양한 문화를 대할 때 우리 문화만 소중히 여기고 다른 문화는 낮추어 본다','서로 다름을 인정하고 존중해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u1-X32','soc',3,'u1',ARRAY['SO3-2-u1-C11']::text[],'축제 초대장 만들기 차례나 축제 프로그램을 잘못 짝짓는다','주제 → 프로그램 → 내용·장소 → 초청 글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_basic#1','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',1,'mc','auto','사회의 모습에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X01']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"mc","stem":"사회의 모습에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"사회의 모습은 끊임없이 변해요","correct":true},{"t":"사회의 모습은 언제나 똑같아요","mis":"SO3-2-u1-X01"},{"t":"사회의 모습은 사라지기만 해요","mis":"SO3-2-u1-X01"},{"t":"사회의 모습은 새로 생기기만 해요","mis":"SO3-2-u1-X01"}],"explanation":["옛날과 오늘을 견줘요.","모습이 달라졌어요.","끊임없이 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_basic#2','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',1,'sa','auto','옛날에는 초등학교를 「○○학교」라고 불렀어요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"sa","stem":"옛날에는 초등학교를 「○○학교」라고 불렀어요. ○○에 알맞은 두 글자를 쓰세요.","answer":["국민"],"explanation":["지금 이름과 달라요.","◯민학교예요.","국민학교예요."],"mis":"SO3-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_basic#3','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',1,'ox','auto','옛날 학교에서는 점심시간에 도시락을 먹었어요.',ARRAY['SO3-2-u1-X03']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"ox","stem":"옛날 학교에서는 점심시간에 도시락을 먹었어요.","answer":"O","reason_options":[{"t":"옛날에는 집에서 싸 온 도시락을 먹었고, 오늘날에는 급식을 먹기 때문에","correct":true},{"t":"옛날에도 오늘날처럼 급식을 먹었기 때문에","mis":"SO3-2-u1-X03"}],"mis":"SO3-2-u1-X03","explanation":["신문 기사를 봐요.","집에서 싸 왔어요.","그래서 O예요."],"asset":{"type":"passage","lines":["학생은 많고 교실은 부족했다.","1학년부터 4학년까지는 오전반, 오후반으로 나누어 수업했다.","점심시간에는 집에서 싸 온 도시락을 먹었다.","학교 이름은 국민학교였다."],"title":"옛날 신문 기사 속 학교(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_basic#4','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',1,'mc','auto','우리 사회가 변하는 원인으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"mc","stem":"우리 사회가 변하는 원인으로 알맞은 것은 무엇인가요?","options":[{"t":"과학 기술의 발달","correct":true},{"t":"해가 뜨고 지는 것","mis":"SO3-2-u1-X02"},{"t":"달력이 넘어가는 것","mis":"SO3-2-u1-X02"},{"t":"학교 종이 울리는 것","mis":"SO3-2-u1-X02"}],"explanation":["생활을 바꾸는 일이에요.","새 기계가 생겨요.","과학 기술의 발달이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_basic#5','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',2,'mc','auto','옛날 학교에서 오전반과 오후반으로 나누어 수업한 까닭은 무엇인가요?',ARRAY['SO3-2-u1-X03']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"mc","stem":"옛날 학교에서 오전반과 오후반으로 나누어 수업한 까닭은 무엇인가요?","options":[{"t":"학생은 많고 교실은 부족했기 때문이에요","correct":true},{"t":"학생이 너무 적었기 때문이에요","mis":"SO3-2-u1-X03"},{"t":"선생님이 오전에만 일했기 때문이에요","mis":"SO3-2-u1-X03"},{"t":"급식을 두 번 먹으려고요","mis":"SO3-2-u1-X03"}],"explanation":["학생이 많았어요.","교실이 모자랐어요.","나누어 썼어요."],"asset":{"type":"passage","lines":["학생은 많고 교실은 부족했다.","1학년부터 4학년까지는 오전반, 오후반으로 나누어 수업했다.","점심시간에는 집에서 싸 온 도시락을 먹었다.","학교 이름은 국민학교였다."],"title":"옛날 신문 기사 속 학교(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_basic#6','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',2,'match','auto','거리의 달라진 모습과 그 원인을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"match","stem":"거리의 달라진 모습과 그 원인을 알맞게 이으세요.","pairs":[{"l":"학생이 줄어 문을 닫는 학교","r":"사람 수의 변화"},{"l":"새로 생긴 노인 복지관","r":"평균 수명의 증가"},{"l":"사람 대신 청소하는 로봇","r":"과학 기술의 발달"},{"l":"세계 여러 음식 가게","r":"다른 나라와의 교류"}],"mis":"SO3-2-u1-X02","explanation":["어린이가 줄었어요.","오래 살게 됐어요.","기술과 교류도 있어요."],"asset":{"type":"passage","lines":["㉠ 학교 — 학생이 가득했는데, 이제는 학생이 줄어 문을 닫는 학교도 있다.","㉡ 동네 쉼터 — 노인 복지관이 드물었는데, 새로 한 곳이 더 생겼다.","㉢ 집 안 — 사람이 손으로 청소했는데, 이제는 로봇이 청소한다.","㉣ 음식 거리 — 우리 음식 가게만 있었는데, 세계 여러 음식 가게가 많아졌다."],"title":"옛 거리와 오늘 거리 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_basic#7','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',2,'blank','auto','사회 곳곳에는 사라지는 모습도 있고, 새롭게 (    ) 모습도 있으며, 다른 모습으로 바뀌는 모습도 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X01']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"blank","stem":"사회 곳곳에는 사라지는 모습도 있고, 새롭게 (    ) 모습도 있으며, 다른 모습으로 바뀌는 모습도 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"생기는","correct":true},{"t":"멈추는","mis":"SO3-2-u1-X01"},{"t":"숨는","mis":"SO3-2-u1-X01"},{"t":"똑같은","mis":"SO3-2-u1-X01"}],"explanation":["사라지는 것의 반대예요.","새롭게 ◯◯는 모습이에요.","생기는이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_basic#8','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',2,'mc','auto','일기 속 옛날 교실과 오늘날 교실을 견준 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X01','SO3-2-u1-X03']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"mc","stem":"일기 속 옛날 교실과 오늘날 교실을 견준 것으로 알맞은 것은 무엇인가요?","options":[{"t":"옛날에는 교실 난로에 넣을 기름을 받아 왔지만 오늘날에는 그러지 않아요","correct":true},{"t":"옛날과 오늘날 교실은 똑같아요","mis":"SO3-2-u1-X01"},{"t":"오늘날에도 칠판 글씨를 모두 공책에 옮겨 써야 해요","mis":"SO3-2-u1-X03"},{"t":"옛날 교실에는 칠판이 없었어요","mis":"SO3-2-u1-X03"}],"explanation":["난로가 있었어요.","기름을 받아 왔어요.","오늘날과 달라요."],"asset":{"type":"passage","lines":["아침에 교실 난로에 넣을 기름을 받아 왔다.","칠판을 꽉 채운 분필 글씨를 공책에 옮겨 썼다."],"title":"옛날 어느 초등학생의 일기(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_basic#9','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',2,'ox','auto','사람들의 생각이 변하는 것도 사회를 바꾸는 원인이에요.',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"ox","stem":"사람들의 생각이 변하는 것도 사회를 바꾸는 원인이에요.","answer":"O","reason_options":[{"t":"눈에 바로 보이지 않을 뿐 사람들의 생각 변화도 생활 모습을 바꾸기 때문에","correct":true},{"t":"사회를 바꾸는 원인은 눈에 보이는 기계뿐이기 때문에","mis":"SO3-2-u1-X02"}],"mis":"SO3-2-u1-X02","explanation":["보이지 않는 원인도 있어요.","생각도 바뀌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_basic#10','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',3,'error','auto','달라진 사회 모습을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"error","stem":"달라진 사회 모습을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「사회는 과학 기술 하나 때문에만 변해.」","correct":true,"mis_target":"SO3-2-u1-X02"},{"t":"친구 가 — 「어린이 수가 줄어 문을 닫는 학교가 있어.」","mis":"SO3-2-u1-X02"},{"t":"친구 나 — 「다른 나라와 교류해서 세계 음식 가게가 늘었어.」","mis":"SO3-2-u1-X02"}],"explanation":["원인은 여러 가지예요.","하나만이 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_challenge#1','soc',3,2,'u1','L01','g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',2,'sa','auto','사람들이 예전보다 오래 살게 된 것을 「평균 ○○의 증가」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"sa","stem":"사람들이 예전보다 오래 살게 된 것을 「평균 ○○의 증가」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["수명"],"explanation":["얼마나 오래 사는지예요.","◯명이에요.","수명이에요."],"mis":"SO3-2-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_challenge#2','soc',3,2,'u1','L01','g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',2,'ox','auto','원생이 부족해 문을 닫는 어린이집이 많아진 것은 사람 수의 변화와 관계있어요.',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"ox","stem":"원생이 부족해 문을 닫는 어린이집이 많아진 것은 사람 수의 변화와 관계있어요.","answer":"O","reason_options":[{"t":"어린이의 수가 줄어 어린이집에 다닐 아이가 적어졌기 때문에","correct":true},{"t":"어린이집이 너무 많이 생겼기 때문에","mis":"SO3-2-u1-X02"}],"mis":"SO3-2-u1-X02","explanation":["어린이가 줄었어요.","다닐 아이가 적어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_challenge#3','soc',3,2,'u1','L01','g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',3,'mc','auto','자료의 ㉡처럼 노인 복지관이 새로 생긴 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"mc","stem":"자료의 ㉡처럼 노인 복지관이 새로 생긴 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"사람들이 예전보다 오래 살게 되어 노인이 많아졌기 때문이에요","correct":true},{"t":"어린이가 많아졌기 때문이에요","mis":"SO3-2-u1-X02"},{"t":"로봇이 발달했기 때문이에요","mis":"SO3-2-u1-X02"},{"t":"다른 나라 음식이 들어왔기 때문이에요","mis":"SO3-2-u1-X02"}],"explanation":["노인이 이용해요.","노인이 많아졌어요.","오래 살게 됐어요."],"asset":{"type":"passage","lines":["㉠ 학교 — 학생이 가득했는데, 이제는 학생이 줄어 문을 닫는 학교도 있다.","㉡ 동네 쉼터 — 노인 복지관이 드물었는데, 새로 한 곳이 더 생겼다.","㉢ 집 안 — 사람이 손으로 청소했는데, 이제는 로봇이 청소한다.","㉣ 음식 거리 — 우리 음식 가게만 있었는데, 세계 여러 음식 가게가 많아졌다."],"title":"옛 거리와 오늘 거리 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_challenge#4','soc',3,2,'u1','L01','g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',3,'mc','auto','자료의 네 곳 가운데 있던 모습이 「사라지는」 쪽에 가장 가까운 곳은 어디인가요?',ARRAY['SO3-2-u1-X01']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"mc","stem":"자료의 네 곳 가운데 있던 모습이 「사라지는」 쪽에 가장 가까운 곳은 어디인가요?","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"SO3-2-u1-X01"},{"t":"㉢","mis":"SO3-2-u1-X01"},{"t":"㉣","mis":"SO3-2-u1-X01"}],"explanation":["문을 닫아요.","사라지는 모습이에요.","㉠이에요."],"asset":{"type":"passage","lines":["㉠ 학교 — 학생이 가득했는데, 이제는 학생이 줄어 문을 닫는 학교도 있다.","㉡ 동네 쉼터 — 노인 복지관이 드물었는데, 새로 한 곳이 더 생겼다.","㉢ 집 안 — 사람이 손으로 청소했는데, 이제는 로봇이 청소한다.","㉣ 음식 거리 — 우리 음식 가게만 있었는데, 세계 여러 음식 가게가 많아졌다."],"title":"옛 거리와 오늘 거리 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_challenge#5','soc',3,2,'u1','L01','g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',3,'mc','auto','자료의 네 곳을 바꾼 원인을 모두 짝지었는데도 남는 원인이 있어요. 그림에 바로 보이지 않지만 사회를 바꾸는 그 원인은 무엇인가요?',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"mc","stem":"자료의 네 곳을 바꾼 원인을 모두 짝지었는데도 남는 원인이 있어요. 그림에 바로 보이지 않지만 사회를 바꾸는 그 원인은 무엇인가요?","options":[{"t":"사람들의 생각 변화","correct":true},{"t":"사람 수의 변화","mis":"SO3-2-u1-X02"},{"t":"과학 기술의 발달","mis":"SO3-2-u1-X02"},{"t":"다른 나라와의 교류","mis":"SO3-2-u1-X02"}],"explanation":["네 곳에 쓰인 원인을 빼요.","눈에 보이지 않아요.","생각 변화예요."],"asset":{"type":"passage","lines":["㉠ 학교 — 학생이 가득했는데, 이제는 학생이 줄어 문을 닫는 학교도 있다.","㉡ 동네 쉼터 — 노인 복지관이 드물었는데, 새로 한 곳이 더 생겼다.","㉢ 집 안 — 사람이 손으로 청소했는데, 이제는 로봇이 청소한다.","㉣ 음식 거리 — 우리 음식 가게만 있었는데, 세계 여러 음식 가게가 많아졌다."],"title":"옛 거리와 오늘 거리 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_challenge#6','soc',3,2,'u1','L01','g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',3,'error','auto','옛날 학교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X03']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"error","stem":"옛날 학교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「옛날 학교는 교실이 남고 학생이 모자랐대.」","correct":true,"mis_target":"SO3-2-u1-X03"},{"t":"친구 가 — 「옛날에는 오전반, 오후반이 있었대.」","mis":"SO3-2-u1-X03"},{"t":"친구 다 — 「옛날에는 도시락을 싸 갔대.」","mis":"SO3-2-u1-X03"}],"explanation":["학생이 많았어요.","교실이 모자랐어요.","친구 나가 거꾸로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_challenge#7','soc',3,2,'u1','L01','g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',3,'ox','auto','실제 사회 변화는 한 가지 원인만으로 일어나요.',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"ox","stem":"실제 사회 변화는 한 가지 원인만으로 일어나요.","answer":"X","reason_options":[{"t":"실제로는 여러 원인이 함께 얽혀 일어나기 때문에","correct":true},{"t":"사회는 언제나 원인 하나로만 바뀌기 때문에","mis":"SO3-2-u1-X02"}],"mis":"SO3-2-u1-X02","explanation":["원인이 얽혀 있어요.","여러 가지예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_challenge#8','soc',3,2,'u1','L01','g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',4,'mc','auto','오늘 공부한 사회의 변화를 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X01','SO3-2-u1-X02']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C1","difficulty":4,"kind":"mc","stem":"오늘 공부한 사회의 변화를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"여러 원인으로 사회가 변하고, 사회가 변하면서 사람들의 생활 모습도 달라져요","correct":true},{"t":"사회의 모습은 한번 정해지면 달라지지 않아요","mis":"SO3-2-u1-X01"},{"t":"사회는 과학 기술 하나 때문에만 변해요","mis":"SO3-2-u1-X02"},{"t":"사회가 변해도 생활 모습은 그대로예요","mis":"SO3-2-u1-X01"}],"explanation":["원인이 여러 가지예요.","사회가 변해요.","생활도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_challenge#9','soc',3,2,'u1','L01','g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',4,'mc','auto','옛날 학교에는 학생이 넘쳤는데 오늘날에는 학생이 줄어 문을 닫는 학교가 있어요. 두 모습을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X01','SO3-2-u1-X02','SO3-2-u1-X03']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C1","difficulty":4,"kind":"mc","stem":"옛날 학교에는 학생이 넘쳤는데 오늘날에는 학생이 줄어 문을 닫는 학교가 있어요. 두 모습을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"사람 수가 변하면서 학교의 모습도 달라졌어요","correct":true},{"t":"학교의 모습은 변하지 않았어요","mis":"SO3-2-u1-X01"},{"t":"학교가 줄어든 까닭은 로봇 때문이에요","mis":"SO3-2-u1-X02"},{"t":"옛날 학교와 오늘날 학교는 관계가 없어요","mis":"SO3-2-u1-X03"}],"explanation":["학생 수가 달라졌어요.","사람 수의 변화예요.","학교도 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L01_challenge#10','soc',3,2,'u1','L01','g3_2_soc_u1_L01_challenge','lesson_challenge','SO3-2-u1-C1',4,'essay','teacher','자료의 네 곳 가운데 한 곳을 골라 옛 모습과 오늘 모습을 견주어 쓰고, 그렇게 달라진 원인을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C1","difficulty":4,"kind":"essay","stem":"자료의 네 곳 가운데 한 곳을 골라 옛 모습과 오늘 모습을 견주어 쓰고, 그렇게 달라진 원인을 쓰세요.","answer_guide":{"answer":"예: ㉣ 음식 거리는 옛날에는 우리 음식 가게만 있었는데, 오늘날에는 세계 여러 음식을 파는 가게가 많아졌어요. 다른 나라와의 교류가 활발해졌기 때문이에요.","scoring_points":["한 곳을 골랐는가","옛 모습과 오늘 모습을 견주었는가","알맞은 원인을 썼는가"]},"explanation":["한 곳을 골라요.","옛날과 오늘을 견줘요.","원인을 써요."],"asset":{"type":"passage","lines":["㉠ 학교 — 학생이 가득했는데, 이제는 학생이 줄어 문을 닫는 학교도 있다.","㉡ 동네 쉼터 — 노인 복지관이 드물었는데, 새로 한 곳이 더 생겼다.","㉢ 집 안 — 사람이 손으로 청소했는데, 이제는 로봇이 청소한다.","㉣ 음식 거리 — 우리 음식 가게만 있었는데, 세계 여러 음식 가게가 많아졌다."],"title":"옛 거리와 오늘 거리 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_basic#1','soc',3,2,'u1','L02','g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',1,'mc','auto','태어나는 아이의 수가 줄어들어 출산율이 감소하는 현상을 무엇이라고 하나요?',ARRAY['SO3-2-u1-X04']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"mc","stem":"태어나는 아이의 수가 줄어들어 출산율이 감소하는 현상을 무엇이라고 하나요?","options":[{"t":"저출산","correct":true},{"t":"출산율","mis":"SO3-2-u1-X04"},{"t":"교류","mis":"SO3-2-u1-X04"},{"t":"평균 수명","mis":"SO3-2-u1-X04"}],"explanation":["아이가 줄어요.","낳는 아이가 적어요.","저출산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_basic#2','soc',3,2,'u1','L02','g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',1,'sa','auto','그래프에서 가로는 무엇을 나타내나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"sa","stem":"그래프에서 가로는 무엇을 나타내나요? 두 글자로 쓰세요.","answer":["연도"],"explanation":["아래쪽 줄을 봐요.","몇 년인지예요.","연도예요."],"asset":{"type":"passage","lines":["1970년 101 · 1980년 86 · 1990년 65","2000년 64 · 2010년 47 · 2020년 27","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"title":"우리나라에서 연도별 태어나는 아이의 수"},"mis":"SO3-2-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_basic#3','soc',3,2,'u1','L02','g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',1,'ox','auto','저출산이 계속되면 학생 수가 줄어들어요.',ARRAY['SO3-2-u1-X06']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"ox","stem":"저출산이 계속되면 학생 수가 줄어들어요.","answer":"O","reason_options":[{"t":"태어나는 아이가 줄면 학교에 다닐 어린이도 줄어들기 때문에","correct":true},{"t":"아이가 줄어도 학생 수는 늘어나기 때문에","mis":"SO3-2-u1-X06"}],"mis":"SO3-2-u1-X06","explanation":["아이가 줄어요.","학교에 다닐 어린이도 줄어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_basic#4','soc',3,2,'u1','L02','g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',1,'mc','auto','그래프에서 1970년에 태어난 아이의 수는 몇 명인가요?',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"mc","stem":"그래프에서 1970년에 태어난 아이의 수는 몇 명인가요?","options":[{"t":"101만 명","correct":true},{"t":"101명","mis":"SO3-2-u1-X05"},{"t":"27만 명","mis":"SO3-2-u1-X05"},{"t":"86만 명","mis":"SO3-2-u1-X05"}],"explanation":["1970년을 찾아요.","단위는 만 명이에요.","101만 명이에요."],"asset":{"type":"passage","lines":["1970년 101 · 1980년 86 · 1990년 65","2000년 64 · 2010년 47 · 2020년 27","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"title":"우리나라에서 연도별 태어나는 아이의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_basic#5','soc',3,2,'u1','L02','g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',2,'mc','auto','그래프를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X04','SO3-2-u1-X05']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"mc","stem":"그래프를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"태어나는 아이의 수가 점점 줄어들고 있어요","correct":true},{"t":"태어나는 아이의 수가 점점 늘어나고 있어요","mis":"SO3-2-u1-X04"},{"t":"태어나는 아이의 수는 변하지 않았어요","mis":"SO3-2-u1-X05"},{"t":"1990년부터 다시 늘어났어요","mis":"SO3-2-u1-X05"}],"explanation":["앞에서 뒤로 읽어요.","수가 작아져요.","줄어들고 있어요."],"asset":{"type":"passage","lines":["1970년 101 · 1980년 86 · 1990년 65","2000년 64 · 2010년 47 · 2020년 27","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"title":"우리나라에서 연도별 태어나는 아이의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_basic#6','soc',3,2,'u1','L02','g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',2,'mc','auto','그래프에서 1990년과 2000년을 견주면 어떻게 되었나요?',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"mc","stem":"그래프에서 1990년과 2000년을 견주면 어떻게 되었나요?","options":[{"t":"1만 명 줄었어요","correct":true},{"t":"변하지 않았어요","mis":"SO3-2-u1-X05"},{"t":"1만 명 늘었어요","mis":"SO3-2-u1-X05"},{"t":"10만 명 줄었어요","mis":"SO3-2-u1-X05"}],"explanation":["65와 64예요.","거의 같아 보여요.","1만 명 줄었어요."],"asset":{"type":"passage","lines":["1970년 101 · 1980년 86 · 1990년 65","2000년 64 · 2010년 47 · 2020년 27","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"title":"우리나라에서 연도별 태어나는 아이의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_basic#7','soc',3,2,'u1','L02','g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',2,'blank','auto','오늘날에는 결혼하지 않거나 아이를 낳아 기르는 것에 (    )을 느끼는 사람이 많아지면서 저출산 현상이 나타나고 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X04']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"blank","stem":"오늘날에는 결혼하지 않거나 아이를 낳아 기르는 것에 (    )을 느끼는 사람이 많아지면서 저출산 현상이 나타나고 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"부담","correct":true},{"t":"기쁨만","mis":"SO3-2-u1-X04"},{"t":"재미","mis":"SO3-2-u1-X04"},{"t":"배고픔","mis":"SO3-2-u1-X04"}],"explanation":["힘들게 느끼는 마음이에요.","짐처럼 느껴요.","부담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_basic#8','soc',3,2,'u1','L02','g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',2,'match','auto','저출산 문제를 해결하려는 노력과 그 노력이 도와주는 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"match","stem":"저출산 문제를 해결하려는 노력과 그 노력이 도와주는 점을 알맞게 이으세요.","pairs":[{"l":"가. 돈과 물품 지원","r":"아이를 키우는 데 드는 돈을 덜어 줘요"},{"l":"나. 보육 시설 운영","r":"아이를 믿고 맡길 수 있게 해 줘요"},{"l":"다. 일을 쉴 수 있는 제도","r":"부모가 아이와 함께 지낼 수 있게 해 줘요"}],"mis":"SO3-2-u1-X07","explanation":["돈을 덜어 줘요.","맡길 곳이에요.","함께 지낼 시간이에요."],"asset":{"type":"passage","lines":["가. 아이를 낳고 키우는 데 필요한 돈과 물품 등을 지원해요.","나. 안전하고 쾌적한 보육 시설을 만들고 운영해요.","다. 부모가 자녀를 키우려고 일정 기간 일을 쉴 수 있는 제도를 운영해요."],"title":"저출산 문제를 해결하려는 노력 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_basic#9','soc',3,2,'u1','L02','g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',2,'ox','auto','저출산 문제를 해결하려면 문을 닫는 학교를 더 늘려야 해요.',ARRAY['SO3-2-u1-X07']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"ox","stem":"저출산 문제를 해결하려면 문을 닫는 학교를 더 늘려야 해요.","answer":"X","reason_options":[{"t":"학교 문을 닫는 것은 저출산으로 나타난 모습이지 해결하려는 노력이 아니기 때문에","correct":true},{"t":"학교가 줄어야 아이가 늘어나기 때문에","mis":"SO3-2-u1-X07"}],"mis":"SO3-2-u1-X07","explanation":["학교 문을 닫는 건 결과예요.","노력이 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_basic#10','soc',3,2,'u1','L02','g3_2_soc_u1_L02_basic','lesson_basic','SO3-2-u1-C2',3,'error','auto','저출산을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X06','SO3-2-u1-X04','SO3-2-u1-X07']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"error","stem":"저출산을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「저출산이 계속되면 일할 수 있는 사람이 늘어날 거야.」","correct":true,"mis_target":"SO3-2-u1-X06"},{"t":"친구 나 — 「태어나는 아이의 수가 줄어드는 현상이야.」","mis":"SO3-2-u1-X04"},{"t":"친구 다 — 「보육 시설을 만들어 해결하려고 노력해.」","mis":"SO3-2-u1-X07"}],"explanation":["아이가 줄면 어떻게 될까요?","일할 사람도 줄어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_challenge#1','soc',3,2,'u1','L02','g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',2,'sa','auto','여성 한 명이 낳을 것으로 예상되는 평균적인 아이의 수로 알 수 있는 것은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"sa","stem":"여성 한 명이 낳을 것으로 예상되는 평균적인 아이의 수로 알 수 있는 것은 무엇인가요? 세 글자로 쓰세요.","answer":["출산율"],"explanation":["아이를 낳는 정도예요.","출산◯이에요.","출산율이에요."],"mis":"SO3-2-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_challenge#2','soc',3,2,'u1','L02','g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',2,'ox','auto','그래프에서 1990년과 2000년은 거의 같아 보이니 태어나는 아이의 수가 줄지 않은 거예요.',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"ox","stem":"그래프에서 1990년과 2000년은 거의 같아 보이니 태어나는 아이의 수가 줄지 않은 거예요.","answer":"X","reason_options":[{"t":"거의 같아 보여도 2000년이 1만 명 적어 줄어든 것이기 때문에","correct":true},{"t":"막대 길이가 비슷하면 늘어난 것이기 때문에","mis":"SO3-2-u1-X05"}],"mis":"SO3-2-u1-X05","explanation":["65와 64를 견줘요.","조금 줄었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["1970년 101 · 1980년 86 · 1990년 65","2000년 64 · 2010년 47 · 2020년 27","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"title":"우리나라에서 연도별 태어나는 아이의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_challenge#3','soc',3,2,'u1','L02','g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',3,'mc','auto','그래프에서 바로 옆 해끼리 견주었을 때 늘어난 쌍은 몇 쌍인가요?',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"mc","stem":"그래프에서 바로 옆 해끼리 견주었을 때 늘어난 쌍은 몇 쌍인가요?","options":[{"t":"하나도 없어요","correct":true},{"t":"한 쌍","mis":"SO3-2-u1-X05"},{"t":"두 쌍","mis":"SO3-2-u1-X05"},{"t":"다섯 쌍","mis":"SO3-2-u1-X05"}],"explanation":["다섯 쌍을 견줘요.","모두 뒤의 해가 적어요.","하나도 없어요."],"asset":{"type":"passage","lines":["1970년 101 · 1980년 86 · 1990년 65","2000년 64 · 2010년 47 · 2020년 27","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"title":"우리나라에서 연도별 태어나는 아이의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_challenge#4','soc',3,2,'u1','L02','g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',3,'mc','auto','그래프에서 바로 옆 해끼리 견주었을 때 태어나는 아이의 수가 가장 많이 줄어든 때는 언제와 언제 사이인가요?',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"mc","stem":"그래프에서 바로 옆 해끼리 견주었을 때 태어나는 아이의 수가 가장 많이 줄어든 때는 언제와 언제 사이인가요?","options":[{"t":"1980년과 1990년 사이","correct":true},{"t":"2010년과 2020년 사이","mis":"SO3-2-u1-X05"},{"t":"1990년과 2000년 사이","mis":"SO3-2-u1-X05"},{"t":"1970년과 1980년 사이","mis":"SO3-2-u1-X05"}],"explanation":["차이를 하나씩 세요.","86에서 65로 줄었어요.","21만 명이 줄었어요."],"asset":{"type":"passage","lines":["1970년 101 · 1980년 86 · 1990년 65","2000년 64 · 2010년 47 · 2020년 27","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"title":"우리나라에서 연도별 태어나는 아이의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_challenge#5','soc',3,2,'u1','L02','g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',3,'mc','auto','저출산이 계속될 때 우리 동네에 나타날 수 있는 모습으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X06']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"mc","stem":"저출산이 계속될 때 우리 동네에 나타날 수 있는 모습으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학생이 줄어 문을 닫는 학교가 생겨요","correct":true},{"t":"교실이 모자라 오전반, 오후반이 생겨요","mis":"SO3-2-u1-X06"},{"t":"어린이집에 다닐 아이가 많아져요","mis":"SO3-2-u1-X06"},{"t":"일할 사람이 넘쳐나요","mis":"SO3-2-u1-X06"}],"explanation":["아이가 줄어요.","학생도 줄어요.","학교 모습이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_challenge#6','soc',3,2,'u1','L02','g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',3,'error','auto','저출산 문제를 해결하려는 노력을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X07']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"error","stem":"저출산 문제를 해결하려는 노력을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「세 노력 가운데 「가」만 정답이고 나머지는 쓸모없어.」","correct":true,"mis_target":"SO3-2-u1-X07"},{"t":"친구 가 — 「「나」는 아이를 믿고 맡길 곳을 만들어 줘.」","mis":"SO3-2-u1-X07"},{"t":"친구 나 — 「「다」는 부모가 아이와 함께 지낼 시간을 줘.」","mis":"SO3-2-u1-X07"}],"explanation":["세 노력 모두 도움이 돼요.","하나만 정답이 아니에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["가. 아이를 낳고 키우는 데 필요한 돈과 물품 등을 지원해요.","나. 안전하고 쾌적한 보육 시설을 만들고 운영해요.","다. 부모가 자녀를 키우려고 일정 기간 일을 쉴 수 있는 제도를 운영해요."],"title":"저출산 문제를 해결하려는 노력 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_challenge#7','soc',3,2,'u1','L02','g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',3,'ox','auto','아이를 낳아 기르는 데 드는 부담을 덜어 주는 것은 저출산 문제를 해결하는 데 도움이 될 수 있어요.',ARRAY['SO3-2-u1-X07']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"ox","stem":"아이를 낳아 기르는 데 드는 부담을 덜어 주는 것은 저출산 문제를 해결하는 데 도움이 될 수 있어요.","answer":"O","reason_options":[{"t":"부담 때문에 아이를 낳지 않는 사람이 많아진 것이 저출산의 까닭이기 때문에","correct":true},{"t":"부담은 저출산과 관계가 없기 때문에","mis":"SO3-2-u1-X07"}],"mis":"SO3-2-u1-X07","explanation":["까닭을 떠올려요.","부담을 느꼈어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_challenge#8','soc',3,2,'u1','L02','g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',4,'mc','auto','저출산을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X04','SO3-2-u1-X06','SO3-2-u1-X07']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C2","difficulty":4,"kind":"mc","stem":"저출산을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"태어나는 아이의 수가 줄어 학생 수와 일할 사람이 줄어들고, 우리 사회는 여러 방법으로 이 문제를 해결하려고 노력해요","correct":true},{"t":"태어나는 아이의 수가 늘어나 학교가 모자라요","mis":"SO3-2-u1-X04"},{"t":"저출산은 우리 생활과 관계가 없어요","mis":"SO3-2-u1-X06"},{"t":"저출산 문제는 저절로 해결돼요","mis":"SO3-2-u1-X07"}],"explanation":["뜻을 떠올려요.","생활이 달라져요.","노력하고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_challenge#9','soc',3,2,'u1','L02','g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',4,'mc','auto','그래프의 흐름이 이대로 이어진다면 앞으로의 모습을 짐작한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X06','SO3-2-u1-X05']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C2","difficulty":4,"kind":"mc","stem":"그래프의 흐름이 이대로 이어진다면 앞으로의 모습을 짐작한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학생 수가 더 줄어들어 학교와 어린이집의 모습이 더 달라질 수 있어요","correct":true},{"t":"학생 수가 다시 크게 늘어날 거예요","mis":"SO3-2-u1-X06"},{"t":"그래프는 앞으로와 아무 관계가 없어요","mis":"SO3-2-u1-X05"},{"t":"일할 수 있는 사람이 늘어날 거예요","mis":"SO3-2-u1-X06"}],"explanation":["계속 줄었어요.","앞으로도 줄 수 있어요.","생활이 더 달라져요."],"asset":{"type":"passage","lines":["1970년 101 · 1980년 86 · 1990년 65","2000년 64 · 2010년 47 · 2020년 27","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"title":"우리나라에서 연도별 태어나는 아이의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L02_challenge#10','soc',3,2,'u1','L02','g3_2_soc_u1_L02_challenge','lesson_challenge','SO3-2-u1-C2',4,'essay','teacher','그래프를 읽고 태어나는 아이의 수가 어떻게 변해 왔는지 쓰고, 저출산 문제를 해결하는 데 가장 도움이 된다고 생각하는 노력을 하나 골라 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C2","difficulty":4,"kind":"essay","stem":"그래프를 읽고 태어나는 아이의 수가 어떻게 변해 왔는지 쓰고, 저출산 문제를 해결하는 데 가장 도움이 된다고 생각하는 노력을 하나 골라 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 1970년에는 101만 명이 태어났는데 2020년에는 27만 명이 태어나, 태어나는 아이의 수가 점점 줄어들고 있어요. 나는 안전한 보육 시설을 만드는 노력이 가장 도움이 된다고 생각해요. 아이를 믿고 맡길 곳이 있어야 부모가 아이를 키우는 부담이 줄어들기 때문이에요.","scoring_points":["그래프의 변화를 바르게 썼는가","노력을 하나 골랐는가","고른 까닭을 썼는가"]},"explanation":["처음과 끝을 견줘요.","노력을 골라요.","까닭을 써요."],"asset":{"type":"passage","lines":["1970년 101 · 1980년 86 · 1990년 65","2000년 64 · 2010년 47 · 2020년 27","(가로 — 연도 · 세로 — 태어나는 아이의 수, 단위는 만 명)"],"title":"우리나라에서 연도별 태어나는 아이의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_basic#1','soc',3,2,'u1','L03','g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',1,'mc','auto','교과서에서는 몇 세 이상인 사람을 노인이라고 하나요?',ARRAY['SO3-2-u1-X08']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"mc","stem":"교과서에서는 몇 세 이상인 사람을 노인이라고 하나요?","options":[{"t":"65세 이상","correct":true},{"t":"50세 이상","mis":"SO3-2-u1-X08"},{"t":"80세 이상","mis":"SO3-2-u1-X08"},{"t":"100세 이상","mis":"SO3-2-u1-X08"}],"explanation":["나이를 떠올려요.","60보다 조금 많아요.","65세 이상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_basic#2','soc',3,2,'u1','L03','g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',1,'sa','auto','전체 사람 수에서 노인의 수가 차지하는 비율이 높아지는 현상을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"sa","stem":"전체 사람 수에서 노인의 수가 차지하는 비율이 높아지는 현상을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["고령화"],"explanation":["노인과 관계있어요.","고◯화예요.","고령화예요."],"mis":"SO3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_basic#3','soc',3,2,'u1','L03','g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',1,'ox','auto','오늘날 사람들이 오래 살게 된 까닭은 의학 기술이 발달하고 깨끗한 환경에서 생활하게 되었기 때문이에요.',ARRAY['SO3-2-u1-X09']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"ox","stem":"오늘날 사람들이 오래 살게 된 까닭은 의학 기술이 발달하고 깨끗한 환경에서 생활하게 되었기 때문이에요.","answer":"O","reason_options":[{"t":"병을 더 잘 고치고 더 깨끗한 곳에서 지내게 되었기 때문에","correct":true},{"t":"병원이 줄어들었기 때문에","mis":"SO3-2-u1-X09"}],"mis":"SO3-2-u1-X09","explanation":["병을 잘 고쳐요.","환경이 깨끗해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_basic#4','soc',3,2,'u1','L03','g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',1,'mc','auto','고령화로 달라진 생활 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X10']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"mc","stem":"고령화로 달라진 생활 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"노인 복지관이 새로 생겨요","correct":true},{"t":"노인 복지관이 모두 문을 닫아요","mis":"SO3-2-u1-X10"},{"t":"노인을 위한 프로그램이 사라져요","mis":"SO3-2-u1-X10"},{"t":"일하는 노인을 찾아볼 수 없어요","mis":"SO3-2-u1-X10"}],"explanation":["노인이 많아졌어요.","이용할 곳이 필요해요.","복지관이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_basic#5','soc',3,2,'u1','L03','g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',2,'mc','auto','자료에서 2020년 마을에는 100명 가운데 노인이 몇 명 정도 있나요?',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"mc","stem":"자료에서 2020년 마을에는 100명 가운데 노인이 몇 명 정도 있나요?","options":[{"t":"16명 정도","correct":true},{"t":"4명 정도","mis":"SO3-2-u1-X05"},{"t":"40명 정도","mis":"SO3-2-u1-X05"},{"t":"100명 정도","mis":"SO3-2-u1-X05"}],"explanation":["2020년 줄을 찾아요.","1980년보다 많아요.","16명 정도예요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 노인 4명 정도","2020년 — 100명 가운데 노인 16명 정도","2050년(예상) — 100명 가운데 노인 40명 정도"],"title":"우리나라가 100명이 사는 마을이라면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_basic#6','soc',3,2,'u1','L03','g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',2,'mc','auto','자료를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X08','SO3-2-u1-X05']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"mc","stem":"자료를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"전체 사람 수에서 노인이 차지하는 비율이 점점 높아지고 있어요","correct":true},{"t":"노인이 차지하는 비율이 점점 낮아지고 있어요","mis":"SO3-2-u1-X08"},{"t":"노인의 비율은 변하지 않았어요","mis":"SO3-2-u1-X05"},{"t":"마을의 사람 수가 점점 늘어나고 있어요","mis":"SO3-2-u1-X05"}],"explanation":["세 마을 모두 100명이에요.","노인이 늘었어요.","비율이 높아져요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 노인 4명 정도","2020년 — 100명 가운데 노인 16명 정도","2050년(예상) — 100명 가운데 노인 40명 정도"],"title":"우리나라가 100명이 사는 마을이라면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_basic#7','soc',3,2,'u1','L03','g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',2,'blank','auto','(    )은 일정한 양을 기준으로 어떤 양이 차지하는 정도를 나타낸 것이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X08']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"blank","stem":"(    )은 일정한 양을 기준으로 어떤 양이 차지하는 정도를 나타낸 것이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"비율","correct":true},{"t":"무게","mis":"SO3-2-u1-X08"},{"t":"거리","mis":"SO3-2-u1-X08"},{"t":"나이","mis":"SO3-2-u1-X08"}],"explanation":["차지하는 정도예요.","비◯이에요.","비율이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_basic#8','soc',3,2,'u1','L03','g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',2,'match','auto','고령화와 관련한 모습과 그 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"match","stem":"고령화와 관련한 모습과 그 쓰임을 알맞게 이으세요.","pairs":[{"l":"노인 전문 병원","r":"노인의 건강을 돌봐요"},{"l":"배움 프로그램","r":"노인이 새로운 것을 배워요"},{"l":"알맞은 일자리","r":"일하고 싶은 노인을 도와요"},{"l":"복지 제도","r":"노인의 안정된 생활을 도와요"}],"mis":"SO3-2-u1-X10","explanation":["건강을 돌봐요.","배우고 일해요.","생활을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_basic#9','soc',3,2,'u1','L03','g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',2,'ox','auto','고령화는 노인의 수만 늘어나는 것을 말해요.',ARRAY['SO3-2-u1-X08']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"ox","stem":"고령화는 노인의 수만 늘어나는 것을 말해요.","answer":"X","reason_options":[{"t":"전체 사람 수에서 노인의 수가 차지하는 비율이 높아지는 현상을 말하기 때문에","correct":true},{"t":"노인의 수가 늘면 비율은 늘 그대로이기 때문에","mis":"SO3-2-u1-X08"}],"mis":"SO3-2-u1-X08","explanation":["전체에서 차지하는 정도예요.","비율이 중요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_basic#10','soc',3,2,'u1','L03','g3_2_soc_u1_L03_basic','lesson_basic','SO3-2-u1-C3',3,'error','auto','고령화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X10','SO3-2-u1-X08']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"error","stem":"고령화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「고령화가 되면 노인을 위한 시설이 줄어들어.」","correct":true,"mis_target":"SO3-2-u1-X10"},{"t":"친구 가 — 「노인이 차지하는 비율이 높아지는 거야.」","mis":"SO3-2-u1-X08"},{"t":"친구 다 — 「노인에게 알맞은 일자리를 제공해.」","mis":"SO3-2-u1-X10"}],"explanation":["노인이 많아졌어요.","시설이 늘어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_challenge#1','soc',3,2,'u1','L03','g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',2,'sa','auto','자료에서 2050년(예상) 마을의 100명 가운데 노인이 아닌 사람은 몇 명 정도인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"sa","stem":"자료에서 2050년(예상) 마을의 100명 가운데 노인이 아닌 사람은 몇 명 정도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["100명 가운데 40명이 노인이에요.","100에서 40을 빼요.","60명 정도예요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 노인 4명 정도","2020년 — 100명 가운데 노인 16명 정도","2050년(예상) — 100명 가운데 노인 40명 정도"],"title":"우리나라가 100명이 사는 마을이라면"},"mis":"SO3-2-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_challenge#2','soc',3,2,'u1','L03','g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',2,'ox','auto','자료의 2050년은 예상한 수라서 앞으로 어떻게 변할지 전혀 짐작할 수 없어요.',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"ox","stem":"자료의 2050년은 예상한 수라서 앞으로 어떻게 변할지 전혀 짐작할 수 없어요.","answer":"X","reason_options":[{"t":"앞선 해들의 변화를 바탕으로 노인의 비율이 더 높아질 것을 짐작한 것이기 때문에","correct":true},{"t":"예상한 수는 아무 쓸모가 없기 때문에","mis":"SO3-2-u1-X05"}],"mis":"SO3-2-u1-X05","explanation":["1980년, 2020년을 봐요.","계속 늘었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 노인 4명 정도","2020년 — 100명 가운데 노인 16명 정도","2050년(예상) — 100명 가운데 노인 40명 정도"],"title":"우리나라가 100명이 사는 마을이라면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_challenge#3','soc',3,2,'u1','L03','g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',3,'mc','auto','자료에서 세 마을의 사람 수를 모두 100명으로 똑같이 놓은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X05','SO3-2-u1-X08']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"mc","stem":"자료에서 세 마을의 사람 수를 모두 100명으로 똑같이 놓은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"전체에서 노인이 차지하는 정도를 한눈에 견주어 보려고","correct":true},{"t":"우리나라 사람이 실제로 100명이라서","mis":"SO3-2-u1-X05"},{"t":"노인의 수만 세려고","mis":"SO3-2-u1-X08"},{"t":"마을을 예쁘게 그리려고","mis":"SO3-2-u1-X05"}],"explanation":["기준을 같게 했어요.","견주기 쉬워요.","차지하는 정도를 봐요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 노인 4명 정도","2020년 — 100명 가운데 노인 16명 정도","2050년(예상) — 100명 가운데 노인 40명 정도"],"title":"우리나라가 100명이 사는 마을이라면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_challenge#4','soc',3,2,'u1','L03','g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',3,'mc','auto','고령화가 나타나는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X08','SO3-2-u1-X09']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"mc","stem":"고령화가 나타나는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"태어나는 아이는 줄고 사람들은 오래 살게 되었기 때문이에요","correct":true},{"t":"태어나는 아이가 크게 늘었기 때문이에요","mis":"SO3-2-u1-X08"},{"t":"병원이 줄어들었기 때문이에요","mis":"SO3-2-u1-X09"},{"t":"노인이 모두 다른 곳으로 떠났기 때문이에요","mis":"SO3-2-u1-X08"}],"explanation":["아이는 줄어요.","노인은 오래 살아요.","노인 비율이 높아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_challenge#5','soc',3,2,'u1','L03','g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',3,'mc','auto','자료의 카드 가운데 나라가 고령화에 대비하려고 하는 「노력」에 해당하는 것은 무엇인가요?',ARRAY['SO3-2-u1-X10']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"mc","stem":"자료의 카드 가운데 나라가 고령화에 대비하려고 하는 「노력」에 해당하는 것은 무엇인가요?","options":[{"t":"㉣","correct":true},{"t":"㉡","mis":"SO3-2-u1-X10"},{"t":"㉢","mis":"SO3-2-u1-X10"},{"t":"㉠과 ㉡","mis":"SO3-2-u1-X10"}],"explanation":["나라가 하는 일이에요.","일자리를 줘요.","㉣이에요."],"asset":{"type":"passage","lines":["㉠ 노인 전문 병원과 요양 시설이 늘었다.","㉡ 노인을 위한 배움 프로그램이 늘었다.","㉢ 사회 곳곳에서 일하는 노인을 볼 수 있다.","㉣ 나라에서 노인에게 알맞은 일자리를 제공한다."],"title":"고령화와 관련한 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_challenge#6','soc',3,2,'u1','L03','g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',3,'error','auto','노인을 위한 물건을 만든다면 넣을 기능을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X10']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"error","stem":"노인을 위한 물건을 만든다면 넣을 기능을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「노인은 도움이 필요 없으니 아무 기능도 넣지 말자.」","correct":true,"mis_target":"SO3-2-u1-X10"},{"t":"친구 가 — 「위급할 때 도움을 부르는 기능을 넣자.」","mis":"SO3-2-u1-X10"},{"t":"친구 나 — 「약 먹을 시간을 알려 주는 기능을 넣자.」","mis":"SO3-2-u1-X10"}],"explanation":["노인을 위한 물건이에요.","도움이 되는 기능이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_challenge#7','soc',3,2,'u1','L03','g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',3,'ox','auto','사회 곳곳에서 일하는 노인을 찾아볼 수 있는 것도 고령화로 달라진 모습이에요.',ARRAY['SO3-2-u1-X10']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"ox","stem":"사회 곳곳에서 일하는 노인을 찾아볼 수 있는 것도 고령화로 달라진 모습이에요.","answer":"O","reason_options":[{"t":"노인이 많아지고 일을 하거나 일자리를 찾는 노인도 늘었기 때문에","correct":true},{"t":"노인은 일을 할 수 없기 때문에","mis":"SO3-2-u1-X10"}],"mis":"SO3-2-u1-X10","explanation":["일하는 노인이 늘었어요.","달라진 모습이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_challenge#8','soc',3,2,'u1','L03','g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',4,'mc','auto','고령화를 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X08','SO3-2-u1-X10','SO3-2-u1-X09']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C3","difficulty":4,"kind":"mc","stem":"고령화를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"전체 사람 수에서 노인이 차지하는 비율이 높아지고, 우리 사회는 노인이 안정된 생활을 하도록 여러 노력을 해요","correct":true},{"t":"노인이 차지하는 비율이 낮아지는 현상이에요","mis":"SO3-2-u1-X08"},{"t":"고령화가 되면 노인을 위한 시설과 프로그램이 줄어들어요","mis":"SO3-2-u1-X10"},{"t":"사람들이 오래 사는 것은 고령화와 관계가 없어요","mis":"SO3-2-u1-X09"}],"explanation":["뜻을 떠올려요.","모습이 달라져요.","노력하고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_challenge#9','soc',3,2,'u1','L03','g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',4,'mc','auto','자료의 변화가 이어진다면 우리 동네에 더 필요해질 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X10','SO3-2-u1-X03']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C3","difficulty":4,"kind":"mc","stem":"자료의 변화가 이어진다면 우리 동네에 더 필요해질 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"노인을 위한 시설과 일자리","correct":true},{"t":"어린이 놀이터만","mis":"SO3-2-u1-X10"},{"t":"오전반, 오후반 교실","mis":"SO3-2-u1-X03"},{"t":"노인 복지관을 없애는 일","mis":"SO3-2-u1-X10"}],"explanation":["노인이 더 많아져요.","노인을 위한 곳이 필요해요.","시설과 일자리예요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 노인 4명 정도","2020년 — 100명 가운데 노인 16명 정도","2050년(예상) — 100명 가운데 노인 40명 정도"],"title":"우리나라가 100명이 사는 마을이라면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L03_challenge#10','soc',3,2,'u1','L03','g3_2_soc_u1_L03_challenge','lesson_challenge','SO3-2-u1-C3',4,'essay','teacher','자료를 보고 노인이 차지하는 비율이 어떻게 변하고 있는지 쓰고, 고령화에 대비해 우리 사회가 할 수 있는 노력을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C3","difficulty":4,"kind":"essay","stem":"자료를 보고 노인이 차지하는 비율이 어떻게 변하고 있는지 쓰고, 고령화에 대비해 우리 사회가 할 수 있는 노력을 두 가지 쓰세요.","answer_guide":{"answer":"예: 100명 가운데 노인이 1980년에는 4명 정도, 2020년에는 16명 정도였고, 2050년에는 40명 정도가 될 것으로 예상돼요. 노인이 차지하는 비율이 점점 높아지고 있어요. 우리 사회는 노인에게 알맞은 일자리를 제공하고, 노인을 위한 복지 제도를 운영할 수 있어요.","scoring_points":["비율의 변화를 바르게 썼는가","노력 두 가지를 썼는가","노인의 안정된 생활과 이었는가"]},"explanation":["세 해를 견줘요.","비율이 높아져요.","노력 두 가지를 써요."],"asset":{"type":"passage","lines":["1980년 — 100명 가운데 노인 4명 정도","2020년 — 100명 가운데 노인 16명 정도","2050년(예상) — 100명 가운데 노인 40명 정도"],"title":"우리나라가 100명이 사는 마을이라면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_basic#1','soc',3,2,'u1','L04','g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',1,'mc','auto','전화, 컴퓨터와 같은 기기를 이용해 정보를 주고받는 기술을 무엇이라고 하나요?',ARRAY['SO3-2-u1-X11']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"mc","stem":"전화, 컴퓨터와 같은 기기를 이용해 정보를 주고받는 기술을 무엇이라고 하나요?","options":[{"t":"정보 통신 기술","correct":true},{"t":"의학 기술","mis":"SO3-2-u1-X11"},{"t":"농사 기술","mis":"SO3-2-u1-X11"},{"t":"건축 기술","mis":"SO3-2-u1-X11"}],"explanation":["정보를 주고받아요.","전화와 컴퓨터예요.","정보 통신 기술이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_basic#2','soc',3,2,'u1','L04','g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',1,'sa','auto','사람처럼 정보를 익히고 처리하여 여러 상황에 적용할 수 있는 컴퓨터 시스템을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"sa","stem":"사람처럼 정보를 익히고 처리하여 여러 상황에 적용할 수 있는 컴퓨터 시스템을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["인공지능"],"explanation":["사람처럼 생각해요.","인공◯◯이에요.","인공지능이에요."],"mis":"SO3-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_basic#3','soc',3,2,'u1','L04','g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',1,'ox','auto','지능정보화로 생활이 편리해졌지만 여러 가지 문제도 생겼어요.',ARRAY['SO3-2-u1-X13']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"ox","stem":"지능정보화로 생활이 편리해졌지만 여러 가지 문제도 생겼어요.","answer":"O","reason_options":[{"t":"배달 로봇처럼 편리한 점도 있고 사이버 범죄 같은 문제도 있기 때문에","correct":true},{"t":"지능정보화로는 좋은 점만 생겼기 때문에","mis":"SO3-2-u1-X13"}],"mis":"SO3-2-u1-X13","explanation":["편리해졌어요.","문제도 생겼어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_basic#4','soc',3,2,'u1','L04','g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',1,'mc','auto','지능정보화로 편리해진 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"mc","stem":"지능정보화로 편리해진 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"목소리를 알아듣고 기능을 해 주는 기기를 써요","correct":true},{"t":"남의 전화번호를 함부로 써요","mis":"SO3-2-u1-X12"},{"t":"가짜 뉴스가 사람들을 속여요","mis":"SO3-2-u1-X12"},{"t":"스마트폰을 지나치게 써요","mis":"SO3-2-u1-X12"}],"explanation":["편리해진 점을 골라요.","말로 시켜요.","목소리를 알아들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_basic#5','soc',3,2,'u1','L04','g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',2,'mc','auto','카드 가운데 「보완해요」 칸, 곧 지능정보화로 생겨난 문제끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"mc","stem":"카드 가운데 「보완해요」 칸, 곧 지능정보화로 생겨난 문제끼리 묶은 것은 무엇인가요?","options":[{"t":"㉡, ㉣, ㉤, ㉦","correct":true},{"t":"㉠, ㉢, ㉥, ㉧","mis":"SO3-2-u1-X12"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"SO3-2-u1-X12"},{"t":"㉤, ㉥, ㉦, ㉧","mis":"SO3-2-u1-X12"}],"explanation":["문제를 골라요.","범죄·가짜 뉴스·과의존이에요.","일자리 감소도 있어요."],"asset":{"type":"passage","lines":["㉠ 애플리케이션으로 주문하면 로봇이 음식을 배달해 준다.","㉡ 인터넷에서 남의 이름이나 전화번호를 함부로 쓴다.","㉢ 인공지능이 학생의 수준과 흥미에 맞춰 교육 활동을 돕는다.","㉣ 인공지능이 만든 그럴듯한 가짜 뉴스가 사람들을 속인다.","㉤ 인터넷이나 스마트폰을 지나치게 이용해 문제가 된다.","㉥ 목소리를 알아듣고 기능을 해 주는 인공지능 기기를 쓴다.","㉦ 사람이 하던 일을 인공지능이 대신 해 일자리가 줄기도 한다.","㉧ 인공지능이 주변 상황을 살펴 안전한 운전을 돕는다."],"title":"지능정보화로 나타난 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_basic#6','soc',3,2,'u1','L04','g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',2,'match','auto','지능정보화와 관련한 낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"match","stem":"지능정보화와 관련한 낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"정보 통신 기술","r":"기기로 정보를 주고받는 기술"},{"l":"인공지능","r":"사람처럼 정보를 익히고 처리하는 컴퓨터 시스템"},{"l":"지능정보화","r":"인공지능 기술이 사회 전반에 폭넓은 영향을 미치는 현상"}],"mis":"SO3-2-u1-X11","explanation":["주고받는 기술이에요.","생각하는 컴퓨터예요.","넓은 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_basic#7','soc',3,2,'u1','L04','g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',2,'blank','auto','인터넷이나 스마트폰을 지나치게 이용하여 문제가 되는 상태를 인터넷·스마트폰 (    )이라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"blank","stem":"인터넷이나 스마트폰을 지나치게 이용하여 문제가 되는 상태를 인터넷·스마트폰 (    )이라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"과의존","correct":true},{"t":"사용법","mis":"SO3-2-u1-X12"},{"t":"충전","mis":"SO3-2-u1-X12"},{"t":"검색","mis":"SO3-2-u1-X12"}],"explanation":["지나치게 써요.","너무 기대요.","과의존이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_basic#8','soc',3,2,'u1','L04','g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',2,'mc','auto','지킬 점 「가」를 지키면 막는 데 도움이 되는 문제는 무엇인가요?',ARRAY['SO3-2-u1-X14','SO3-2-u1-X12']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"mc","stem":"지킬 점 「가」를 지키면 막는 데 도움이 되는 문제는 무엇인가요?","options":[{"t":"다른 사람이 내 개인 정보를 함부로 쓰는 일","correct":true},{"t":"거짓 정보에 속는 일","mis":"SO3-2-u1-X14"},{"t":"스마트폰을 너무 오래 쓰는 일","mis":"SO3-2-u1-X14"},{"t":"로봇이 음식을 늦게 배달하는 일","mis":"SO3-2-u1-X12"}],"explanation":["개인 정보예요.","함부로 올리지 않아요.","남이 함부로 못 써요."],"asset":{"type":"passage","lines":["가. 자신의 개인 정보를 인터넷에서 함부로 공유하지 않아요.","나. 인터넷에 있는 정보를 비판 없이 무조건 믿지 않아요.","다. 선생님의 가르침이나 정해진 규칙에 따라 사용해요."],"title":"학교에서 인터넷이나 태블릿 컴퓨터를 쓸 때 지킬 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_basic#9','soc',3,2,'u1','L04','g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',2,'ox','auto','인터넷에 있는 정보는 모두 사실이니 그대로 믿어도 돼요.',ARRAY['SO3-2-u1-X14']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"ox","stem":"인터넷에 있는 정보는 모두 사실이니 그대로 믿어도 돼요.","answer":"X","reason_options":[{"t":"인공지능이 만든 그럴듯한 거짓 정보도 있어 비판하며 살펴봐야 하기 때문에","correct":true},{"t":"인터넷 정보는 누가 써도 늘 정확하기 때문에","mis":"SO3-2-u1-X14"}],"mis":"SO3-2-u1-X14","explanation":["가짜 뉴스도 있어요.","살펴봐야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_basic#10','soc',3,2,'u1','L04','g3_2_soc_u1_L04_basic','lesson_basic','SO3-2-u1-C4',3,'error','auto','지능정보화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X13']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"error","stem":"지능정보화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「문제가 생겼으니 인터넷이나 인공지능 기기는 아예 쓰지 말자.」","correct":true,"mis_target":"SO3-2-u1-X13"},{"t":"친구 가 — 「장점은 누리고 단점은 보완해야 해.」","mis":"SO3-2-u1-X13"},{"t":"친구 나 — 「사이버 범죄를 막으려고 감시하는 노력을 해.」","mis":"SO3-2-u1-X13"}],"explanation":["편리한 점도 있어요.","아예 안 쓰는 게 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_challenge#1','soc',3,2,'u1','L04','g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',2,'sa','auto','인터넷에서 남의 개인 정보를 함부로 쓰는 것과 같은 범죄를 「○○○ 범죄」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"sa","stem":"인터넷에서 남의 개인 정보를 함부로 쓰는 것과 같은 범죄를 「○○○ 범죄」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["사이버"],"explanation":["인터넷에서 일어나요.","사◯◯예요.","사이버예요."],"mis":"SO3-2-u1-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_challenge#2','soc',3,2,'u1','L04','g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',2,'ox','auto','카드 ㉦은 지능정보화로 편리해진 점이에요.',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"ox","stem":"카드 ㉦은 지능정보화로 편리해진 점이에요.","answer":"X","reason_options":[{"t":"사람이 하던 일을 인공지능이 대신 해 일자리가 줄어드는 것은 생겨난 문제이기 때문에","correct":true},{"t":"일자리가 줄면 모두에게 좋기 때문에","mis":"SO3-2-u1-X12"}],"mis":"SO3-2-u1-X12","explanation":["일자리가 줄어요.","문제예요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 애플리케이션으로 주문하면 로봇이 음식을 배달해 준다.","㉡ 인터넷에서 남의 이름이나 전화번호를 함부로 쓴다.","㉢ 인공지능이 학생의 수준과 흥미에 맞춰 교육 활동을 돕는다.","㉣ 인공지능이 만든 그럴듯한 가짜 뉴스가 사람들을 속인다.","㉤ 인터넷이나 스마트폰을 지나치게 이용해 문제가 된다.","㉥ 목소리를 알아듣고 기능을 해 주는 인공지능 기기를 쓴다.","㉦ 사람이 하던 일을 인공지능이 대신 해 일자리가 줄기도 한다.","㉧ 인공지능이 주변 상황을 살펴 안전한 운전을 돕는다."],"title":"지능정보화로 나타난 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_challenge#3','soc',3,2,'u1','L04','g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',3,'mc','auto','카드를 「누려요」와 「보완해요」 두 칸에 나누어 담았을 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X13','SO3-2-u1-X12']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"mc","stem":"카드를 「누려요」와 「보완해요」 두 칸에 나누어 담았을 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"두 칸 모두 비지 않아요. 생활이 편리해졌지만 문제도 생겼어요","correct":true},{"t":"「누려요」 칸만 채워져요. 편리해진 점만 있어요","mis":"SO3-2-u1-X13"},{"t":"「보완해요」 칸만 채워져요. 문제만 있어요","mis":"SO3-2-u1-X13"},{"t":"두 칸은 아무 관계가 없어요","mis":"SO3-2-u1-X12"}],"explanation":["두 칸을 봐요.","모두 채워졌어요.","좋은 점과 문제가 함께예요."],"asset":{"type":"passage","lines":["㉠ 애플리케이션으로 주문하면 로봇이 음식을 배달해 준다.","㉡ 인터넷에서 남의 이름이나 전화번호를 함부로 쓴다.","㉢ 인공지능이 학생의 수준과 흥미에 맞춰 교육 활동을 돕는다.","㉣ 인공지능이 만든 그럴듯한 가짜 뉴스가 사람들을 속인다.","㉤ 인터넷이나 스마트폰을 지나치게 이용해 문제가 된다.","㉥ 목소리를 알아듣고 기능을 해 주는 인공지능 기기를 쓴다.","㉦ 사람이 하던 일을 인공지능이 대신 해 일자리가 줄기도 한다.","㉧ 인공지능이 주변 상황을 살펴 안전한 운전을 돕는다."],"title":"지능정보화로 나타난 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_challenge#4','soc',3,2,'u1','L04','g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',3,'mc','auto','우리 사회가 지능정보화로 나타난 문제를 해결하려고 하는 노력으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO3-2-u1-X14','SO3-2-u1-X13']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"mc","stem":"우리 사회가 지능정보화로 나타난 문제를 해결하려고 하는 노력으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"개인 정보를 인터넷에 널리 알리도록 해요","correct":true},{"t":"사이버 범죄를 감시하고 피해를 줄여요","mis":"SO3-2-u1-X14"},{"t":"인터넷을 올바르게 쓰는 습관을 갖도록 도와요","mis":"SO3-2-u1-X14"},{"t":"인공지능을 잘 활용하는 능력을 기르는 교육을 해요","mis":"SO3-2-u1-X13"}],"explanation":["노력이 아닌 것을 찾아요.","개인 정보는 지켜야 해요.","알리는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_challenge#5','soc',3,2,'u1','L04','g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',3,'mc','auto','인터넷이나 휴대 전화가 없다면 생길 수 있는 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X11']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"mc","stem":"인터넷이나 휴대 전화가 없다면 생길 수 있는 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"날씨나 먼 곳 소식을 알려면 더 많은 시간이 걸릴 수 있어요","correct":true},{"t":"오늘 날씨를 더 빨리 알 수 있어요","mis":"SO3-2-u1-X11"},{"t":"생활이 지금보다 더 편리해져요","mis":"SO3-2-u1-X11"},{"t":"정보를 얻는 일은 아무것도 달라지지 않아요","mis":"SO3-2-u1-X11"}],"explanation":["스마트폰으로 날씨를 봐요.","없다면 어떨까요?","시간이 더 걸려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_challenge#6','soc',3,2,'u1','L04','g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',3,'error','auto','학교에서 태블릿 컴퓨터를 쓰며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X14']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"error","stem":"학교에서 태블릿 컴퓨터를 쓰며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「재미있으니까 정해진 시간보다 더 오래 써도 돼.」","correct":true,"mis_target":"SO3-2-u1-X14"},{"t":"친구 가 — 「내 개인 정보는 함부로 올리지 않을래.」","mis":"SO3-2-u1-X14"},{"t":"친구 다 — 「찾은 정보가 맞는지 다시 살펴볼래.」","mis":"SO3-2-u1-X14"}],"explanation":["규칙이 있어요.","정해진 만큼 써요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["가. 자신의 개인 정보를 인터넷에서 함부로 공유하지 않아요.","나. 인터넷에 있는 정보를 비판 없이 무조건 믿지 않아요.","다. 선생님의 가르침이나 정해진 규칙에 따라 사용해요."],"title":"학교에서 인터넷이나 태블릿 컴퓨터를 쓸 때 지킬 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_challenge#7','soc',3,2,'u1','L04','g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',3,'ox','auto','인공지능이 만든 그럴듯한 가짜 뉴스가 많은 사람을 속이는 것은 지능정보화로 생겨난 문제예요.',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"ox","stem":"인공지능이 만든 그럴듯한 가짜 뉴스가 많은 사람을 속이는 것은 지능정보화로 생겨난 문제예요.","answer":"O","reason_options":[{"t":"거짓 정보가 퍼져 사람들이 잘못 알게 될 수 있기 때문에","correct":true},{"t":"인공지능이 만든 것은 모두 사실이기 때문에","mis":"SO3-2-u1-X12"}],"mis":"SO3-2-u1-X12","explanation":["가짜 뉴스예요.","사람들이 속아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_challenge#8','soc',3,2,'u1','L04','g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',4,'mc','auto','지능정보화를 대하는 태도를 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X13']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C4","difficulty":4,"kind":"mc","stem":"지능정보화를 대하는 태도를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"편리해진 점은 잘 누리고, 생겨난 문제는 함께 보완하려고 노력해요","correct":true},{"t":"편리하니 문제는 걱정하지 않아요","mis":"SO3-2-u1-X13"},{"t":"문제가 있으니 인공지능 기기는 아예 쓰지 않아요","mis":"SO3-2-u1-X13"},{"t":"문제는 저절로 사라지니 아무 노력도 하지 않아요","mis":"SO3-2-u1-X13"}],"explanation":["누려요.","보완해요.","두 가지를 함께해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_challenge#9','soc',3,2,'u1','L04','g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',4,'mc','auto','카드 ㉤과 같은 문제를 막는 데 가장 도움이 되는 지킬 점은 무엇인가요?',ARRAY['SO3-2-u1-X14']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C4","difficulty":4,"kind":"mc","stem":"카드 ㉤과 같은 문제를 막는 데 가장 도움이 되는 지킬 점은 무엇인가요?","options":[{"t":"정해진 규칙에 따라 정해진 시간만큼 사용해요","correct":true},{"t":"개인 정보를 널리 알려요","mis":"SO3-2-u1-X14"},{"t":"밤늦게까지 계속 사용해요","mis":"SO3-2-u1-X14"},{"t":"인터넷 정보를 무조건 믿어요","mis":"SO3-2-u1-X14"}],"explanation":["지나치게 쓰는 문제예요.","규칙이 필요해요.","정해진 만큼 써요."],"asset":{"type":"passage","lines":["㉠ 애플리케이션으로 주문하면 로봇이 음식을 배달해 준다.","㉡ 인터넷에서 남의 이름이나 전화번호를 함부로 쓴다.","㉢ 인공지능이 학생의 수준과 흥미에 맞춰 교육 활동을 돕는다.","㉣ 인공지능이 만든 그럴듯한 가짜 뉴스가 사람들을 속인다.","㉤ 인터넷이나 스마트폰을 지나치게 이용해 문제가 된다.","㉥ 목소리를 알아듣고 기능을 해 주는 인공지능 기기를 쓴다.","㉦ 사람이 하던 일을 인공지능이 대신 해 일자리가 줄기도 한다.","㉧ 인공지능이 주변 상황을 살펴 안전한 운전을 돕는다."],"title":"지능정보화로 나타난 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L04_challenge#10','soc',3,2,'u1','L04','g3_2_soc_u1_L04_challenge','lesson_challenge','SO3-2-u1-C4',4,'essay','teacher','카드 가운데 편리해진 점 하나와 생겨난 문제 하나를 골라 쓰고, 그 문제를 보완하기 위해 내가 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C4","difficulty":4,"kind":"essay","stem":"카드 가운데 편리해진 점 하나와 생겨난 문제 하나를 골라 쓰고, 그 문제를 보완하기 위해 내가 지킬 점을 쓰세요.","answer_guide":{"answer":"예: ㉠처럼 로봇이 음식을 배달해 주어 생활이 편리해졌어요. 하지만 ㉣처럼 인공지능이 만든 가짜 뉴스가 사람들을 속이는 문제도 생겼어요. 나는 인터넷에 있는 정보를 무조건 믿지 않고 맞는지 다시 살펴볼 거예요.","scoring_points":["편리해진 점을 골랐는가","생겨난 문제를 골랐는가","문제에 맞는 지킬 점을 썼는가"]},"explanation":["누려요 칸에서 골라요.","보완해요 칸에서 골라요.","지킬 점을 써요."],"asset":{"type":"passage","lines":["㉠ 애플리케이션으로 주문하면 로봇이 음식을 배달해 준다.","㉡ 인터넷에서 남의 이름이나 전화번호를 함부로 쓴다.","㉢ 인공지능이 학생의 수준과 흥미에 맞춰 교육 활동을 돕는다.","㉣ 인공지능이 만든 그럴듯한 가짜 뉴스가 사람들을 속인다.","㉤ 인터넷이나 스마트폰을 지나치게 이용해 문제가 된다.","㉥ 목소리를 알아듣고 기능을 해 주는 인공지능 기기를 쓴다.","㉦ 사람이 하던 일을 인공지능이 대신 해 일자리가 줄기도 한다.","㉧ 인공지능이 주변 상황을 살펴 안전한 운전을 돕는다."],"title":"지능정보화로 나타난 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_basic#1','soc',3,2,'u1','L05','g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',1,'mc','auto','세계 여러 나라가 다양한 분야에서 교류하면서 전 세계가 하나로 연결되는 현상을 무엇이라고 하나요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"mc","stem":"세계 여러 나라가 다양한 분야에서 교류하면서 전 세계가 하나로 연결되는 현상을 무엇이라고 하나요?","options":[{"t":"세계화","correct":true},{"t":"저출산","mis":"SO3-2-u1-X18"},{"t":"고령화","mis":"SO3-2-u1-X18"},{"t":"지능정보화","mis":"SO3-2-u1-X18"}],"explanation":["세계가 이어져요.","하나로 연결돼요.","세계화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_basic#2','soc',3,2,'u1','L05','g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',1,'sa','auto','대한민국과 관련 있는 것들이 다른 나라에서 인기를 얻는 현상을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"sa","stem":"대한민국과 관련 있는 것들이 다른 나라에서 인기를 얻는 현상을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["한류"],"explanation":["한국의 물결이에요.","한◯예요.","한류예요."],"mis":"SO3-2-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_basic#3','soc',3,2,'u1','L05','g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',1,'ox','auto','세계화로 다른 나라에서 만든 영화를 우리나라에서도 볼 수 있어요.',ARRAY['SO3-2-u1-X15']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"ox","stem":"세계화로 다른 나라에서 만든 영화를 우리나라에서도 볼 수 있어요.","answer":"O","reason_options":[{"t":"세계 여러 나라가 교류하며 영화 같은 것을 주고받기 때문에","correct":true},{"t":"다른 나라 영화는 그 나라에서만 볼 수 있기 때문에","mis":"SO3-2-u1-X15"}],"mis":"SO3-2-u1-X15","explanation":["여러 나라가 주고받아요.","영화도 들어와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_basic#4','soc',3,2,'u1','L05','g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',1,'mc','auto','우리 주변에서 볼 수 있는 세계화 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X15']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"mc","stem":"우리 주변에서 볼 수 있는 세계화 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"다른 나라에서 온 과일을 사 먹어요","correct":true},{"t":"우리 마을에서 기른 채소만 먹어요","mis":"SO3-2-u1-X15"},{"t":"다른 나라 소식은 전혀 알 수 없어요","mis":"SO3-2-u1-X15"},{"t":"먼 나라에 가려면 몇 년이 걸려요","mis":"SO3-2-u1-X15"}],"explanation":["다른 나라와 이어져요.","과일이 들어와요.","사 먹을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_basic#5','soc',3,2,'u1','L05','g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',2,'mc','auto','자료에서 세종 학당이 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"mc","stem":"자료에서 세종 학당이 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"다른 나라 사람들에게 한국어와 한국에 관한 내용을 가르쳐요","correct":true},{"t":"다른 나라 과일을 들여와 팔아요","mis":"SO3-2-u1-X16"},{"t":"우리나라 사람에게 다른 나라 운전 규칙을 가르쳐요","mis":"SO3-2-u1-X16"},{"t":"다른 나라에서 만든 영화를 만들어요","mis":"SO3-2-u1-X16"}],"explanation":["한국어를 배우려는 사람이에요.","한국을 알려요.","한국어를 가르쳐요."],"asset":{"type":"passage","lines":["세종 학당은 다른 나라에서 한국어를 배우려는 사람들에게","한국어를 중심으로 한국에 관한 내용을 가르친다.","우리의 말과 글, 음식, 한복 등을 세계 곳곳에 알린다."],"title":"신문 기사를 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_basic#6','soc',3,2,'u1','L05','g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',2,'match','auto','자료의 물건과 이어진 나라를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"match","stem":"자료의 물건과 이어진 나라를 알맞게 이으세요.","pairs":[{"l":"㉠ 초콜릿","r":"벨기에"},{"l":"㉢ 포도","r":"칠레"},{"l":"㉤ 프라이팬","r":"독일"},{"l":"㉣ 라면 공장","r":"미국·중국 등"}],"mis":"SO3-2-u1-X15","explanation":["만든 나라를 찾아요.","기른 나라도 있어요.","공장을 지은 나라도 있어요."],"asset":{"type":"passage","lines":["㉠ 벨기에에서 만든 초콜릿을 우리나라 가게에서 산다.","㉡ 우리나라 회사가 러시아·중국·베트남 등에 과자 공장을 세웠다.","㉢ 칠레에서 기른 포도를 우리나라에서 사 먹는다.","㉣ 한국 라면이 인기를 끌어 우리나라 회사가 미국·중국 등에 공장을 지었다.","㉤ 독일에서 만든 프라이팬을 우리나라에서 쓴다."],"title":"세계 여러 나라와 이어진 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_basic#7','soc',3,2,'u1','L05','g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',2,'blank','auto','여러 나라를 오가는 사람들이 많아지면서 (    )이 전 세계로 빠르게 퍼지기도 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"blank","stem":"여러 나라를 오가는 사람들이 많아지면서 (    )이 전 세계로 빠르게 퍼지기도 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"감염병","correct":true},{"t":"한류","mis":"SO3-2-u1-X17"},{"t":"새 학년","mis":"SO3-2-u1-X17"},{"t":"급식","mis":"SO3-2-u1-X17"}],"explanation":["세계화로 생긴 문제예요.","사람을 따라 옮겨요.","감염병이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_basic#8','soc',3,2,'u1','L05','g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',2,'mc','auto','자료에서 우리나라에서 다른 나라로 「나간」 모습에 해당하는 것끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"mc","stem":"자료에서 우리나라에서 다른 나라로 「나간」 모습에 해당하는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"㉡, ㉣","correct":true},{"t":"㉠, ㉢","mis":"SO3-2-u1-X16"},{"t":"㉢, ㉤","mis":"SO3-2-u1-X16"},{"t":"㉠, ㉤","mis":"SO3-2-u1-X16"}],"explanation":["우리나라 회사예요.","다른 나라에 공장을 지었어요.","㉡, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 벨기에에서 만든 초콜릿을 우리나라 가게에서 산다.","㉡ 우리나라 회사가 러시아·중국·베트남 등에 과자 공장을 세웠다.","㉢ 칠레에서 기른 포도를 우리나라에서 사 먹는다.","㉣ 한국 라면이 인기를 끌어 우리나라 회사가 미국·중국 등에 공장을 지었다.","㉤ 독일에서 만든 프라이팬을 우리나라에서 쓴다."],"title":"세계 여러 나라와 이어진 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_basic#9','soc',3,2,'u1','L05','g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',2,'ox','auto','세계화로 각 나라의 전통적인 생활 양식이 약해지는 문제가 생기기도 해요.',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"ox","stem":"세계화로 각 나라의 전통적인 생활 양식이 약해지는 문제가 생기기도 해요.","answer":"O","reason_options":[{"t":"다른 나라의 생활 양식이 들어오면서 생활 양식이 비슷해지기도 하기 때문에","correct":true},{"t":"세계화로는 아무 문제도 생기지 않기 때문에","mis":"SO3-2-u1-X17"}],"mis":"SO3-2-u1-X17","explanation":["생활 양식이 비슷해져요.","전통이 약해질 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_basic#10','soc',3,2,'u1','L05','g3_2_soc_u1_L05_basic','lesson_basic','SO3-2-u1-C5',3,'error','auto','세계화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X15','SO3-2-u1-X16','SO3-2-u1-X17']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"error","stem":"세계화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「세계화는 우리나라가 다른 나라 물건을 사기만 하는 거야.」","correct":true,"mis_target":"SO3-2-u1-X15"},{"t":"친구 나 — 「우리나라 라면이 다른 나라에서도 인기야.」","mis":"SO3-2-u1-X16"},{"t":"친구 다 — 「감염병이 빠르게 퍼지는 문제도 있어.」","mis":"SO3-2-u1-X17"}],"explanation":["주고받아요.","사기만 하지 않아요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_challenge#1','soc',3,2,'u1','L05','g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',2,'sa','auto','세계화에 대응하려면 다른 나라의 생활 양식을 무조건 따르지 않고 「○○○」을 따져 받아들여요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"sa","stem":"세계화에 대응하려면 다른 나라의 생활 양식을 무조건 따르지 않고 「○○○」을 따져 받아들여요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["장단점"],"explanation":["좋은 점과 나쁜 점이에요.","장◯◯이에요.","장단점이에요."],"mis":"SO3-2-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_challenge#2','soc',3,2,'u1','L05','g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',2,'ox','auto','자료의 물건은 모두 다른 나라에서 우리나라로 들어오기만 했어요.',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"ox","stem":"자료의 물건은 모두 다른 나라에서 우리나라로 들어오기만 했어요.","answer":"X","reason_options":[{"t":"㉡·㉣처럼 우리나라 회사가 다른 나라에 공장을 세운 모습도 있기 때문에","correct":true},{"t":"우리나라는 다른 나라에 아무것도 보내지 않기 때문에","mis":"SO3-2-u1-X16"}],"mis":"SO3-2-u1-X16","explanation":["㉡과 ㉣을 봐요.","나간 것도 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 벨기에에서 만든 초콜릿을 우리나라 가게에서 산다.","㉡ 우리나라 회사가 러시아·중국·베트남 등에 과자 공장을 세웠다.","㉢ 칠레에서 기른 포도를 우리나라에서 사 먹는다.","㉣ 한국 라면이 인기를 끌어 우리나라 회사가 미국·중국 등에 공장을 지었다.","㉤ 독일에서 만든 프라이팬을 우리나라에서 쓴다."],"title":"세계 여러 나라와 이어진 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_challenge#3','soc',3,2,'u1','L05','g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',3,'mc','auto','자료의 물건을 나라와 실로 이어 보았을 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X16','SO3-2-u1-X15']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"mc","stem":"자료의 물건을 나라와 실로 이어 보았을 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리나라는 세계 여러 나라와 서로 주고받으며 하나로 연결되어 있어요","correct":true},{"t":"우리나라는 다른 나라에 영향을 주지 않아요","mis":"SO3-2-u1-X16"},{"t":"우리나라는 가까운 한 나라와만 물건을 주고받아요","mis":"SO3-2-u1-X15"},{"t":"실이 이어진 나라는 하나도 없어요","mis":"SO3-2-u1-X15"}],"explanation":["들어온 실이 있어요.","나간 실도 있어요.","서로 주고받아요."],"asset":{"type":"passage","lines":["㉠ 벨기에에서 만든 초콜릿을 우리나라 가게에서 산다.","㉡ 우리나라 회사가 러시아·중국·베트남 등에 과자 공장을 세웠다.","㉢ 칠레에서 기른 포도를 우리나라에서 사 먹는다.","㉣ 한국 라면이 인기를 끌어 우리나라 회사가 미국·중국 등에 공장을 지었다.","㉤ 독일에서 만든 프라이팬을 우리나라에서 쓴다."],"title":"세계 여러 나라와 이어진 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_challenge#4','soc',3,2,'u1','L05','g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',3,'mc','auto','세계화에 대응하는 태도로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"mc","stem":"세계화에 대응하는 태도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다른 나라의 생활 양식은 장단점을 따져 받아들이고, 세계 여러 나라의 문제에 관심을 가져요","correct":true},{"t":"다른 나라의 생활 양식을 무조건 따라요","mis":"SO3-2-u1-X17"},{"t":"다른 나라의 생활 양식은 모두 받아들이지 않아요","mis":"SO3-2-u1-X17"},{"t":"세계 여러 나라의 문제에는 관심을 두지 않아요","mis":"SO3-2-u1-X17"}],"explanation":["무조건이 아니에요.","따져 받아들여요.","관심을 가져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_challenge#5','soc',3,2,'u1','L05','g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',3,'mc','auto','광고 문구 「가」에 담긴 태도로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"mc","stem":"광고 문구 「가」에 담긴 태도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리나라의 전통 생활 양식을 소중히 여기는 태도","correct":true},{"t":"다른 나라의 생활 양식을 무조건 따르는 태도","mis":"SO3-2-u1-X17"},{"t":"세계 여러 나라의 문제를 모른 체하는 태도","mis":"SO3-2-u1-X17"},{"t":"우리 전통을 잊어버리는 태도","mis":"SO3-2-u1-X17"}],"explanation":["우리 전통이에요.","소중히 여겨요.","전통을 지키는 태도예요."],"asset":{"type":"passage","lines":["가. 소중히 여기는 우리 전통, 더 나은 세계화","나. 세계인의 관심으로 만드는 모두가 행복한 세상","다. 우리의 작은 관심이 만드는 세계인의 더 큰 행복"],"title":"세계화에 대응하는 태도를 알리는 광고 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_challenge#6','soc',3,2,'u1','L05','g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',3,'error','auto','광고 문구를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"error","stem":"광고 문구를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「세 문구 가운데 「나」만 옳고 나머지는 잘못된 문구야.」","correct":true,"mis_target":"SO3-2-u1-X17"},{"t":"친구 가 — 「「나」와 「다」는 세계 여러 나라의 문제에 관심을 갖자는 문구야.」","mis":"SO3-2-u1-X17"},{"t":"친구 나 — 「「가」는 우리 전통을 소중히 여기자는 문구야.」","mis":"SO3-2-u1-X17"}],"explanation":["세 문구 모두 좋은 태도예요.","하나만 옳은 게 아니에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["가. 소중히 여기는 우리 전통, 더 나은 세계화","나. 세계인의 관심으로 만드는 모두가 행복한 세상","다. 우리의 작은 관심이 만드는 세계인의 더 큰 행복"],"title":"세계화에 대응하는 태도를 알리는 광고 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_challenge#7','soc',3,2,'u1','L05','g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',3,'ox','auto','세종 학당이 우리의 말과 글, 음식, 한복을 세계 곳곳에 알리는 것도 세계화의 모습이에요.',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"ox","stem":"세종 학당이 우리의 말과 글, 음식, 한복을 세계 곳곳에 알리는 것도 세계화의 모습이에요.","answer":"O","reason_options":[{"t":"우리나라의 생활 양식이 다른 나라로 퍼져 나가는 교류이기 때문에","correct":true},{"t":"세계화는 다른 나라 것이 들어오는 것만 말하기 때문에","mis":"SO3-2-u1-X16"}],"mis":"SO3-2-u1-X16","explanation":["우리 것을 알려요.","나가는 교류예요.","그래서 O예요."],"asset":{"type":"passage","lines":["세종 학당은 다른 나라에서 한국어를 배우려는 사람들에게","한국어를 중심으로 한국에 관한 내용을 가르친다.","우리의 말과 글, 음식, 한복 등을 세계 곳곳에 알린다."],"title":"신문 기사를 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_challenge#8','soc',3,2,'u1','L05','g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',4,'mc','auto','세계화를 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X15','SO3-2-u1-X17']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C5","difficulty":4,"kind":"mc","stem":"세계화를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"세계 여러 나라가 교류하며 하나로 연결되고, 다른 나라의 생활 양식을 장단점을 따져 받아들이며 함께 문제를 해결하려는 자세가 필요해요","correct":true},{"t":"세계화는 우리나라가 다른 나라 물건을 사기만 하는 현상이에요","mis":"SO3-2-u1-X15"},{"t":"우리 생활 양식만 지키고 다른 나라 것은 모두 거부해요","mis":"SO3-2-u1-X17"},{"t":"세계화로 생긴 문제는 하나도 없어요","mis":"SO3-2-u1-X17"}],"explanation":["하나로 연결돼요.","따져 받아들여요.","함께 해결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_challenge#9','soc',3,2,'u1','L05','g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',4,'mc','auto','감염병이 전 세계로 빠르게 퍼지는 까닭을 세계화와 이어 설명한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X17','SO3-2-u1-X16','SO3-2-u1-X15']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C5","difficulty":4,"kind":"mc","stem":"감염병이 전 세계로 빠르게 퍼지는 까닭을 세계화와 이어 설명한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여러 나라를 오가는 사람이 많아졌기 때문이에요","correct":true},{"t":"다른 나라 영화를 많이 보기 때문이에요","mis":"SO3-2-u1-X17"},{"t":"한국어를 배우는 사람이 늘었기 때문이에요","mis":"SO3-2-u1-X16"},{"t":"사람들이 한 나라에만 머물기 때문이에요","mis":"SO3-2-u1-X15"}],"explanation":["사람이 오가요.","병도 함께 옮겨요.","오가는 사람이 많아졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L05_challenge#10','soc',3,2,'u1','L05','g3_2_soc_u1_L05_challenge','lesson_challenge','SO3-2-u1-C5',4,'essay','teacher','자료의 물건 가운데 다른 나라에서 「들어온」 것 하나와 우리나라에서 「나간」 것 하나를 골라 쓰고, 이것으로 알 수 있는 세계화의 모습을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C5","difficulty":4,"kind":"essay","stem":"자료의 물건 가운데 다른 나라에서 「들어온」 것 하나와 우리나라에서 「나간」 것 하나를 골라 쓰고, 이것으로 알 수 있는 세계화의 모습을 쓰세요.","answer_guide":{"answer":"예: ㉢ 칠레에서 기른 포도는 우리나라로 들어왔고, ㉣ 한국 라면은 인기를 끌어 우리나라 회사가 미국·중국 등에 공장을 지었어요. 이것으로 우리나라는 세계 여러 나라와 서로 주고받으며 하나로 연결되어 있다는 것을 알 수 있어요.","scoring_points":["들어온 것을 골랐는가","나간 것을 골랐는가","서로 주고받으며 연결된다는 것을 썼는가"]},"explanation":["들어온 것을 골라요.","나간 것을 골라요.","알 수 있는 것을 써요."],"asset":{"type":"passage","lines":["㉠ 벨기에에서 만든 초콜릿을 우리나라 가게에서 산다.","㉡ 우리나라 회사가 러시아·중국·베트남 등에 과자 공장을 세웠다.","㉢ 칠레에서 기른 포도를 우리나라에서 사 먹는다.","㉣ 한국 라면이 인기를 끌어 우리나라 회사가 미국·중국 등에 공장을 지었다.","㉤ 독일에서 만든 프라이팬을 우리나라에서 쓴다."],"title":"세계 여러 나라와 이어진 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_basic#1','soc',3,2,'u1','L06','g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',1,'mc','auto','퍼즐 열쇠 ①에 알맞은 낱말은 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C6","difficulty":1,"kind":"mc","stem":"퍼즐 열쇠 ①에 알맞은 낱말은 무엇인가요?","options":[{"t":"복지 제도","correct":true},{"t":"세계화","mis":"SO3-2-u1-X18"},{"t":"출산율","mis":"SO3-2-u1-X18"},{"t":"정보 통신 기술","mis":"SO3-2-u1-X18"}],"explanation":["사회에서 지원해요.","행복하게 살도록 해요.","복지 제도예요."],"asset":{"type":"passage","lines":["① 사람들이 건강하고 행복하게 살도록 사회에서 지원하는 제도","② 인공지능 기술이 사회 전반에 폭넓은 영향을 미치는 현상","③ 전화·컴퓨터 같은 기기로 정보를 주고받는 기술","④ 전체 사람 수에서 노인의 수가 차지하는 비율이 높아지는 현상","⑤ 태어나는 아이의 수가 줄어 출산율이 감소하는 현상"],"title":"낱말 퍼즐 열쇠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_basic#2','soc',3,2,'u1','L06','g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',1,'sa','auto','퍼즐 열쇠 ④에 알맞은 낱말을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C6","difficulty":1,"kind":"sa","stem":"퍼즐 열쇠 ④에 알맞은 낱말을 세 글자로 쓰세요.","answer":["고령화"],"explanation":["노인의 비율이에요.","고◯화예요.","고령화예요."],"asset":{"type":"passage","lines":["① 사람들이 건강하고 행복하게 살도록 사회에서 지원하는 제도","② 인공지능 기술이 사회 전반에 폭넓은 영향을 미치는 현상","③ 전화·컴퓨터 같은 기기로 정보를 주고받는 기술","④ 전체 사람 수에서 노인의 수가 차지하는 비율이 높아지는 현상","⑤ 태어나는 아이의 수가 줄어 출산율이 감소하는 현상"],"title":"낱말 퍼즐 열쇠"},"mis":"SO3-2-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_basic#3','soc',3,2,'u1','L06','g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',1,'ox','auto','우리 사회는 저출산, 고령화, 지능정보화, 세계화 등으로 변화하고 있어요.',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C6","difficulty":1,"kind":"ox","stem":"우리 사회는 저출산, 고령화, 지능정보화, 세계화 등으로 변화하고 있어요.","answer":"O","reason_options":[{"t":"여러 사회 변화로 사람들의 생활 모습이 달라지고 있기 때문에","correct":true},{"t":"우리 사회는 한 가지 이유로만 변하기 때문에","mis":"SO3-2-u1-X18"}],"mis":"SO3-2-u1-X18","explanation":["네 가지를 배웠어요.","생활이 달라졌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_basic#4','soc',3,2,'u1','L06','g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',1,'mc','auto','사회 변화로 나타난 문제를 해결하려면 누가 노력해야 할까요?',ARRAY['SO3-2-u1-X19']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C6","difficulty":1,"kind":"mc","stem":"사회 변화로 나타난 문제를 해결하려면 누가 노력해야 할까요?","options":[{"t":"우리 모두가 관심을 갖고 함께 노력해야 해요","correct":true},{"t":"나라만 노력하면 돼요","mis":"SO3-2-u1-X19"},{"t":"어른들만 노력하면 돼요","mis":"SO3-2-u1-X19"},{"t":"아무도 노력하지 않아도 돼요","mis":"SO3-2-u1-X19"}],"explanation":["모두의 문제예요.","함께해요.","우리 모두예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_basic#5','soc',3,2,'u1','L06','g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',2,'match','auto','사회 변화와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u1-C6","difficulty":2,"kind":"match","stem":"사회 변화와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"저출산","r":"태어나는 아이의 수가 줄어드는 현상"},{"l":"고령화","r":"노인이 차지하는 비율이 높아지는 현상"},{"l":"지능정보화","r":"인공지능 기술이 폭넓은 영향을 미치는 현상"},{"l":"세계화","r":"여러 나라가 교류하며 하나로 연결되는 현상"}],"mis":"SO3-2-u1-X18","explanation":["아이와 노인이에요.","인공지능이에요.","여러 나라예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_basic#6','soc',3,2,'u1','L06','g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',2,'mc','auto','사회 변화를 카드 뉴스로 정리할 때 알맞은 차례는 무엇인가요?',ARRAY['SO3-2-u1-X19']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C6","difficulty":2,"kind":"mc","stem":"사회 변화를 카드 뉴스로 정리할 때 알맞은 차례는 무엇인가요?","options":[{"t":"주제 → 모습 → 문제 → 대응 방안","correct":true},{"t":"대응 방안 → 주제 → 문제 → 모습","mis":"SO3-2-u1-X19"},{"t":"문제 → 주제 → 대응 방안 → 모습","mis":"SO3-2-u1-X19"},{"t":"모습 → 대응 방안 → 주제 → 문제","mis":"SO3-2-u1-X19"}],"explanation":["주제가 먼저예요.","모습과 문제를 써요.","대응 방안이 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_basic#7','soc',3,2,'u1','L06','g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',2,'blank','auto','태어나는 아이의 수가 줄어들어 (    )이 감소하는 현상을 저출산이라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C6","difficulty":2,"kind":"blank","stem":"태어나는 아이의 수가 줄어들어 (    )이 감소하는 현상을 저출산이라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"출산율","correct":true},{"t":"평균 수명","mis":"SO3-2-u1-X18"},{"t":"비율","mis":"SO3-2-u1-X18"},{"t":"노인의 수","mis":"SO3-2-u1-X18"}],"explanation":["아이를 낳는 정도예요.","출산◯이에요.","출산율이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_basic#8','soc',3,2,'u1','L06','g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',2,'mc','auto','포스터 문구 「나」는 어느 사회 변화로 생긴 문제와 관계있나요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C6","difficulty":2,"kind":"mc","stem":"포스터 문구 「나」는 어느 사회 변화로 생긴 문제와 관계있나요?","options":[{"t":"지능정보화","correct":true},{"t":"저출산","mis":"SO3-2-u1-X18"},{"t":"고령화","mis":"SO3-2-u1-X18"},{"t":"세계화","mis":"SO3-2-u1-X18"}],"explanation":["사이버 범죄예요.","인터넷에서 일어나요.","지능정보화예요."],"asset":{"type":"passage","lines":["가. 저출산, 이겨 낼 수 있어요 — 보육 시설을 늘려 해결해요","나. 사이버 범죄를 막기 위해 모두 함께 노력해요","다. 우리 이웃이 된 세계인들을 친구처럼 여겨요"],"title":"사회 변화 포스터 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_basic#9','soc',3,2,'u1','L06','g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',2,'ox','auto','지능정보화에 대응하려면 장점은 누리고 단점은 보완하려는 태도가 필요해요.',ARRAY['SO3-2-u1-X13']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C6","difficulty":2,"kind":"ox","stem":"지능정보화에 대응하려면 장점은 누리고 단점은 보완하려는 태도가 필요해요.","answer":"O","reason_options":[{"t":"생활이 편리해졌지만 사이버 범죄 같은 문제도 생겼기 때문에","correct":true},{"t":"편리한 점만 있으니 보완할 것이 없기 때문에","mis":"SO3-2-u1-X13"}],"mis":"SO3-2-u1-X13","explanation":["편리해졌어요.","문제도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_basic#10','soc',3,2,'u1','L06','g3_2_soc_u1_L06_basic','lesson_basic','SO3-2-u1-C6',3,'error','auto','사회 변화를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X19','SO3-2-u1-X06','SO3-2-u1-X10']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C6","difficulty":3,"kind":"error","stem":"사회 변화를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「사회 변화로 생긴 문제는 나라에서만 해결하면 돼.」","correct":true,"mis_target":"SO3-2-u1-X19"},{"t":"친구 가 — 「저출산이 계속되면 학생 수가 줄어.」","mis":"SO3-2-u1-X06"},{"t":"친구 다 — 「고령화에 대비해 노인 일자리를 마련해.」","mis":"SO3-2-u1-X10"}],"explanation":["누가 노력할까요?","우리 모두예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_challenge#1','soc',3,2,'u1','L06','g3_2_soc_u1_L06_challenge','lesson_challenge','SO3-2-u1-C6',2,'sa','auto','퍼즐 열쇠 ③에 알맞은 낱말은 「정보 ○○ 기술」이에요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C6","difficulty":2,"kind":"sa","stem":"퍼즐 열쇠 ③에 알맞은 낱말은 「정보 ○○ 기술」이에요. ○○에 알맞은 두 글자를 쓰세요.","answer":["통신"],"explanation":["주고받아요.","◯신이에요.","통신이에요."],"asset":{"type":"passage","lines":["① 사람들이 건강하고 행복하게 살도록 사회에서 지원하는 제도","② 인공지능 기술이 사회 전반에 폭넓은 영향을 미치는 현상","③ 전화·컴퓨터 같은 기기로 정보를 주고받는 기술","④ 전체 사람 수에서 노인의 수가 차지하는 비율이 높아지는 현상","⑤ 태어나는 아이의 수가 줄어 출산율이 감소하는 현상"],"title":"낱말 퍼즐 열쇠"},"mis":"SO3-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_challenge#2','soc',3,2,'u1','L06','g3_2_soc_u1_L06_challenge','lesson_challenge','SO3-2-u1-C6',2,'ox','auto','포스터 문구 「다」는 세계화로 우리 이웃이 된 세계인들을 친구처럼 여기자는 생각을 나타내요.',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C6","difficulty":2,"kind":"ox","stem":"포스터 문구 「다」는 세계화로 우리 이웃이 된 세계인들을 친구처럼 여기자는 생각을 나타내요.","answer":"O","reason_options":[{"t":"세계화로 우리나라에 사는 세계 여러 나라 사람이 늘었기 때문에","correct":true},{"t":"세계화와 우리 이웃은 관계가 없기 때문에","mis":"SO3-2-u1-X17"}],"mis":"SO3-2-u1-X17","explanation":["세계인이 이웃이에요.","친구처럼 여겨요.","그래서 O예요."],"asset":{"type":"passage","lines":["가. 저출산, 이겨 낼 수 있어요 — 보육 시설을 늘려 해결해요","나. 사이버 범죄를 막기 위해 모두 함께 노력해요","다. 우리 이웃이 된 세계인들을 친구처럼 여겨요"],"title":"사회 변화 포스터 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_challenge#3','soc',3,2,'u1','L06','g3_2_soc_u1_L06_challenge','lesson_challenge','SO3-2-u1-C6',3,'mc','auto','네 사회 변화와 그때 생긴 문제를 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X18','SO3-2-u1-X19']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C6","difficulty":3,"kind":"mc","stem":"네 사회 변화와 그때 생긴 문제를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"저출산 — 학생 수 감소 · 지능정보화 — 사이버 범죄 · 세계화 — 감염병의 빠른 확산","correct":true},{"t":"저출산 — 사이버 범죄 · 지능정보화 — 감염병의 빠른 확산 · 세계화 — 학생 수 감소","mis":"SO3-2-u1-X18"},{"t":"저출산 — 감염병의 빠른 확산 · 지능정보화 — 학생 수 감소 · 세계화 — 사이버 범죄","mis":"SO3-2-u1-X18"},{"t":"세 사회 변화 모두 문제가 없어요","mis":"SO3-2-u1-X19"}],"explanation":["아이가 줄어요.","인터넷 범죄예요.","병이 퍼져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_challenge#4','soc',3,2,'u1','L06','g3_2_soc_u1_L06_challenge','lesson_challenge','SO3-2-u1-C6',3,'mc','auto','사회 변화와 그 대응 노력을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C6","difficulty":3,"kind":"mc","stem":"사회 변화와 그 대응 노력을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"고령화 — 노인에게 알맞은 일자리 제공","correct":true},{"t":"저출산 — 사이버 범죄 감시","mis":"SO3-2-u1-X18"},{"t":"세계화 — 보육 시설 운영","mis":"SO3-2-u1-X18"},{"t":"지능정보화 — 노인 복지관 짓기","mis":"SO3-2-u1-X18"}],"explanation":["노인과 관계있어요.","일자리예요.","고령화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_challenge#5','soc',3,2,'u1','L06','g3_2_soc_u1_L06_challenge','lesson_challenge','SO3-2-u1-C6',3,'mc','auto','포스터 문구 「가」에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SO3-2-u1-X18','SO3-2-u1-X17','SO3-2-u1-X19']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C6","difficulty":3,"kind":"mc","stem":"포스터 문구 「가」에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"저출산 문제를 보육 시설을 늘려 해결하자는 생각을 나타내요","correct":true},{"t":"고령화 문제를 해결하자는 생각이에요","mis":"SO3-2-u1-X18"},{"t":"세계화를 막자는 생각이에요","mis":"SO3-2-u1-X17"},{"t":"저출산은 해결할 필요가 없다는 생각이에요","mis":"SO3-2-u1-X19"}],"explanation":["저출산이 적혀 있어요.","보육 시설이에요.","해결하자는 생각이에요."],"asset":{"type":"passage","lines":["가. 저출산, 이겨 낼 수 있어요 — 보육 시설을 늘려 해결해요","나. 사이버 범죄를 막기 위해 모두 함께 노력해요","다. 우리 이웃이 된 세계인들을 친구처럼 여겨요"],"title":"사회 변화 포스터 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_challenge#6','soc',3,2,'u1','L06','g3_2_soc_u1_L06_challenge','lesson_challenge','SO3-2-u1-C6',3,'error','auto','낱말 퍼즐을 풀며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C6","difficulty":3,"kind":"error","stem":"낱말 퍼즐을 풀며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「열쇠 ②의 답은 「세계화」야.」","correct":true,"mis_target":"SO3-2-u1-X18"},{"t":"친구 가 — 「열쇠 ⑤의 답은 「저출산」이야.」","mis":"SO3-2-u1-X18"},{"t":"친구 나 — 「열쇠 ④의 답은 「고령화」야.」","mis":"SO3-2-u1-X18"}],"explanation":["열쇠 ②는 인공지능이에요.","지능정보화예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 사람들이 건강하고 행복하게 살도록 사회에서 지원하는 제도","② 인공지능 기술이 사회 전반에 폭넓은 영향을 미치는 현상","③ 전화·컴퓨터 같은 기기로 정보를 주고받는 기술","④ 전체 사람 수에서 노인의 수가 차지하는 비율이 높아지는 현상","⑤ 태어나는 아이의 수가 줄어 출산율이 감소하는 현상"],"title":"낱말 퍼즐 열쇠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_challenge#7','soc',3,2,'u1','L06','g3_2_soc_u1_L06_challenge','lesson_challenge','SO3-2-u1-C6',3,'ox','auto','다른 나라의 생활 양식은 무조건 따르는 것이 세계화에 대응하는 좋은 태도예요.',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C6","difficulty":3,"kind":"ox","stem":"다른 나라의 생활 양식은 무조건 따르는 것이 세계화에 대응하는 좋은 태도예요.","answer":"X","reason_options":[{"t":"장단점을 따져 받아들이고 우리 생활 양식도 소중히 여겨야 하기 때문에","correct":true},{"t":"다른 나라의 생활 양식은 모두 우리 것보다 낫기 때문에","mis":"SO3-2-u1-X17"}],"mis":"SO3-2-u1-X17","explanation":["무조건은 아니에요.","따져 받아들여요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_challenge#8','soc',3,2,'u1','L06','g3_2_soc_u1_L06_challenge','lesson_challenge','SO3-2-u1-C6',4,'mc','auto','「사회 변화로 달라진 생활 모습」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X19','SO3-2-u1-X02']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C6","difficulty":4,"kind":"mc","stem":"「사회 변화로 달라진 생활 모습」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"우리 사회는 저출산, 고령화, 지능정보화, 세계화 등으로 변화하고 있고, 문제를 해결하려면 모두 관심을 갖고 함께 노력해야 해요","correct":true},{"t":"사회 변화는 우리 생활과 관계가 없어요","mis":"SO3-2-u1-X19"},{"t":"사회 변화로 생긴 문제는 나라에서만 해결하면 돼요","mis":"SO3-2-u1-X19"},{"t":"사회는 한 가지 까닭으로만 변해요","mis":"SO3-2-u1-X02"}],"explanation":["네 가지 변화예요.","문제가 생겨요.","함께 노력해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_challenge#9','soc',3,2,'u1','L06','g3_2_soc_u1_L06_challenge','lesson_challenge','SO3-2-u1-C6',4,'mc','auto','사회 변화에 대응하기 위해 어린이인 내가 할 수 있는 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X19','SO3-2-u1-X14','SO3-2-u1-X17']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C6","difficulty":4,"kind":"mc","stem":"사회 변화에 대응하기 위해 어린이인 내가 할 수 있는 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"개인 정보를 함부로 올리지 않고, 세계 여러 나라의 문제에도 관심을 가져요","correct":true},{"t":"사회 변화는 어른들의 일이니 신경 쓰지 않아요","mis":"SO3-2-u1-X19"},{"t":"인터넷 정보를 무조건 믿어요","mis":"SO3-2-u1-X14"},{"t":"다른 나라 사람을 멀리해요","mis":"SO3-2-u1-X17"}],"explanation":["나도 할 수 있어요.","작은 실천이에요.","관심을 가져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L06_challenge#10','soc',3,2,'u1','L06','g3_2_soc_u1_L06_challenge','lesson_challenge','SO3-2-u1-C6',4,'essay','teacher','네 가지 사회 변화 가운데 하나를 골라 카드 뉴스의 차례(주제 → 모습 → 문제 → 대응 방안)에 맞게 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C6","difficulty":4,"kind":"essay","stem":"네 가지 사회 변화 가운데 하나를 골라 카드 뉴스의 차례(주제 → 모습 → 문제 → 대응 방안)에 맞게 쓰세요.","answer_guide":{"answer":"예: 주제는 고령화예요. 노인 복지관과 노인 전문 병원이 늘어나는 모습이 나타나요. 노인이 많아져 노인을 돌보고 지원할 일이 늘어나는 문제가 생겨요. 노인을 위한 복지 제도를 운영하고 알맞은 일자리를 제공해요.","scoring_points":["주제를 골랐는가","모습과 문제를 썼는가","알맞은 대응 방안을 썼는가"]},"explanation":["주제를 골라요.","모습과 문제를 써요.","대응 방안을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_basic#1','soc',3,2,'u1','L07','g3_2_soc_u1_L07_basic','lesson_basic','SO3-2-u1-C7',1,'mc','auto','한 사회의 사람들이 지닌 공통의 생활 양식을 무엇이라고 하나요?',ARRAY['SO3-2-u1-X21','SO3-2-u1-X20']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"mc","stem":"한 사회의 사람들이 지닌 공통의 생활 양식을 무엇이라고 하나요?","options":[{"t":"문화","correct":true},{"t":"규범","mis":"SO3-2-u1-X21"},{"t":"의식주","mis":"SO3-2-u1-X21"},{"t":"버릇","mis":"SO3-2-u1-X20"}],"explanation":["함께 지닌 생활 양식이에요.","사회마다 있어요.","문화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_basic#2','soc',3,2,'u1','L07','g3_2_soc_u1_L07_basic','lesson_basic','SO3-2-u1-C7',1,'sa','auto','사람이 살아가기 위해 꼭 필요한 옷, 음식, 집을 함께 이르는 말을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"sa","stem":"사람이 살아가기 위해 꼭 필요한 옷, 음식, 집을 함께 이르는 말을 세 글자로 쓰세요.","answer":["의식주"],"explanation":["옷·밥·집이에요.","의◯◯예요.","의식주예요."],"mis":"SO3-2-u1-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_basic#3','soc',3,2,'u1','L07','g3_2_soc_u1_L07_basic','lesson_basic','SO3-2-u1-C7',1,'ox','auto','졸려서 하품을 하고 잠을 자는 것도 문화예요.',ARRAY['SO3-2-u1-X20']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"ox","stem":"졸려서 하품을 하고 잠을 자는 것도 문화예요.","answer":"X","reason_options":[{"t":"태어날 때부터 누구나 하게 되는 행동은 문화가 아니기 때문에","correct":true},{"t":"사람이 하는 행동은 모두 문화이기 때문에","mis":"SO3-2-u1-X20"}],"mis":"SO3-2-u1-X20","explanation":["누구나 하는 행동이에요.","함께 만든 게 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_basic#4','soc',3,2,'u1','L07','g3_2_soc_u1_L07_basic','lesson_basic','SO3-2-u1-C7',1,'mc','auto','다음 가운데 문화라고 할 수 있는 것은 무엇인가요?',ARRAY['SO3-2-u1-X20']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"mc","stem":"다음 가운데 문화라고 할 수 있는 것은 무엇인가요?","options":[{"t":"생일에 미역국을 끓여 먹는 것","correct":true},{"t":"배가 고파서 음식을 먹는 것","mis":"SO3-2-u1-X20"},{"t":"졸려서 잠을 자는 것","mis":"SO3-2-u1-X20"},{"t":"추워서 몸을 떠는 것","mis":"SO3-2-u1-X20"}],"explanation":["함께 만든 생활 양식이에요.","생일을 축하해요.","미역국이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_basic#5','soc',3,2,'u1','L07','g3_2_soc_u1_L07_basic','lesson_basic','SO3-2-u1-C7',2,'mc','auto','자료의 세 줄을 견주어 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X22']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"mc","stem":"자료의 세 줄을 견주어 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"하는 일은 비슷하지만 하는 방법은 서로 달라요","correct":true},{"t":"학교 문화는 어느 나라나 똑같아요","mis":"SO3-2-u1-X22"},{"t":"우리 학교 문화만 알맞아요","mis":"SO3-2-u1-X22"},{"t":"다른 나라 학교에는 공부가 없어요","mis":"SO3-2-u1-X22"}],"explanation":["모두 새 학년이 있어요.","시작하는 달이 달라요.","방법이 달라요."],"asset":{"type":"passage","lines":["가. 중국 — 새 학년이 9월에 시작해요.","　　우리 학교 — 새 학년이 3월에 시작해요.","나. 미국 — 선생님의 이름을 부르며 악수해요.","　　우리 학교 — 고개를 숙여 인사해요.","다. 독일 — 독일어, 수학, 영어, 종교 등을 공부해요.","　　우리 학교 — 국어, 수학, 영어, 사회 등을 공부해요."],"title":"다른 나라 학교와 우리 학교 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_basic#6','soc',3,2,'u1','L07','g3_2_soc_u1_L07_basic','lesson_basic','SO3-2-u1-C7',2,'match','auto','문화와 관련한 낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"match","stem":"문화와 관련한 낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"문화","r":"한 사회의 사람들이 지닌 공통의 생활 양식"},{"l":"의식주","r":"옷, 음식, 집을 함께 이르는 말"},{"l":"규범","r":"마땅히 따르고 지켜야 할 생각이나 행동의 기준"}],"mis":"SO3-2-u1-X21","explanation":["생활 양식이에요.","옷·음식·집이에요.","지켜야 할 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_basic#7','soc',3,2,'u1','L07','g3_2_soc_u1_L07_basic','lesson_basic','SO3-2-u1-C7',2,'blank','auto','사람들이 마땅히 따르고 지켜야 할 생각이나 행동의 기준을 (    )이라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X21']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"blank","stem":"사람들이 마땅히 따르고 지켜야 할 생각이나 행동의 기준을 (    )이라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"규범","correct":true},{"t":"초원","mis":"SO3-2-u1-X21"},{"t":"축제","mis":"SO3-2-u1-X21"},{"t":"의식주","mis":"SO3-2-u1-X21"}],"explanation":["지켜야 할 기준이에요.","규◯이에요.","규범이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_basic#8','soc',3,2,'u1','L07','g3_2_soc_u1_L07_basic','lesson_basic','SO3-2-u1-C7',2,'mc','auto','자료처럼 지역마다 옷차림이 다른 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X22','SO3-2-u1-X21','SO3-2-u1-X23']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"mc","stem":"자료처럼 지역마다 옷차림이 다른 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"지역의 환경에 따라 생활 양식이 다르게 나타나기 때문이에요","correct":true},{"t":"한 지역의 옷만 알맞은 옷이라서예요","mis":"SO3-2-u1-X22"},{"t":"옷차림은 문화가 아니라서예요","mis":"SO3-2-u1-X21"},{"t":"사람들이 옷을 입는 까닭이 없어서예요","mis":"SO3-2-u1-X23"}],"explanation":["추운 곳과 햇볕 강한 곳이에요.","환경이 달라요.","생활 양식이 달라요."],"asset":{"type":"passage","lines":["㉠ 추운 지역 — 털모자를 쓰고 털옷을 입는다.","㉡ 햇볕이 강한 지역 — 온몸을 감싸는 긴 옷을 입는다."],"title":"지역마다 다른 옷차림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_basic#9','soc',3,2,'u1','L07','g3_2_soc_u1_L07_basic','lesson_basic','SO3-2-u1-C7',2,'ox','auto','각 사회의 문화는 비슷한 점도 있고 다른 점도 있어요.',ARRAY['SO3-2-u1-X22']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"ox","stem":"각 사회의 문화는 비슷한 점도 있고 다른 점도 있어요.","answer":"O","reason_options":[{"t":"모두 생일을 축하하지만 축하하는 음식이 다른 것처럼 하는 일은 비슷해도 방법이 다르기 때문에","correct":true},{"t":"어느 사회나 문화가 모두 똑같기 때문에","mis":"SO3-2-u1-X22"}],"mis":"SO3-2-u1-X22","explanation":["생일 축하는 비슷해요.","음식은 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_basic#10','soc',3,2,'u1','L07','g3_2_soc_u1_L07_basic','lesson_basic','SO3-2-u1-C7',3,'error','auto','문화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X21']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C7","difficulty":3,"kind":"error","stem":"문화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「문화에는 옷, 음식, 집만 있어.」","correct":true,"mis_target":"SO3-2-u1-X21"},{"t":"친구 나 — 「말과 글이나 음악도 문화야.」","mis":"SO3-2-u1-X21"},{"t":"친구 다 — 「규범과 종교도 문화에 들어가.」","mis":"SO3-2-u1-X21"}],"explanation":["의식주만이 아니에요.","말과 글도 있어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_challenge#1','soc',3,2,'u1','L07','g3_2_soc_u1_L07_challenge','lesson_challenge','SO3-2-u1-C7',2,'sa','auto','자료의 「가」에서 우리 학교의 새 학년은 몇 월에 시작하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"sa","stem":"자료의 「가」에서 우리 학교의 새 학년은 몇 월에 시작하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["우리 학교 줄을 봐요.","봄이에요.","3월이에요."],"asset":{"type":"passage","lines":["가. 중국 — 새 학년이 9월에 시작해요.","　　우리 학교 — 새 학년이 3월에 시작해요.","나. 미국 — 선생님의 이름을 부르며 악수해요.","　　우리 학교 — 고개를 숙여 인사해요.","다. 독일 — 독일어, 수학, 영어, 종교 등을 공부해요.","　　우리 학교 — 국어, 수학, 영어, 사회 등을 공부해요."],"title":"다른 나라 학교와 우리 학교 견주기"},"mis":"SO3-2-u1-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_challenge#2','soc',3,2,'u1','L07','g3_2_soc_u1_L07_challenge','lesson_challenge','SO3-2-u1-C7',2,'ox','auto','자료에서 미국과 우리 학교의 인사 방법이 다르니, 둘 중 하나는 잘못된 방법이에요.',ARRAY['SO3-2-u1-X22']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"ox","stem":"자료에서 미국과 우리 학교의 인사 방법이 다르니, 둘 중 하나는 잘못된 방법이에요.","answer":"X","reason_options":[{"t":"인사하는 방법은 사회마다 다를 뿐 어느 쪽이 잘못된 것이 아니기 때문에","correct":true},{"t":"우리 학교의 인사 방법만 알맞기 때문에","mis":"SO3-2-u1-X22"}],"mis":"SO3-2-u1-X22","explanation":["모두 인사해요.","방법만 달라요.","그래서 X예요."],"asset":{"type":"passage","lines":["가. 중국 — 새 학년이 9월에 시작해요.","　　우리 학교 — 새 학년이 3월에 시작해요.","나. 미국 — 선생님의 이름을 부르며 악수해요.","　　우리 학교 — 고개를 숙여 인사해요.","다. 독일 — 독일어, 수학, 영어, 종교 등을 공부해요.","　　우리 학교 — 국어, 수학, 영어, 사회 등을 공부해요."],"title":"다른 나라 학교와 우리 학교 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_challenge#3','soc',3,2,'u1','L07','g3_2_soc_u1_L07_challenge','lesson_challenge','SO3-2-u1-C7',3,'mc','auto','자료의 축제를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X21','SO3-2-u1-X22']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C7","difficulty":3,"kind":"mc","stem":"자료의 축제를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"축제는 그 사회의 생활 모습과 문화를 잘 드러내요","correct":true},{"t":"축제는 문화와 관계가 없어요","mis":"SO3-2-u1-X21"},{"t":"모든 나라의 축제는 똑같아요","mis":"SO3-2-u1-X22"},{"t":"다른 나라의 축제는 이상한 것이에요","mis":"SO3-2-u1-X22"}],"explanation":["참치를 잡는 곳이에요.","원숭이가 많은 곳이에요.","생활이 드러나요."],"asset":{"type":"passage","lines":["가. 에스파냐의 한 지역 — 서로 토마토를 던지는 축제","나. 타이의 한 지역 — 원숭이들에게 과일과 채소를 주는 축제","다. 오스트레일리아의 한 지역 — 모형 참치를 멀리 던지는 축제"],"title":"세계 여러 나라의 축제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_challenge#4','soc',3,2,'u1','L07','g3_2_soc_u1_L07_challenge','lesson_challenge','SO3-2-u1-C7',3,'mc','auto','숟가락과 젓가락으로 음식을 먹는 것을 문화라고 할 수 있는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X22']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C7","difficulty":3,"kind":"mc","stem":"숟가락과 젓가락으로 음식을 먹는 것을 문화라고 할 수 있는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그 사회 사람들이 함께 생활하며 만든 공통의 생활 양식이기 때문이에요","correct":true},{"t":"배가 고프면 누구나 하는 행동이기 때문이에요","mis":"SO3-2-u1-X20"},{"t":"한 사람만 하는 특별한 버릇이기 때문이에요","mis":"SO3-2-u1-X20"},{"t":"세계 어디서나 똑같이 하기 때문이에요","mis":"SO3-2-u1-X22"}],"explanation":["함께 만들었어요.","공통의 생활 양식이에요.","그래서 문화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_challenge#5','soc',3,2,'u1','L07','g3_2_soc_u1_L07_challenge','lesson_challenge','SO3-2-u1-C7',3,'mc','auto','자료의 두 지역 사람들이 옷을 입는 까닭으로 같은 점은 무엇인가요?',ARRAY['SO3-2-u1-X23']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C7","difficulty":3,"kind":"mc","stem":"자료의 두 지역 사람들이 옷을 입는 까닭으로 같은 점은 무엇인가요?","options":[{"t":"몸을 보호하기 위해 옷을 입어요","correct":true},{"t":"멋을 내기 위해서만 옷을 입어요","mis":"SO3-2-u1-X23"},{"t":"옷을 입는 까닭은 지역마다 완전히 달라요","mis":"SO3-2-u1-X23"},{"t":"추운 지역 사람만 옷을 입어요","mis":"SO3-2-u1-X23"}],"explanation":["털옷과 긴 옷이에요.","모두 몸을 지켜요.","보호하려고 입어요."],"asset":{"type":"passage","lines":["㉠ 추운 지역 — 털모자를 쓰고 털옷을 입는다.","㉡ 햇볕이 강한 지역 — 온몸을 감싸는 긴 옷을 입는다."],"title":"지역마다 다른 옷차림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_challenge#6','soc',3,2,'u1','L07','g3_2_soc_u1_L07_challenge','lesson_challenge','SO3-2-u1-C7',3,'error','auto','세계 여러 나라의 축제를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X22','SO3-2-u1-X23']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C7","difficulty":3,"kind":"error","stem":"세계 여러 나라의 축제를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「토마토를 던지는 축제는 이상하니까 없애야 해.」","correct":true,"mis_target":"SO3-2-u1-X22"},{"t":"친구 가 — 「참치를 잡으며 사는 곳이라 참치 축제가 있대.」","mis":"SO3-2-u1-X23"},{"t":"친구 다 — 「원숭이가 많이 사는 곳이라 원숭이 축제가 있대.」","mis":"SO3-2-u1-X23"}],"explanation":["다를 뿐이에요.","이상한 게 아니에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["가. 에스파냐의 한 지역 — 서로 토마토를 던지는 축제","나. 타이의 한 지역 — 원숭이들에게 과일과 채소를 주는 축제","다. 오스트레일리아의 한 지역 — 모형 참치를 멀리 던지는 축제"],"title":"세계 여러 나라의 축제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_challenge#7','soc',3,2,'u1','L07','g3_2_soc_u1_L07_challenge','lesson_challenge','SO3-2-u1-C7',3,'ox','auto','문화는 사람들이 함께 생활하면서 만들어지고 오랫동안 전해져 내려오기도 해요.',ARRAY['SO3-2-u1-X20']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C7","difficulty":3,"kind":"ox","stem":"문화는 사람들이 함께 생활하면서 만들어지고 오랫동안 전해져 내려오기도 해요.","answer":"O","reason_options":[{"t":"한 사회의 사람들이 함께 지니는 생활 양식이기 때문에","correct":true},{"t":"문화는 한 사람이 하루 만에 만들기 때문에","mis":"SO3-2-u1-X20"}],"mis":"SO3-2-u1-X20","explanation":["함께 만들어요.","오래 이어져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_challenge#8','soc',3,2,'u1','L07','g3_2_soc_u1_L07_challenge','lesson_challenge','SO3-2-u1-C7',4,'mc','auto','오늘 공부한 문화를 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X21','SO3-2-u1-X22']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C7","difficulty":4,"kind":"mc","stem":"오늘 공부한 문화를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"문화는 한 사회의 사람들이 지닌 공통의 생활 양식이고, 각 사회의 문화는 비슷한 점도 있고 다른 점도 있어요","correct":true},{"t":"사람들이 하는 행동은 모두 문화예요","mis":"SO3-2-u1-X20"},{"t":"문화에는 옷, 음식, 집만 있어요","mis":"SO3-2-u1-X21"},{"t":"우리 문화만 알맞은 문화예요","mis":"SO3-2-u1-X22"}],"explanation":["뜻을 떠올려요.","비슷한 점이 있어요.","다른 점도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_challenge#9','soc',3,2,'u1','L07','g3_2_soc_u1_L07_challenge','lesson_challenge','SO3-2-u1-C7',4,'mc','auto','자료와 같은 표에 줄을 하나 더 넣는다면 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X22','SO3-2-u1-X20']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C7","difficulty":4,"kind":"mc","stem":"자료와 같은 표에 줄을 하나 더 넣는다면 가장 알맞은 것은 무엇인가요?","options":[{"t":"점심을 먹는 방법을 다른 나라 학교와 우리 학교로 견주어요","correct":true},{"t":"우리 학교만 적고 다른 나라는 적지 않아요","mis":"SO3-2-u1-X22"},{"t":"졸릴 때 잠자는 모습을 견주어요","mis":"SO3-2-u1-X20"},{"t":"배고플 때 밥 먹는 모습을 견주어요","mis":"SO3-2-u1-X20"}],"explanation":["학교 문화를 견줘요.","함께 만든 생활 양식이에요.","점심 먹는 방법이에요."],"asset":{"type":"passage","lines":["가. 중국 — 새 학년이 9월에 시작해요.","　　우리 학교 — 새 학년이 3월에 시작해요.","나. 미국 — 선생님의 이름을 부르며 악수해요.","　　우리 학교 — 고개를 숙여 인사해요.","다. 독일 — 독일어, 수학, 영어, 종교 등을 공부해요.","　　우리 학교 — 국어, 수학, 영어, 사회 등을 공부해요."],"title":"다른 나라 학교와 우리 학교 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L07_challenge#10','soc',3,2,'u1','L07','g3_2_soc_u1_L07_challenge','lesson_challenge','SO3-2-u1-C7',4,'essay','teacher','우리 생활에서 문화라고 할 수 있는 것 하나와 문화라고 할 수 없는 것 하나를 골라 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C7","difficulty":4,"kind":"essay","stem":"우리 생활에서 문화라고 할 수 있는 것 하나와 문화라고 할 수 없는 것 하나를 골라 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 설날에 웃어른께 세배하는 것은 우리 사회 사람들이 함께 지켜 온 생활 양식이라 문화예요. 졸려서 하품하는 것은 태어날 때부터 누구나 하는 행동이라 문화가 아니에요.","scoring_points":["문화인 것을 골랐는가","문화가 아닌 것을 골랐는가","공통의 생활 양식과 이어 까닭을 썼는가"]},"explanation":["함께 만든 것을 골라요.","타고난 행동도 골라요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_basic#1','soc',3,2,'u1','L08','g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',1,'mc','auto','다른 지역에서 옮겨 와 사는 사람을 무엇이라고 하나요?',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"mc","stem":"다른 지역에서 옮겨 와 사는 사람을 무엇이라고 하나요?","options":[{"t":"이주민","correct":true},{"t":"관광객","mis":"SO3-2-u1-X24"},{"t":"여행객","mis":"SO3-2-u1-X24"},{"t":"구경꾼","mis":"SO3-2-u1-X24"}],"explanation":["옮겨 와 살아요.","이◯◯이에요.","이주민이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_basic#2','soc',3,2,'u1','L08','g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',1,'sa','auto','부모나 자녀, 형제 등과 같이 살지 않고 혼자 사는 경우를 「○인 가구」라고 해요. ○에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"sa","stem":"부모나 자녀, 형제 등과 같이 살지 않고 혼자 사는 경우를 「○인 가구」라고 해요. ○에 알맞은 수를 숫자로 쓰세요.","answer":["1"],"explanation":["혼자 살아요.","한 사람이에요.","1이에요."],"mis":"SO3-2-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_basic#3','soc',3,2,'u1','L08','g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',1,'ox','auto','반려동물은 사람과 더불어 살아가며 친밀감과 안정감을 주는 동물이에요.',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"ox","stem":"반려동물은 사람과 더불어 살아가며 친밀감과 안정감을 주는 동물이에요.","answer":"O","reason_options":[{"t":"가족처럼 함께 지내며 마음을 편하게 해 주기 때문에","correct":true},{"t":"동물원에서만 볼 수 있는 동물이기 때문에","mis":"SO3-2-u1-X24"}],"mis":"SO3-2-u1-X24","explanation":["함께 살아요.","마음이 편해져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_basic#4','soc',3,2,'u1','L08','g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',1,'mc','auto','우리나라의 외국인 이주민 수는 어떻게 변화하고 있나요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"mc","stem":"우리나라의 외국인 이주민 수는 어떻게 변화하고 있나요?","options":[{"t":"늘어나고 있어요","correct":true},{"t":"줄어들고 있어요","mis":"SO3-2-u1-X25"},{"t":"변화가 없어요","mis":"SO3-2-u1-X25"},{"t":"모두 사라졌어요","mis":"SO3-2-u1-X25"}],"explanation":["그래프를 떠올려요.","수가 커졌어요.","늘어나고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_basic#5','soc',3,2,'u1','L08','g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',2,'mc','auto','자료의 ④와 ⑥은 어떤 사람들이 늘어나며 나타난 모습인가요?',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"mc","stem":"자료의 ④와 ⑥은 어떤 사람들이 늘어나며 나타난 모습인가요?","options":[{"t":"1인 가구","correct":true},{"t":"외국인 이주민","mis":"SO3-2-u1-X24"},{"t":"반려동물과 함께 사는 사람","mis":"SO3-2-u1-X24"},{"t":"어린이집에 다니는 아이","mis":"SO3-2-u1-X24"}],"explanation":["1인분이에요.","혼자 만들어 먹어요.","1인 가구예요."],"asset":{"type":"passage","lines":["① 인도 음식점 — 사람들이 맨손으로 음식을 먹는다.","② 야외 결혼식장 — 한국인 남자와 외국인 여자가 결혼식을 한다.","③ 공원 — 반려동물 전용 놀이터에서 강아지들이 뛰어논다.","④ 동네 상점 — 한 사람이 조리해 먹을 1인분 간편식을 고른다.","⑤ 3층 집 — 어린이가 고양이가 좋아하는 간식을 찾아본다.","⑥ 반찬 가게 간판 — 「혼자 만들어 먹는 맛있는 집밥」"],"title":"우리 동네 여섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_basic#6','soc',3,2,'u1','L08','g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',2,'match','auto','자료의 장소와 그 모습이 늘어난 까닭이 된 사람들을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"match","stem":"자료의 장소와 그 모습이 늘어난 까닭이 된 사람들을 알맞게 이으세요.","pairs":[{"l":"① 인도 음식점","r":"외국인 이주민"},{"l":"④ 동네 상점","r":"1인 가구"},{"l":"③ 공원","r":"반려동물과 함께 사는 사람"}],"mis":"SO3-2-u1-X24","explanation":["다른 나라 음식이에요.","1인분이에요.","반려동물 놀이터예요."],"asset":{"type":"passage","lines":["① 인도 음식점 — 사람들이 맨손으로 음식을 먹는다.","② 야외 결혼식장 — 한국인 남자와 외국인 여자가 결혼식을 한다.","③ 공원 — 반려동물 전용 놀이터에서 강아지들이 뛰어논다.","④ 동네 상점 — 한 사람이 조리해 먹을 1인분 간편식을 고른다.","⑤ 3층 집 — 어린이가 고양이가 좋아하는 간식을 찾아본다.","⑥ 반찬 가게 간판 — 「혼자 만들어 먹는 맛있는 집밥」"],"title":"우리 동네 여섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_basic#7','soc',3,2,'u1','L08','g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',2,'blank','auto','세계화의 영향으로 직장, 공부, (    ) 등 다양한 목적으로 우리나라에 와서 사는 외국인 이주민이 늘어났어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"blank","stem":"세계화의 영향으로 직장, 공부, (    ) 등 다양한 목적으로 우리나라에 와서 사는 외국인 이주민이 늘어났어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"결혼","correct":true},{"t":"놀이","mis":"SO3-2-u1-X25"},{"t":"방학","mis":"SO3-2-u1-X25"},{"t":"낮잠","mis":"SO3-2-u1-X25"}],"explanation":["함께 가정을 꾸려요.","②를 떠올려요.","결혼이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_basic#8','soc',3,2,'u1','L08','g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',2,'mc','auto','1인 가구가 늘어나고 있는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"mc","stem":"1인 가구가 늘어나고 있는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"결혼에 관한 생각이 변하고, 혼자 사는 노인이 늘었기 때문이에요","correct":true},{"t":"태어나는 아이가 많아졌기 때문이에요","mis":"SO3-2-u1-X25"},{"t":"가족이 모두 함께 살아야 한다는 규칙 때문이에요","mis":"SO3-2-u1-X25"},{"t":"집이 모두 넓어졌기 때문이에요","mis":"SO3-2-u1-X25"}],"explanation":["생각이 변했어요.","노인도 혼자 살아요.","그래서 늘었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_basic#9','soc',3,2,'u1','L08','g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',2,'ox','auto','자료를 보면 한 동네에 여러 문화가 함께 나타나고 있어요.',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"ox","stem":"자료를 보면 한 동네에 여러 문화가 함께 나타나고 있어요.","answer":"O","reason_options":[{"t":"이주민, 1인 가구, 반려동물과 관련한 모습이 한 동네에 모두 있기 때문에","correct":true},{"t":"한 동네에는 한 가지 문화만 있기 때문에","mis":"SO3-2-u1-X25"}],"mis":"SO3-2-u1-X25","explanation":["여섯 곳을 봐요.","여러 모습이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 인도 음식점 — 사람들이 맨손으로 음식을 먹는다.","② 야외 결혼식장 — 한국인 남자와 외국인 여자가 결혼식을 한다.","③ 공원 — 반려동물 전용 놀이터에서 강아지들이 뛰어논다.","④ 동네 상점 — 한 사람이 조리해 먹을 1인분 간편식을 고른다.","⑤ 3층 집 — 어린이가 고양이가 좋아하는 간식을 찾아본다.","⑥ 반찬 가게 간판 — 「혼자 만들어 먹는 맛있는 집밥」"],"title":"우리 동네 여섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_basic#10','soc',3,2,'u1','L08','g3_2_soc_u1_L08_basic','lesson_basic','SO3-2-u1-C8',3,'error','auto','우리 사회의 다양한 문화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"error","stem":"우리 사회의 다양한 문화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「1인 가구가 줄어들면서 반려동물과 사는 사람도 줄고 있어.」","correct":true,"mis_target":"SO3-2-u1-X25"},{"t":"친구 가 — 「외국인 이주민이 늘고 있어.」","mis":"SO3-2-u1-X25"},{"t":"친구 나 — 「반려동물 놀이터 같은 시설이 생겼어.」","mis":"SO3-2-u1-X25"}],"explanation":["모두 늘고 있어요.","줄지 않아요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_challenge#1','soc',3,2,'u1','L08','g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',2,'sa','auto','교과서 그래프에서 외국인 이주민 수는 111만 명에서 몇만 명으로 늘었나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"sa","stem":"교과서 그래프에서 외국인 이주민 수는 111만 명에서 몇만 명으로 늘었나요? 숫자로 쓰세요.","answer":["213"],"explanation":["나중 수를 봐요.","200이 넘어요.","213만 명이에요."],"mis":"SO3-2-u1-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_challenge#2','soc',3,2,'u1','L08','g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',2,'ox','auto','자료의 ⑤는 외국인 이주민이 늘어나며 나타난 모습이에요.',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"ox","stem":"자료의 ⑤는 외국인 이주민이 늘어나며 나타난 모습이에요.","answer":"X","reason_options":[{"t":"고양이 간식을 알아보는 것은 반려동물과 함께 사는 사람이 늘어나며 나타난 모습이기 때문에","correct":true},{"t":"간식은 모두 다른 나라에서 오기 때문에","mis":"SO3-2-u1-X24"}],"mis":"SO3-2-u1-X24","explanation":["고양이예요.","반려동물이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 인도 음식점 — 사람들이 맨손으로 음식을 먹는다.","② 야외 결혼식장 — 한국인 남자와 외국인 여자가 결혼식을 한다.","③ 공원 — 반려동물 전용 놀이터에서 강아지들이 뛰어논다.","④ 동네 상점 — 한 사람이 조리해 먹을 1인분 간편식을 고른다.","⑤ 3층 집 — 어린이가 고양이가 좋아하는 간식을 찾아본다.","⑥ 반찬 가게 간판 — 「혼자 만들어 먹는 맛있는 집밥」"],"title":"우리 동네 여섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_challenge#3','soc',3,2,'u1','L08','g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',3,'mc','auto','자료의 여섯 곳에 알맞은 깃발을 모두 꽂았을 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X25','SO3-2-u1-X22']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"mc","stem":"자료의 여섯 곳에 알맞은 깃발을 모두 꽂았을 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리 사회에는 다양한 문화가 함께 있어요","correct":true},{"t":"우리 사회에는 하나의 문화만 있어요","mis":"SO3-2-u1-X25"},{"t":"깃발이 많은 문화만 알맞은 문화예요","mis":"SO3-2-u1-X22"},{"t":"동네 사람들은 모두 같은 문화 속에서 살아요","mis":"SO3-2-u1-X25"}],"explanation":["세 깃발이 모두 꽂혀요.","함께 있어요.","다양한 문화예요."],"asset":{"type":"passage","lines":["① 인도 음식점 — 사람들이 맨손으로 음식을 먹는다.","② 야외 결혼식장 — 한국인 남자와 외국인 여자가 결혼식을 한다.","③ 공원 — 반려동물 전용 놀이터에서 강아지들이 뛰어논다.","④ 동네 상점 — 한 사람이 조리해 먹을 1인분 간편식을 고른다.","⑤ 3층 집 — 어린이가 고양이가 좋아하는 간식을 찾아본다.","⑥ 반찬 가게 간판 — 「혼자 만들어 먹는 맛있는 집밥」"],"title":"우리 동네 여섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
