INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_challenge#5','soc',3,2,'u1','L08','g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',3,'mc','auto','반려동물과 함께 사는 사람이 많아지면서 나타난 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"mc","stem":"반려동물과 함께 사는 사람이 많아지면서 나타난 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"반려동물 놀이터와 관련 행사가 곳곳에 생겨요","correct":true},{"t":"반려동물 가게가 모두 문을 닫아요","mis":"SO3-2-u1-X25"},{"t":"공원에서 동물을 볼 수 없어요","mis":"SO3-2-u1-X25"},{"t":"반려동물은 한 종류만 기를 수 있어요","mis":"SO3-2-u1-X25"}],"explanation":["반려동물이 늘었어요.","시설이 생겨요.","행사도 열려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_challenge#6','soc',3,2,'u1','L08','g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',3,'error','auto','낱말의 뜻을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"error","stem":"낱말의 뜻을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「이주민은 한 지역에서 태어나 계속 사는 사람이야.」","correct":true,"mis_target":"SO3-2-u1-X24"},{"t":"친구 나 — 「1인 가구는 혼자 사는 경우야.」","mis":"SO3-2-u1-X24"},{"t":"친구 다 — 「반려동물은 사람과 더불어 사는 동물이야.」","mis":"SO3-2-u1-X24"}],"explanation":["옮겨 와 살아요.","계속 사는 사람이 아니에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_challenge#7','soc',3,2,'u1','L08','g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',3,'ox','auto','고령화로 혼자 사는 노인이 늘어난 것도 1인 가구가 늘어난 까닭 가운데 하나예요.',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"ox","stem":"고령화로 혼자 사는 노인이 늘어난 것도 1인 가구가 늘어난 까닭 가운데 하나예요.","answer":"O","reason_options":[{"t":"노인이 많아지며 혼자 사는 노인도 늘었기 때문에","correct":true},{"t":"1인 가구는 모두 어린이이기 때문에","mis":"SO3-2-u1-X25"}],"mis":"SO3-2-u1-X25","explanation":["노인이 많아졌어요.","혼자 사는 노인도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_challenge#8','soc',3,2,'u1','L08','g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',4,'mc','auto','오늘 살펴본 우리 사회의 문화를 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C8","difficulty":4,"kind":"mc","stem":"오늘 살펴본 우리 사회의 문화를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"외국인 이주민, 1인 가구, 반려동물과 함께 사는 사람이 늘어나면서 다양한 문화가 나타나고 있어요","correct":true},{"t":"우리 사회의 문화는 하나로만 이어져 와서 바뀌지 않아요","mis":"SO3-2-u1-X25"},{"t":"1인 가구가 줄면서 반려동물과 사는 사람도 줄고 있어요","mis":"SO3-2-u1-X25"},{"t":"외국인 이주민이 줄어 문화가 한 가지가 되었어요","mis":"SO3-2-u1-X25"}],"explanation":["세 사람들이 늘었어요.","문화가 다양해요.","함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_challenge#9','soc',3,2,'u1','L08','g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',4,'mc','auto','반려동물과 함께 사는 친구에게 묻기에 가장 알맞은 질문은 무엇인가요?',ARRAY['SO3-2-u1-X22','SO3-2-u1-X25']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C8","difficulty":4,"kind":"mc","stem":"반려동물과 함께 사는 친구에게 묻기에 가장 알맞은 질문은 무엇인가요?","options":[{"t":"어떤 반려동물과 함께 살고, 왜 함께 사나요?","correct":true},{"t":"반려동물을 기르면 안 되는 거 알아요?","mis":"SO3-2-u1-X22"},{"t":"반려동물은 가족이 아니죠?","mis":"SO3-2-u1-X22"},{"t":"반려동물은 한 종류만 기를 수 있죠?","mis":"SO3-2-u1-X25"}],"explanation":["친구를 존중해요.","궁금한 것을 물어요.","어떤 동물인지 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L08_challenge#10','soc',3,2,'u1','L08','g3_2_soc_u1_L08_challenge','lesson_challenge','SO3-2-u1-C8',4,'essay','teacher','자료의 여섯 곳 가운데 두 곳을 골라 각각 어떤 사람들이 늘어나며 나타난 모습인지 쓰고, 그 사람들이 늘어난 까닭을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C8","difficulty":4,"kind":"essay","stem":"자료의 여섯 곳 가운데 두 곳을 골라 각각 어떤 사람들이 늘어나며 나타난 모습인지 쓰고, 그 사람들이 늘어난 까닭을 하나 쓰세요.","answer_guide":{"answer":"예: ① 인도 음식점은 외국인 이주민이 늘어나며 나타난 모습이고, ④ 1인분 간편식을 고르는 모습은 1인 가구가 늘어나며 나타난 모습이에요. 외국인 이주민은 세계화의 영향으로 직장, 공부, 결혼 등을 위해 우리나라에 와서 살기 때문에 늘어났어요.","scoring_points":["두 곳을 골랐는가","알맞은 사람들과 이었는가","늘어난 까닭을 썼는가"]},"explanation":["두 곳을 골라요.","누가 늘었나요?","까닭을 써요."],"asset":{"type":"passage","lines":["① 인도 음식점 — 사람들이 맨손으로 음식을 먹는다.","② 야외 결혼식장 — 한국인 남자와 외국인 여자가 결혼식을 한다.","③ 공원 — 반려동물 전용 놀이터에서 강아지들이 뛰어논다.","④ 동네 상점 — 한 사람이 조리해 먹을 1인분 간편식을 고른다.","⑤ 3층 집 — 어린이가 고양이가 좋아하는 간식을 찾아본다.","⑥ 반찬 가게 간판 — 「혼자 만들어 먹는 맛있는 집밥」"],"title":"우리 동네 여섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_basic#1','soc',3,2,'u1','L09','g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',1,'mc','auto','나와 다르고 익숙하지 않은 것에 대해 공정하지 못하고 한쪽으로 치우친 생각을 무엇이라고 하나요?',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"mc","stem":"나와 다르고 익숙하지 않은 것에 대해 공정하지 못하고 한쪽으로 치우친 생각을 무엇이라고 하나요?","options":[{"t":"편견","correct":true},{"t":"차별","mis":"SO3-2-u1-X27"},{"t":"존중","mis":"SO3-2-u1-X27"},{"t":"관심","mis":"SO3-2-u1-X27"}],"explanation":["치우친 생각이에요.","편◯이에요.","편견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_basic#2','soc',3,2,'u1','L09','g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',1,'sa','auto','편견을 가지고 대상을 다르게 대우하는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"sa","stem":"편견을 가지고 대상을 다르게 대우하는 것을 두 글자로 쓰세요.","answer":["차별"],"explanation":["다르게 대해요.","◯별이에요.","차별이에요."],"mis":"SO3-2-u1-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_basic#3','soc',3,2,'u1','L09','g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',1,'ox','auto','다양한 문화가 퍼지면서 좋은 점만 생기고 문제는 생기지 않았어요.',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"ox","stem":"다양한 문화가 퍼지면서 좋은 점만 생기고 문제는 생기지 않았어요.","answer":"X","reason_options":[{"t":"좋은 영향과 함께 편견과 차별, 외로움, 갈등 같은 문제도 나타났기 때문에","correct":true},{"t":"새로운 문화는 언제나 좋기만 하기 때문에","mis":"SO3-2-u1-X26"}],"mis":"SO3-2-u1-X26","explanation":["두 면이 있어요.","문제도 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_basic#4','soc',3,2,'u1','L09','g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',1,'mc','auto','반려동물이 늘어나며 생긴 직업이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u1-X28']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"mc","stem":"반려동물이 늘어나며 생긴 직업이 아닌 것은 무엇인가요?","options":[{"t":"비행기 조종사","correct":true},{"t":"수의사","mis":"SO3-2-u1-X28"},{"t":"반려동물 훈련사","mis":"SO3-2-u1-X28"},{"t":"반려동물 미용사","mis":"SO3-2-u1-X28"}],"explanation":["반려동물을 돌보는 일이에요.","아닌 것을 골라요.","조종사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_basic#5','soc',3,2,'u1','L09','g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',2,'mc','auto','자료 가운데 1인 가구가 늘어나며 나타난 「좋아진 점」은 무엇인가요?',ARRAY['SO3-2-u1-X28','SO3-2-u1-X26']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"mc","stem":"자료 가운데 1인 가구가 늘어나며 나타난 「좋아진 점」은 무엇인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"SO3-2-u1-X28"},{"t":"㉣","mis":"SO3-2-u1-X26"},{"t":"㉤","mis":"SO3-2-u1-X28"}],"explanation":["혼자 사는 사람이에요.","작은 제품이에요.","㉢이에요."],"asset":{"type":"passage","lines":["㉠ 이주민이 학생들에게 자기 나라 문화를 알려 주는 교육에 참여한다.","㉡ 언어나 피부색이 다르다는 까닭으로 부당한 대우를 받기도 한다.","㉢ 크기가 작은 가전제품과 적은 양을 포장한 상품이 많아졌다.","㉣ 아플 때 도움을 청할 사람이 없어 어려움을 겪기도 한다.","㉤ 반려동물 미용사, 훈련사 같은 직업이 늘었다.","㉥ 짖는 소리나 냄새 때문에 이웃 간에 갈등이 생기기도 한다."],"title":"다양한 문화가 퍼지며 나타난 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_basic#6','soc',3,2,'u1','L09','g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',2,'match','auto','자료의 「생긴 문제」 카드와 관계있는 사람들을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"match","stem":"자료의 「생긴 문제」 카드와 관계있는 사람들을 알맞게 이으세요.","pairs":[{"l":"㉡","r":"외국인 이주민"},{"l":"㉣","r":"1인 가구"},{"l":"㉥","r":"반려동물과 함께 사는 사람"}],"mis":"SO3-2-u1-X28","explanation":["언어와 피부색이에요.","도움을 청할 사람이에요.","짖는 소리예요."],"asset":{"type":"passage","lines":["㉠ 이주민이 학생들에게 자기 나라 문화를 알려 주는 교육에 참여한다.","㉡ 언어나 피부색이 다르다는 까닭으로 부당한 대우를 받기도 한다.","㉢ 크기가 작은 가전제품과 적은 양을 포장한 상품이 많아졌다.","㉣ 아플 때 도움을 청할 사람이 없어 어려움을 겪기도 한다.","㉤ 반려동물 미용사, 훈련사 같은 직업이 늘었다.","㉥ 짖는 소리나 냄새 때문에 이웃 간에 갈등이 생기기도 한다."],"title":"다양한 문화가 퍼지며 나타난 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_basic#7','soc',3,2,'u1','L09','g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',2,'blank','auto','반려동물로 이웃 간에 갈등이 생긴 까닭 가운데 가장 많은 것은 짖는 소리나 발소리 같은 (    )이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X28']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"blank","stem":"반려동물로 이웃 간에 갈등이 생긴 까닭 가운데 가장 많은 것은 짖는 소리나 발소리 같은 (    )이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"소음","correct":true},{"t":"물림","mis":"SO3-2-u1-X28"},{"t":"털","mis":"SO3-2-u1-X28"},{"t":"산책","mis":"SO3-2-u1-X28"}],"explanation":["소리와 관계있어요.","시끄러워요.","소음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_basic#8','soc',3,2,'u1','L09','g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',2,'mc','auto','외국인 이주민이 늘어나면서 우리 사회에 나타난 좋은 영향으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X26','SO3-2-u1-X28']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"mc","stem":"외국인 이주민이 늘어나면서 우리 사회에 나타난 좋은 영향으로 알맞은 것은 무엇인가요?","options":[{"t":"세계 여러 나라의 문화를 경험할 기회가 늘었어요","correct":true},{"t":"다른 나라의 문화를 배울 기회가 줄었어요","mis":"SO3-2-u1-X26"},{"t":"우리 사회의 문화가 한 가지로 같아졌어요","mis":"SO3-2-u1-X26"},{"t":"낯선 문화에 대한 차별이 생겼어요","mis":"SO3-2-u1-X28"}],"explanation":["좋은 영향이에요.","여러 나라 문화예요.","경험이 늘었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_basic#9','soc',3,2,'u1','L09','g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',2,'ox','auto','「피부색이 다르니 우리와 어울릴 수 없을 거야」라고 생각하는 것은 편견이에요.',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"ox","stem":"「피부색이 다르니 우리와 어울릴 수 없을 거야」라고 생각하는 것은 편견이에요.","answer":"O","reason_options":[{"t":"익숙하지 않은 것에 대해 공정하지 못하고 치우친 생각이기 때문에","correct":true},{"t":"생각만 하는 것은 편견이 아니기 때문에","mis":"SO3-2-u1-X27"}],"mis":"SO3-2-u1-X27","explanation":["생각이에요.","치우쳤어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_basic#10','soc',3,2,'u1','L09','g3_2_soc_u1_L09_basic','lesson_basic','SO3-2-u1-C9',3,'error','auto','편견과 차별을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"error","stem":"편견과 차별을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「편견은 다르게 대하는 행동이고, 차별은 치우친 생각이야.」","correct":true,"mis_target":"SO3-2-u1-X27"},{"t":"친구 가 — 「편견은 한쪽으로 치우친 생각이야.」","mis":"SO3-2-u1-X27"},{"t":"친구 다 — 「차별은 편견을 가지고 다르게 대우하는 거야.」","mis":"SO3-2-u1-X27"}],"explanation":["편견은 생각이에요.","차별은 행동이에요.","친구 나가 거꾸로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_challenge#1','soc',3,2,'u1','L09','g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',2,'sa','auto','반려동물의 건강을 돌봐 주는 사람을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"sa","stem":"반려동물의 건강을 돌봐 주는 사람을 세 글자로 쓰세요.","answer":["수의사"],"explanation":["동물 병원에 있어요.","수◯◯예요.","수의사예요."],"mis":"SO3-2-u1-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_challenge#2','soc',3,2,'u1','L09','g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',2,'ox','auto','자료의 ㉥처럼 문제가 생기는 문화는 우리 사회에서 없애야 해요.',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"ox","stem":"자료의 ㉥처럼 문제가 생기는 문화는 우리 사회에서 없애야 해요.","answer":"X","reason_options":[{"t":"문제가 있다고 문화를 없애는 것이 아니라 문제를 함께 풀어 가야 하기 때문에","correct":true},{"t":"문제가 생긴 문화는 나쁜 문화이기 때문에","mis":"SO3-2-u1-X26"}],"mis":"SO3-2-u1-X26","explanation":["좋은 면도 있어요.","함께 풀어 가요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 이주민이 학생들에게 자기 나라 문화를 알려 주는 교육에 참여한다.","㉡ 언어나 피부색이 다르다는 까닭으로 부당한 대우를 받기도 한다.","㉢ 크기가 작은 가전제품과 적은 양을 포장한 상품이 많아졌다.","㉣ 아플 때 도움을 청할 사람이 없어 어려움을 겪기도 한다.","㉤ 반려동물 미용사, 훈련사 같은 직업이 늘었다.","㉥ 짖는 소리나 냄새 때문에 이웃 간에 갈등이 생기기도 한다."],"title":"다양한 문화가 퍼지며 나타난 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_challenge#3','soc',3,2,'u1','L09','g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',3,'mc','auto','자료의 여섯 카드를 사람들별로 두 장씩 나누어 보았을 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X26','SO3-2-u1-X28']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"mc","stem":"자료의 여섯 카드를 사람들별로 두 장씩 나누어 보았을 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다양한 문화가 퍼지면서 좋은 영향과 함께 문제도 나타나요","correct":true},{"t":"좋은 면만 있는 문화도 있어요","mis":"SO3-2-u1-X26"},{"t":"문제가 있는 문화는 없애야 해요","mis":"SO3-2-u1-X26"},{"t":"다양한 문화는 우리 사회와 관계가 없어요","mis":"SO3-2-u1-X28"}],"explanation":["세 사람들이에요.","두 면씩 있어요.","함께 나타나요."],"asset":{"type":"passage","lines":["㉠ 이주민이 학생들에게 자기 나라 문화를 알려 주는 교육에 참여한다.","㉡ 언어나 피부색이 다르다는 까닭으로 부당한 대우를 받기도 한다.","㉢ 크기가 작은 가전제품과 적은 양을 포장한 상품이 많아졌다.","㉣ 아플 때 도움을 청할 사람이 없어 어려움을 겪기도 한다.","㉤ 반려동물 미용사, 훈련사 같은 직업이 늘었다.","㉥ 짖는 소리나 냄새 때문에 이웃 간에 갈등이 생기기도 한다."],"title":"다양한 문화가 퍼지며 나타난 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_challenge#4','soc',3,2,'u1','L09','g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',3,'mc','auto','혼자 사는 사람들이 겪을 수 있는 어려움으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X28']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"mc","stem":"혼자 사는 사람들이 겪을 수 있는 어려움으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"아플 때 주변에 도움을 청할 사람이 없을 수 있어요","correct":true},{"t":"집안일을 도와줄 가족이 너무 많아요","mis":"SO3-2-u1-X28"},{"t":"작은 가전제품을 살 수 없어요","mis":"SO3-2-u1-X28"},{"t":"반려동물을 기를 수 없어요","mis":"SO3-2-u1-X28"}],"explanation":["혼자 살아요.","도와줄 사람이 없어요.","어려울 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_challenge#5','soc',3,2,'u1','L09','g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',3,'mc','auto','1인 가구에 인기 있을 만한 제품으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X28']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"mc","stem":"1인 가구에 인기 있을 만한 제품으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"혼자서 쓰기 좋은 작은 식기세척기","correct":true},{"t":"열 사람이 함께 쓰는 커다란 밥솥","mis":"SO3-2-u1-X28"},{"t":"대가족용 큰 식탁","mis":"SO3-2-u1-X28"},{"t":"반려동물 놀이터","mis":"SO3-2-u1-X28"}],"explanation":["혼자 써요.","작은 크기예요.","작은 식기세척기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_challenge#6','soc',3,2,'u1','L09','g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',3,'error','auto','자료를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X28']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"error","stem":"자료를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「㉤은 반려동물이 늘어나며 생긴 문제야.」","correct":true,"mis_target":"SO3-2-u1-X28"},{"t":"친구 나 — 「㉠은 외국인 이주민이 늘어나며 좋아진 점이야.」","mis":"SO3-2-u1-X28"},{"t":"친구 다 — 「㉣은 1인 가구가 겪는 어려움이야.」","mis":"SO3-2-u1-X28"}],"explanation":["직업이 늘었어요.","좋아진 점이에요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 이주민이 학생들에게 자기 나라 문화를 알려 주는 교육에 참여한다.","㉡ 언어나 피부색이 다르다는 까닭으로 부당한 대우를 받기도 한다.","㉢ 크기가 작은 가전제품과 적은 양을 포장한 상품이 많아졌다.","㉣ 아플 때 도움을 청할 사람이 없어 어려움을 겪기도 한다.","㉤ 반려동물 미용사, 훈련사 같은 직업이 늘었다.","㉥ 짖는 소리나 냄새 때문에 이웃 간에 갈등이 생기기도 한다."],"title":"다양한 문화가 퍼지며 나타난 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_challenge#7','soc',3,2,'u1','L09','g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',3,'ox','auto','외국인 이주민이 자기 나라 문화를 알려 주는 교육에 참여하면 우리가 여러 나라 문화를 경험할 기회가 늘어나요.',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"ox","stem":"외국인 이주민이 자기 나라 문화를 알려 주는 교육에 참여하면 우리가 여러 나라 문화를 경험할 기회가 늘어나요.","answer":"O","reason_options":[{"t":"이주민이 태어나고 자란 나라의 문화를 생생하게 알려 주기 때문에","correct":true},{"t":"다른 나라 문화는 책으로만 배울 수 있기 때문에","mis":"SO3-2-u1-X26"}],"mis":"SO3-2-u1-X26","explanation":["직접 알려 줘요.","생생하게 배워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_challenge#8','soc',3,2,'u1','L09','g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',4,'mc','auto','다양한 문화의 확산이 우리 사회에 미친 영향을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C9","difficulty":4,"kind":"mc","stem":"다양한 문화의 확산이 우리 사회에 미친 영향을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"원하는 문화를 누리며 살 수 있게 되었지만, 낯선 문화에 편견을 갖고 차별하는 문제가 생기기도 해요","correct":true},{"t":"우리 사회에는 아무 문제도 생기지 않았어요","mis":"SO3-2-u1-X26"},{"t":"사람들이 누릴 수 있는 문화가 줄어들었어요","mis":"SO3-2-u1-X26"},{"t":"문제가 생긴 문화는 모두 사라졌어요","mis":"SO3-2-u1-X26"}],"explanation":["좋은 영향이 있어요.","문제도 있어요.","두 면을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_challenge#9','soc',3,2,'u1','L09','g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',4,'mc','auto','「말이 다르다는 까닭으로 친구를 놀이에 끼워 주지 않았다」는 일에 대한 설명으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X27','SO3-2-u1-X26']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C9","difficulty":4,"kind":"mc","stem":"「말이 다르다는 까닭으로 친구를 놀이에 끼워 주지 않았다」는 일에 대한 설명으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"편견을 가지고 다르게 대우한 차별이에요","correct":true},{"t":"생각만 했으니 편견이에요","mis":"SO3-2-u1-X27"},{"t":"공정하게 대한 것이에요","mis":"SO3-2-u1-X27"},{"t":"문화를 존중한 것이에요","mis":"SO3-2-u1-X26"}],"explanation":["끼워 주지 않았어요.","행동으로 옮겼어요.","차별이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L09_challenge#10','soc',3,2,'u1','L09','g3_2_soc_u1_L09_challenge','lesson_challenge','SO3-2-u1-C9',4,'essay','teacher','자료에서 외국인 이주민·1인 가구·반려동물과 함께 사는 사람 가운데 하나를 골라 좋아진 점과 생긴 문제를 각각 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C9","difficulty":4,"kind":"essay","stem":"자료에서 외국인 이주민·1인 가구·반려동물과 함께 사는 사람 가운데 하나를 골라 좋아진 점과 생긴 문제를 각각 쓰세요.","answer_guide":{"answer":"예: 반려동물과 함께 사는 사람이 늘어나면서 반려동물 미용사, 훈련사 같은 직업이 늘어나는 좋은 점이 생겼어요. 하지만 짖는 소리나 냄새 때문에 이웃 간에 갈등이 생기는 문제도 나타났어요.","scoring_points":["하나를 골랐는가","좋아진 점을 썼는가","생긴 문제를 썼는가"]},"explanation":["하나를 골라요.","좋아진 점을 써요.","생긴 문제도 써요."],"asset":{"type":"passage","lines":["㉠ 이주민이 학생들에게 자기 나라 문화를 알려 주는 교육에 참여한다.","㉡ 언어나 피부색이 다르다는 까닭으로 부당한 대우를 받기도 한다.","㉢ 크기가 작은 가전제품과 적은 양을 포장한 상품이 많아졌다.","㉣ 아플 때 도움을 청할 사람이 없어 어려움을 겪기도 한다.","㉤ 반려동물 미용사, 훈련사 같은 직업이 늘었다.","㉥ 짖는 소리나 냄새 때문에 이웃 간에 갈등이 생기기도 한다."],"title":"다양한 문화가 퍼지며 나타난 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_basic#1','soc',3,2,'u1','L10','g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',1,'mc','auto','만화 영화 속 미나가 집 밖에 나갈 때 늘 모자를 쓰는 까닭은 무엇인가요?',ARRAY['SO3-2-u1-X30']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C10","difficulty":1,"kind":"mc","stem":"만화 영화 속 미나가 집 밖에 나갈 때 늘 모자를 쓰는 까닭은 무엇인가요?","options":[{"t":"다른 사람들이 자기 피부색을 이상하게 여긴다고 생각해서","correct":true},{"t":"햇볕이 너무 뜨거워서","mis":"SO3-2-u1-X30"},{"t":"모자를 모으는 것이 취미라서","mis":"SO3-2-u1-X30"},{"t":"학교에서 모자를 쓰라고 해서","mis":"SO3-2-u1-X30"}],"explanation":["피부색과 관계있어요.","이상하게 볼까 걱정해요.","그래서 모자를 써요."],"asset":{"type":"passage","lines":["만화 영화 속 미나는 집 밖에 나갈 때 늘 모자를 써요.","다른 사람들이 자기 피부색을 이상하게 여긴다고 생각하기 때문이에요."],"title":"만화 영화 속 미나 이야기(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_basic#2','soc',3,2,'u1','L10','g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',1,'sa','auto','나이, 국적, 언어, 장애 등과 관계없이 누구나 쓰기 쉽도록 물건이나 시설을 디자인하는 것을 「○○○○ 디자인」이라고 해요. ○○○○에 알맞은 네 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C10","difficulty":1,"kind":"sa","stem":"나이, 국적, 언어, 장애 등과 관계없이 누구나 쓰기 쉽도록 물건이나 시설을 디자인하는 것을 「○○○○ 디자인」이라고 해요. ○○○○에 알맞은 네 글자를 쓰세요.","answer":["유니버설"],"explanation":["누구나를 위한 디자인이에요.","유◯◯◯예요.","유니버설이에요."],"mis":"SO3-2-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_basic#3','soc',3,2,'u1','L10','g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',1,'ox','auto','반려견과 산책할 때는 입마개를 착용시키고 목줄을 채워요.',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C10","difficulty":1,"kind":"ox","stem":"반려견과 산책할 때는 입마개를 착용시키고 목줄을 채워요.","answer":"O","reason_options":[{"t":"물림 사고를 막고 이웃을 배려할 수 있기 때문에","correct":true},{"t":"반려견은 마음껏 뛰게 해야 하기 때문에","mis":"SO3-2-u1-X29"}],"mis":"SO3-2-u1-X29","explanation":["이웃을 배려해요.","사고를 막아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_basic#4','soc',3,2,'u1','L10','g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',1,'mc','auto','다양한 문화를 대하는 바람직한 태도로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X30','SO3-2-u1-X31']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C10","difficulty":1,"kind":"mc","stem":"다양한 문화를 대하는 바람직한 태도로 알맞은 것은 무엇인가요?","options":[{"t":"나와 다른 문화를 가진 사람들의 어려움에 관심을 가져요","correct":true},{"t":"외국인 이주민을 무시하고 경계해요","mis":"SO3-2-u1-X30"},{"t":"1인 가구의 사람들을 이상하다고 생각해요","mis":"SO3-2-u1-X30"},{"t":"다른 문화는 알려고 하지 않아요","mis":"SO3-2-u1-X31"}],"explanation":["바람직한 태도예요.","관심을 가져요.","어려움에 관심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_basic#5','soc',3,2,'u1','L10','g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',2,'mc','auto','태도 블록 가운데 바람직한 태도끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u1-X30']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"mc","stem":"태도 블록 가운데 바람직한 태도끼리 묶은 것은 무엇인가요?","options":[{"t":"㉠, ㉢, ㉤","correct":true},{"t":"㉡, ㉣, ㉥","mis":"SO3-2-u1-X30"},{"t":"㉠, ㉡, ㉢","mis":"SO3-2-u1-X30"},{"t":"㉣, ㉤, ㉥","mis":"SO3-2-u1-X30"}],"explanation":["편견 없이예요.","관심과 존중이에요.","㉠, ㉢, ㉤이에요."],"asset":{"type":"passage","lines":["㉠ 다른 문화에 대한 편견을 갖지 않고 차별하지 않아요.","㉡ 외국인 이주민을 무시하고 경계해요.","㉢ 다른 문화의 사람들이 겪는 어려움에 관심을 가져요.","㉣ 1인 가구의 사람들을 이상하다고 생각해요.","㉤ 서로 다른 문화를 이해하고 존중해요.","㉥ 반려동물을 가족이라고 생각하는 사람들을 비난해요."],"title":"태도 블록 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_basic#6','soc',3,2,'u1','L10','g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',2,'match','auto','자료의 노력과 그 노력이 돕는 사람을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"match","stem":"자료의 노력과 그 노력이 돕는 사람을 알맞게 이으세요.","pairs":[{"l":"㉠ 다양한 언어로 정보 안내","r":"한국어에 서툰 외국인"},{"l":"㉢ 프로그램 운영","r":"혼자 사는 사람"},{"l":"㉣ 입마개와 목줄","r":"반려견과 산책하는 사람과 이웃"}],"mis":"SO3-2-u1-X29","explanation":["말이 서툴러요.","혼자 살아요.","반려견과 이웃이에요."],"asset":{"type":"passage","lines":["㉠ 한국 생활에 필요한 정보를 다양한 언어로 알려 준다.","㉡ 국가 인권 위원회가 편견과 차별을 막는 제도를 만든다.","㉢ 혼자 사는 사람을 위한 프로그램을 운영한다.","㉣ 반려견과 산책할 때 입마개를 하고 목줄을 채운다.","㉤ 누구나 쓰기 쉽도록 물건과 시설을 디자인한다."],"title":"문제를 해결하려는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_basic#7','soc',3,2,'u1','L10','g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',2,'blank','auto','(    )는 편견과 차별을 막을 수 있는 제도를 만들고 관련 기관을 운영해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"blank","stem":"(    )는 편견과 차별을 막을 수 있는 제도를 만들고 관련 기관을 운영해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"국가 인권 위원회","correct":true},{"t":"반려동물 놀이터","mis":"SO3-2-u1-X29"},{"t":"세종 학당","mis":"SO3-2-u1-X29"},{"t":"노인 복지관","mis":"SO3-2-u1-X29"}],"explanation":["인권을 지켜요.","나라의 기관이에요.","국가 인권 위원회예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_basic#8','soc',3,2,'u1','L10','g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',2,'mc','auto','혼자 사는 사람들을 위한 우리 사회의 노력으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"mc","stem":"혼자 사는 사람들을 위한 우리 사회의 노력으로 알맞은 것은 무엇인가요?","options":[{"t":"혼자 사는 사람이 안전하고 편안하게 살 수 있도록 지원해요","correct":true},{"t":"혼자 사는 사람은 모두 함께 살게 해요","mis":"SO3-2-u1-X29"},{"t":"혼자 사는 사람에게는 도움을 주지 않아요","mis":"SO3-2-u1-X29"},{"t":"혼자 사는 사람은 요리를 배울 수 없어요","mis":"SO3-2-u1-X29"}],"explanation":["혼자 살아요.","안전이 중요해요.","지원해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_basic#9','soc',3,2,'u1','L10','g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',2,'ox','auto','태도 블록 가운데 바람직하지 못한 태도가 하나라도 섞이면 탑이 곧게 서지 않아요.',ARRAY['SO3-2-u1-X30']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"ox","stem":"태도 블록 가운데 바람직하지 못한 태도가 하나라도 섞이면 탑이 곧게 서지 않아요.","answer":"O","reason_options":[{"t":"다양한 문화가 존중받으려면 모두가 바람직한 태도를 가져야 하기 때문에","correct":true},{"t":"잘 보이지 않는 곳의 태도는 괜찮기 때문에","mis":"SO3-2-u1-X30"}],"mis":"SO3-2-u1-X30","explanation":["하나만 섞여도 기울어요.","모두 바람직해야 해요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 다른 문화에 대한 편견을 갖지 않고 차별하지 않아요.","㉡ 외국인 이주민을 무시하고 경계해요.","㉢ 다른 문화의 사람들이 겪는 어려움에 관심을 가져요.","㉣ 1인 가구의 사람들을 이상하다고 생각해요.","㉤ 서로 다른 문화를 이해하고 존중해요.","㉥ 반려동물을 가족이라고 생각하는 사람들을 비난해요."],"title":"태도 블록 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_basic#10','soc',3,2,'u1','L10','g3_2_soc_u1_L10_basic','lesson_basic','SO3-2-u1-C10',3,'error','auto','다양한 문화를 대하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X31','SO3-2-u1-X30']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"error","stem":"다양한 문화를 대하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「다른 문화보다 우리 문화를 더 소중하게 여겨야 해.」","correct":true,"mis_target":"SO3-2-u1-X31"},{"t":"친구 가 — 「서로 다른 문화를 이해하고 존중해야 해.」","mis":"SO3-2-u1-X31"},{"t":"친구 나 — 「편견을 갖지 않고 차별하지 않아야 해.」","mis":"SO3-2-u1-X30"}],"explanation":["누구 문화가 더 소중할까요?","모두 존중해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_challenge#1','soc',3,2,'u1','L10','g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',2,'sa','auto','서로 다른 문화를 대할 때 필요한 태도 「서로 다름을 인정하고 ○○해요」의 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"sa","stem":"서로 다른 문화를 대할 때 필요한 태도 「서로 다름을 인정하고 ○○해요」의 ○○에 알맞은 두 글자를 쓰세요.","answer":["존중"],"explanation":["귀하게 여겨요.","존◯이에요.","존중이에요."],"mis":"SO3-2-u1-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_challenge#2','soc',3,2,'u1','L10','g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',2,'ox','auto','다양한 문화의 확산으로 나타난 문제는 저절로 사라지므로 아무 노력도 하지 않아도 돼요.',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"ox","stem":"다양한 문화의 확산으로 나타난 문제는 저절로 사라지므로 아무 노력도 하지 않아도 돼요.","answer":"X","reason_options":[{"t":"문제를 예방하고 해결하려면 우리 사회와 우리 모두가 함께 노력해야 하기 때문에","correct":true},{"t":"문제는 시간이 지나면 언제나 저절로 풀리기 때문에","mis":"SO3-2-u1-X29"}],"mis":"SO3-2-u1-X29","explanation":["저절로 사라지지 않아요.","노력이 필요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_challenge#3','soc',3,2,'u1','L10','g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',3,'mc','auto','내가 미나와 같은 반 친구라면 할 수 있는 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X30']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"내가 미나와 같은 반 친구라면 할 수 있는 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"미나에게 먼저 다가가 이야기를 나누고 어려움에 관심을 가져요","correct":true},{"t":"미나의 모자를 벗기고 놀려요","mis":"SO3-2-u1-X30"},{"t":"미나와 놀지 않아요","mis":"SO3-2-u1-X30"},{"t":"미나의 피부색이 이상하다고 말해요","mis":"SO3-2-u1-X30"}],"explanation":["미나의 마음을 생각해요.","먼저 다가가요.","관심을 가져요."],"asset":{"type":"passage","lines":["만화 영화 속 미나는 집 밖에 나갈 때 늘 모자를 써요.","다른 사람들이 자기 피부색을 이상하게 여긴다고 생각하기 때문이에요."],"title":"만화 영화 속 미나 이야기(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_challenge#4','soc',3,2,'u1','L10','g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',3,'mc','auto','자료의 ㉤과 같은 디자인이 필요한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"자료의 ㉤과 같은 디자인이 필요한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"나이, 국적, 언어, 장애 등과 관계없이 누구나 편하게 쓸 수 있게 하려고","correct":true},{"t":"값비싼 물건을 많이 팔려고","mis":"SO3-2-u1-X29"},{"t":"어른만 쓸 수 있게 하려고","mis":"SO3-2-u1-X29"},{"t":"한 나라 사람만 쓸 수 있게 하려고","mis":"SO3-2-u1-X29"}],"explanation":["누구나 써요.","조건과 관계없어요.","편하게 쓰려고요."],"asset":{"type":"passage","lines":["㉠ 한국 생활에 필요한 정보를 다양한 언어로 알려 준다.","㉡ 국가 인권 위원회가 편견과 차별을 막는 제도를 만든다.","㉢ 혼자 사는 사람을 위한 프로그램을 운영한다.","㉣ 반려견과 산책할 때 입마개를 하고 목줄을 채운다.","㉤ 누구나 쓰기 쉽도록 물건과 시설을 디자인한다."],"title":"문제를 해결하려는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_challenge#5','soc',3,2,'u1','L10','g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',3,'mc','auto','세 칸 탑을 곧게 쌓으려면 어떤 블록으로 쌓아야 하나요?',ARRAY['SO3-2-u1-X30']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"세 칸 탑을 곧게 쌓으려면 어떤 블록으로 쌓아야 하나요?","options":[{"t":"㉠, ㉢, ㉤으로만 쌓아요","correct":true},{"t":"어떤 블록이든 세 개만 쌓으면 돼요","mis":"SO3-2-u1-X30"},{"t":"㉡을 맨 아래에 두면 괜찮아요","mis":"SO3-2-u1-X30"},{"t":"㉣과 ㉥을 함께 쌓아요","mis":"SO3-2-u1-X30"}],"explanation":["바람직한 블록만이에요.","하나도 섞으면 안 돼요.","㉠, ㉢, ㉤이에요."],"asset":{"type":"passage","lines":["㉠ 다른 문화에 대한 편견을 갖지 않고 차별하지 않아요.","㉡ 외국인 이주민을 무시하고 경계해요.","㉢ 다른 문화의 사람들이 겪는 어려움에 관심을 가져요.","㉣ 1인 가구의 사람들을 이상하다고 생각해요.","㉤ 서로 다른 문화를 이해하고 존중해요.","㉥ 반려동물을 가족이라고 생각하는 사람들을 비난해요."],"title":"태도 블록 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_challenge#6','soc',3,2,'u1','L10','g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',3,'error','auto','문제를 해결하려는 노력을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"error","stem":"문제를 해결하려는 노력을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉡은 반려동물에게 새 주인을 찾아 주는 일이야.」","correct":true,"mis_target":"SO3-2-u1-X29"},{"t":"친구 가 — 「㉠은 한국어에 서툰 외국인을 도와.」","mis":"SO3-2-u1-X29"},{"t":"친구 다 — 「㉣은 물림 사고를 막아.」","mis":"SO3-2-u1-X29"}],"explanation":["㉡은 인권이에요.","편견과 차별을 막아요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 한국 생활에 필요한 정보를 다양한 언어로 알려 준다.","㉡ 국가 인권 위원회가 편견과 차별을 막는 제도를 만든다.","㉢ 혼자 사는 사람을 위한 프로그램을 운영한다.","㉣ 반려견과 산책할 때 입마개를 하고 목줄을 채운다.","㉤ 누구나 쓰기 쉽도록 물건과 시설을 디자인한다."],"title":"문제를 해결하려는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_challenge#7','soc',3,2,'u1','L10','g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',3,'ox','auto','억울하게 차별을 당했을 때 도움을 요청할 수 있는 기관이 있어요.',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"ox","stem":"억울하게 차별을 당했을 때 도움을 요청할 수 있는 기관이 있어요.","answer":"O","reason_options":[{"t":"국가 인권 위원회가 편견과 차별을 막는 일을 하기 때문에","correct":true},{"t":"차별은 혼자서만 해결해야 하기 때문에","mis":"SO3-2-u1-X29"}],"mis":"SO3-2-u1-X29","explanation":["도움을 청할 곳이 있어요.","나라의 기관이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_challenge#8','soc',3,2,'u1','L10','g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',4,'mc','auto','다양한 문화의 확산으로 나타난 문제를 해결하는 방법을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X31','SO3-2-u1-X29','SO3-2-u1-X30']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C10","difficulty":4,"kind":"mc","stem":"다양한 문화의 확산으로 나타난 문제를 해결하는 방법을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"서로 다름을 인정하고 존중하는 태도를 갖고, 우리 사회도 문제를 예방하고 해결하려고 여러 노력을 해요","correct":true},{"t":"다른 문화보다 우리 문화를 더 소중히 여겨요","mis":"SO3-2-u1-X31"},{"t":"문제는 저절로 사라지니 노력하지 않아요","mis":"SO3-2-u1-X29"},{"t":"바람직하지 못한 태도도 조금은 괜찮아요","mis":"SO3-2-u1-X30"}],"explanation":["태도가 필요해요.","사회도 노력해요.","함께해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_challenge#9','soc',3,2,'u1','L10','g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',4,'mc','auto','우리 반 실천 약속으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X30']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C10","difficulty":4,"kind":"mc","stem":"우리 반 실천 약속으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다른 문화를 가진 친구를 놀리지 않고 먼저 다가가요","correct":true},{"t":"우리와 다른 친구는 모둠에 넣지 않아요","mis":"SO3-2-u1-X30"},{"t":"반려동물을 기르는 친구를 비난해요","mis":"SO3-2-u1-X30"},{"t":"혼자 사는 사람을 이상하게 봐요","mis":"SO3-2-u1-X30"}],"explanation":["존중하는 약속이에요.","먼저 다가가요.","놀리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L10_challenge#10','soc',3,2,'u1','L10','g3_2_soc_u1_L10_challenge','lesson_challenge','SO3-2-u1-C10',4,'essay','teacher','미나 이야기를 읽고 미나가 겪는 어려움을 쓰고, 미나를 위해 내가 할 수 있는 일과 우리 사회가 하는 노력을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C10","difficulty":4,"kind":"essay","stem":"미나 이야기를 읽고 미나가 겪는 어려움을 쓰고, 미나를 위해 내가 할 수 있는 일과 우리 사회가 하는 노력을 하나씩 쓰세요.","answer_guide":{"answer":"예: 미나는 사람들이 자기 피부색을 이상하게 여긴다고 생각해 늘 모자를 써요. 나는 미나에게 먼저 다가가 함께 놀고, 모자를 벗은 모습도 이상하지 않다고 말해 줄 거예요. 우리 사회는 국가 인권 위원회를 두어 편견과 차별을 막으려고 노력해요.","scoring_points":["미나의 어려움을 썼는가","내가 할 수 있는 일을 썼는가","사회의 노력을 썼는가"]},"explanation":["미나의 마음을 생각해요.","내가 할 일을 써요.","사회의 노력도 써요."],"asset":{"type":"passage","lines":["만화 영화 속 미나는 집 밖에 나갈 때 늘 모자를 써요.","다른 사람들이 자기 피부색을 이상하게 여긴다고 생각하기 때문이에요."],"title":"만화 영화 속 미나 이야기(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_basic#1','soc',3,2,'u1','L11','g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',1,'mc','auto','자료의 설명 가운데 문화의 뜻에 비추어 알맞지 않은 것은 무엇인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X25']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C11","difficulty":1,"kind":"mc","stem":"자료의 설명 가운데 문화의 뜻에 비추어 알맞지 않은 것은 무엇인가요?","options":[{"t":"①","correct":true},{"t":"②","mis":"SO3-2-u1-X20"},{"t":"③","mis":"SO3-2-u1-X25"},{"t":"⑤","mis":"SO3-2-u1-X25"}],"explanation":["문화의 뜻을 떠올려요.","타고난 행동이에요.","①이에요."],"asset":{"type":"passage","lines":["① 배가 고파서 음식을 먹는 행동도 문화예요.","② 문화는 함께 생활하며 만들어지고 오래 전해져 내려오기도 해요.","③ 세계화의 영향으로 우리나라에 사는 외국인 이주민이 늘었어요.","④ 결혼에 관한 생각 변화 등으로 1인 가구가 줄어들고 있어요.","⑤ 반려동물과 관련 있는 문화가 널리 퍼지고 있어요.","⑥ 다양한 문화가 퍼지며 낯선 문화에 대한 편견과 차별이 생기기도 해요."],"title":"알맞은 설명 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_basic#2','soc',3,2,'u1','L11','g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',1,'sa','auto','자료의 ④를 알맞게 고치면 「1인 가구가 ○○○고 있어요」예요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C11","difficulty":1,"kind":"sa","stem":"자료의 ④를 알맞게 고치면 「1인 가구가 ○○○고 있어요」예요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["늘어나"],"explanation":["줄어드는 게 아니에요.","반대말이에요.","늘어나예요."],"asset":{"type":"passage","lines":["① 배가 고파서 음식을 먹는 행동도 문화예요.","② 문화는 함께 생활하며 만들어지고 오래 전해져 내려오기도 해요.","③ 세계화의 영향으로 우리나라에 사는 외국인 이주민이 늘었어요.","④ 결혼에 관한 생각 변화 등으로 1인 가구가 줄어들고 있어요.","⑤ 반려동물과 관련 있는 문화가 널리 퍼지고 있어요.","⑥ 다양한 문화가 퍼지며 낯선 문화에 대한 편견과 차별이 생기기도 해요."],"title":"알맞은 설명 고르기"},"mis":"SO3-2-u1-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_basic#3','soc',3,2,'u1','L11','g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',1,'ox','auto','자료의 ⑥은 알맞은 설명이에요.',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C11","difficulty":1,"kind":"ox","stem":"자료의 ⑥은 알맞은 설명이에요.","answer":"O","reason_options":[{"t":"다양한 문화가 퍼지며 낯선 문화에 대한 편견과 차별이 생기기도 하기 때문에","correct":true},{"t":"다양한 문화가 퍼지면 좋은 점만 생기기 때문에","mis":"SO3-2-u1-X26"}],"mis":"SO3-2-u1-X26","explanation":["문제도 생겨요.","편견과 차별이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 배가 고파서 음식을 먹는 행동도 문화예요.","② 문화는 함께 생활하며 만들어지고 오래 전해져 내려오기도 해요.","③ 세계화의 영향으로 우리나라에 사는 외국인 이주민이 늘었어요.","④ 결혼에 관한 생각 변화 등으로 1인 가구가 줄어들고 있어요.","⑤ 반려동물과 관련 있는 문화가 널리 퍼지고 있어요.","⑥ 다양한 문화가 퍼지며 낯선 문화에 대한 편견과 차별이 생기기도 해요."],"title":"알맞은 설명 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_basic#4','soc',3,2,'u1','L11','g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',1,'mc','auto','축제 초대장을 만들 때 가장 먼저 할 일은 무엇인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C11","difficulty":1,"kind":"mc","stem":"축제 초대장을 만들 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"축제 주제 정하기","correct":true},{"t":"초청하는 글 쓰기","mis":"SO3-2-u1-X32"},{"t":"장소 정하기","mis":"SO3-2-u1-X32"},{"t":"프로그램 계획하기","mis":"SO3-2-u1-X32"}],"explanation":["무엇에 관한 축제일까요?","주제가 먼저예요.","주제 정하기예요."],"asset":{"type":"passage","lines":["① 축제 주제 정하기","② 프로그램 계획하기","③ 내용과 장소 정하기","④ 초청하는 글 쓰기"],"title":"축제 초대장 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_basic#5','soc',3,2,'u1','L11','g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',2,'mc','auto','반려동물 축제 프로그램으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"mc","stem":"반려동물 축제 프로그램으로 알맞은 것은 무엇인가요?","options":[{"t":"반려동물 예절 배우기","correct":true},{"t":"1인 가구 음식 만들기","mis":"SO3-2-u1-X32"},{"t":"1인 가구 생활용품 체험하기","mis":"SO3-2-u1-X32"},{"t":"세계 여러 나라 인사말 배우기","mis":"SO3-2-u1-X32"}],"explanation":["반려동물과 관계있어요.","예절을 배워요.","반려동물 예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_basic#6','soc',3,2,'u1','L11','g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',2,'match','auto','축제 주제와 어울리는 프로그램을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"match","stem":"축제 주제와 어울리는 프로그램을 알맞게 이으세요.","pairs":[{"l":"외국인 이주민 축제","r":"세계 여러 나라의 문화 체험하기"},{"l":"1인 가구 축제","r":"1인 가구 음식 만들기"},{"l":"반려동물 축제","r":"나의 반려동물 소개하기"}],"mis":"SO3-2-u1-X32","explanation":["세계 문화예요.","혼자 만드는 음식이에요.","반려동물 소개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_basic#7','soc',3,2,'u1','L11','g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',2,'blank','auto','문화는 사람들이 함께 생활하면서 만들어지고 오랫동안 (    ) 내려오기도 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X20']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"blank","stem":"문화는 사람들이 함께 생활하면서 만들어지고 오랫동안 (    ) 내려오기도 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"전해져","correct":true},{"t":"사라져","mis":"SO3-2-u1-X20"},{"t":"잊혀","mis":"SO3-2-u1-X20"},{"t":"숨겨져","mis":"SO3-2-u1-X20"}],"explanation":["이어져 와요.","오래 이어져요.","전해져예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_basic#8','soc',3,2,'u1','L11','g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',2,'mc','auto','자료의 설명 가운데 알맞은 것끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X25']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"mc","stem":"자료의 설명 가운데 알맞은 것끼리 묶은 것은 무엇인가요?","options":[{"t":"②, ③, ⑤, ⑥","correct":true},{"t":"①, ②, ③, ④","mis":"SO3-2-u1-X20"},{"t":"①, ④, ⑤, ⑥","mis":"SO3-2-u1-X25"},{"t":"②, ③, ④, ⑤","mis":"SO3-2-u1-X25"}],"explanation":["①은 타고난 행동이에요.","④는 거꾸로예요.","나머지가 알맞아요."],"asset":{"type":"passage","lines":["① 배가 고파서 음식을 먹는 행동도 문화예요.","② 문화는 함께 생활하며 만들어지고 오래 전해져 내려오기도 해요.","③ 세계화의 영향으로 우리나라에 사는 외국인 이주민이 늘었어요.","④ 결혼에 관한 생각 변화 등으로 1인 가구가 줄어들고 있어요.","⑤ 반려동물과 관련 있는 문화가 널리 퍼지고 있어요.","⑥ 다양한 문화가 퍼지며 낯선 문화에 대한 편견과 차별이 생기기도 해요."],"title":"알맞은 설명 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_basic#9','soc',3,2,'u1','L11','g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',2,'ox','auto','다양한 문화를 대할 때는 서로 다름을 인정하고 존중하는 태도가 필요해요.',ARRAY['SO3-2-u1-X31']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"ox","stem":"다양한 문화를 대할 때는 서로 다름을 인정하고 존중하는 태도가 필요해요.","answer":"O","reason_options":[{"t":"다양한 문화가 함께 어울려 살아가려면 서로를 존중해야 하기 때문에","correct":true},{"t":"우리 문화와 다른 것은 받아들이지 않아야 하기 때문에","mis":"SO3-2-u1-X31"}],"mis":"SO3-2-u1-X31","explanation":["함께 살아요.","존중해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_basic#10','soc',3,2,'u1','L11','g3_2_soc_u1_L11_basic','lesson_basic','SO3-2-u1-C11',3,'error','auto','축제 초대장을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"error","stem":"축제 초대장을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「초청하는 글부터 쓰고 주제는 마지막에 정하자.」","correct":true,"mis_target":"SO3-2-u1-X32"},{"t":"친구 나 — 「주제를 정하고 프로그램을 계획하자.」","mis":"SO3-2-u1-X32"},{"t":"친구 다 — 「내용과 장소를 정한 뒤 초청하는 글을 쓰자.」","mis":"SO3-2-u1-X32"}],"explanation":["차례가 있어요.","주제가 먼저예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_challenge#1','soc',3,2,'u1','L11','g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',2,'sa','auto','초대장에서 사람들을 축제에 오라고 부르는 글을 「○○하는 글」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"sa","stem":"초대장에서 사람들을 축제에 오라고 부르는 글을 「○○하는 글」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["초청"],"explanation":["오라고 불러요.","초◯이에요.","초청이에요."],"mis":"SO3-2-u1-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_challenge#2','soc',3,2,'u1','L11','g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',2,'ox','auto','자료의 ①은 알맞은 설명이에요.',ARRAY['SO3-2-u1-X20']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"ox","stem":"자료의 ①은 알맞은 설명이에요.","answer":"X","reason_options":[{"t":"배고파서 먹는 것처럼 태어날 때부터 하는 행동은 문화가 아니기 때문에","correct":true},{"t":"사람이 하는 행동은 모두 문화이기 때문에","mis":"SO3-2-u1-X20"}],"mis":"SO3-2-u1-X20","explanation":["타고난 행동이에요.","문화가 아니에요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 배가 고파서 음식을 먹는 행동도 문화예요.","② 문화는 함께 생활하며 만들어지고 오래 전해져 내려오기도 해요.","③ 세계화의 영향으로 우리나라에 사는 외국인 이주민이 늘었어요.","④ 결혼에 관한 생각 변화 등으로 1인 가구가 줄어들고 있어요.","⑤ 반려동물과 관련 있는 문화가 널리 퍼지고 있어요.","⑥ 다양한 문화가 퍼지며 낯선 문화에 대한 편견과 차별이 생기기도 해요."],"title":"알맞은 설명 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_challenge#3','soc',3,2,'u1','L11','g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',3,'mc','auto','자료에서 알맞지 않은 설명을 바르게 고친 것은 무엇인가요?',ARRAY['SO3-2-u1-X25','SO3-2-u1-X26','SO3-2-u1-X20']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"mc","stem":"자료에서 알맞지 않은 설명을 바르게 고친 것은 무엇인가요?","options":[{"t":"④ — 결혼에 관한 생각 변화 등으로 1인 가구가 늘어나고 있어요","correct":true},{"t":"③ — 외국인 이주민이 줄어들고 있어요","mis":"SO3-2-u1-X25"},{"t":"⑥ — 다양한 문화가 퍼져도 아무 문제가 없어요","mis":"SO3-2-u1-X26"},{"t":"② — 문화는 한 사람이 하루 만에 만들어요","mis":"SO3-2-u1-X20"}],"explanation":["④를 고쳐요.","줄어든다가 거꾸로예요.","늘어나고 있어요."],"asset":{"type":"passage","lines":["① 배가 고파서 음식을 먹는 행동도 문화예요.","② 문화는 함께 생활하며 만들어지고 오래 전해져 내려오기도 해요.","③ 세계화의 영향으로 우리나라에 사는 외국인 이주민이 늘었어요.","④ 결혼에 관한 생각 변화 등으로 1인 가구가 줄어들고 있어요.","⑤ 반려동물과 관련 있는 문화가 널리 퍼지고 있어요.","⑥ 다양한 문화가 퍼지며 낯선 문화에 대한 편견과 차별이 생기기도 해요."],"title":"알맞은 설명 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_challenge#4','soc',3,2,'u1','L11','g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',3,'mc','auto','알맞은 설명만 골라 그 힌트를 따라가야 원하는 곳에 가는 버스를 찾을 수 있었어요. 이것으로 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X32']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"mc","stem":"알맞은 설명만 골라 그 힌트를 따라가야 원하는 곳에 가는 버스를 찾을 수 있었어요. 이것으로 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"문화와 우리 사회의 다양한 문화를 바르게 알아야 헷갈리지 않아요","correct":true},{"t":"설명을 읽지 않아도 버스를 찾을 수 있어요","mis":"SO3-2-u1-X20"},{"t":"설명이 알맞은지는 따지지 않아도 돼요","mis":"SO3-2-u1-X20"},{"t":"버스는 아무거나 타도 돼요","mis":"SO3-2-u1-X32"}],"explanation":["알맞은 설명이 필요해요.","바르게 알아야 해요.","헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_challenge#5','soc',3,2,'u1','L11','g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',3,'mc','auto','다양한 문화를 알리는 축제를 여는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X31','SO3-2-u1-X30','SO3-2-u1-X32']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"mc","stem":"다양한 문화를 알리는 축제를 여는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"서로 다른 문화를 이해하고 함께 즐기며 존중하는 마음을 키우려고","correct":true},{"t":"한 가지 문화만 알리려고","mis":"SO3-2-u1-X31"},{"t":"다른 문화를 놀리려고","mis":"SO3-2-u1-X30"},{"t":"축제는 아무 까닭 없이 열려요","mis":"SO3-2-u1-X32"}],"explanation":["함께 즐겨요.","이해해요.","존중을 키워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_challenge#6','soc',3,2,'u1','L11','g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',3,'error','auto','다양한 문화를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X26','SO3-2-u1-X20','SO3-2-u1-X25']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"error","stem":"다양한 문화를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「다양한 문화가 퍼지면 좋은 점만 있어.」","correct":true,"mis_target":"SO3-2-u1-X26"},{"t":"친구 가 — 「문화는 공통의 생활 양식이야.」","mis":"SO3-2-u1-X20"},{"t":"친구 나 — 「반려동물과 관련 있는 문화가 퍼지고 있어.」","mis":"SO3-2-u1-X25"}],"explanation":["문제도 있어요.","두 면이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_challenge#7','soc',3,2,'u1','L11','g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',3,'ox','auto','축제 초대장에는 축제 주제, 프로그램, 장소가 들어가야 받는 사람이 잘 알 수 있어요.',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"ox","stem":"축제 초대장에는 축제 주제, 프로그램, 장소가 들어가야 받는 사람이 잘 알 수 있어요.","answer":"O","reason_options":[{"t":"무엇을 하는지, 어디서 하는지 알아야 찾아올 수 있기 때문에","correct":true},{"t":"초대장에는 그림만 있으면 되기 때문에","mis":"SO3-2-u1-X32"}],"mis":"SO3-2-u1-X32","explanation":["무엇을 하나요?","어디서 하나요?","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_challenge#8','soc',3,2,'u1','L11','g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',4,'mc','auto','「다양한 문화에 대한 이해와 존중」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X26','SO3-2-u1-X31']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C11","difficulty":4,"kind":"mc","stem":"「다양한 문화에 대한 이해와 존중」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"문화는 한 사회의 공통의 생활 양식이고, 다양한 문화를 대할 때는 서로 다름을 인정하고 존중해야 해요","correct":true},{"t":"사람이라면 누구나 하는 행동이 모두 문화예요","mis":"SO3-2-u1-X20"},{"t":"다양한 문화가 퍼지면 좋은 점만 생겨요","mis":"SO3-2-u1-X26"},{"t":"우리 문화만 소중히 여기면 돼요","mis":"SO3-2-u1-X31"}],"explanation":["문화의 뜻이에요.","다양한 문화예요.","존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_challenge#9','soc',3,2,'u1','L11','g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',4,'mc','auto','1인 가구 축제 초대장을 차례대로 만든다면 ③ 단계에서 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C11","difficulty":4,"kind":"mc","stem":"1인 가구 축제 초대장을 차례대로 만든다면 ③ 단계에서 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"축제에서 할 내용과 열릴 장소를 정해요","correct":true},{"t":"축제 주제를 정해요","mis":"SO3-2-u1-X32"},{"t":"초청하는 글을 써요","mis":"SO3-2-u1-X32"},{"t":"초대장을 친구에게 나눠 줘요","mis":"SO3-2-u1-X32"}],"explanation":["③을 찾아요.","내용과 장소예요.","그것을 정해요."],"asset":{"type":"passage","lines":["① 축제 주제 정하기","② 프로그램 계획하기","③ 내용과 장소 정하기","④ 초청하는 글 쓰기"],"title":"축제 초대장 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_L11_challenge#10','soc',3,2,'u1','L11','g3_2_soc_u1_L11_challenge','lesson_challenge','SO3-2-u1-C11',4,'essay','teacher','우리 사회의 다양한 문화를 알리는 축제를 하나 골라 축제 이름과 프로그램 두 가지를 쓰고, 그 축제로 사람들이 무엇을 느끼면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u1-C11","difficulty":4,"kind":"essay","stem":"우리 사회의 다양한 문화를 알리는 축제를 하나 골라 축제 이름과 프로그램 두 가지를 쓰고, 그 축제로 사람들이 무엇을 느끼면 좋을지 쓰세요.","answer_guide":{"answer":"예: 「함께해요 반려동물 축제」를 열고 싶어요. 프로그램은 나의 반려동물 소개하기와 반려동물 예절 배우기예요. 사람들이 반려동물과 함께 사는 이웃을 이해하고 서로 배려하는 마음을 느끼면 좋겠어요.","scoring_points":["축제 이름을 썼는가","어울리는 프로그램 두 가지를 썼는가","이해와 존중으로 이어 썼는가"]},"explanation":["주제를 골라요.","프로그램을 써요.","느낄 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#1','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C1',1,'mc','auto','사회를 바꾸는 원인이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"mc","stem":"사회를 바꾸는 원인이 아닌 것은 무엇인가요?","options":[{"t":"해가 뜨고 지는 것","correct":true},{"t":"사람 수의 변화","mis":"SO3-2-u1-X02"},{"t":"과학 기술의 발달","mis":"SO3-2-u1-X02"},{"t":"다른 나라와의 교류","mis":"SO3-2-u1-X02"}],"explanation":["원인을 떠올려요.","생활을 바꾸는 일이에요.","아닌 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#2','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C2',1,'mc','auto','저출산이 계속되면 줄어드는 것은 무엇인가요?',ARRAY['SO3-2-u1-X06','SO3-2-u1-X08','SO3-2-u1-X07']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"mc","stem":"저출산이 계속되면 줄어드는 것은 무엇인가요?","options":[{"t":"학생 수","correct":true},{"t":"노인 복지관","mis":"SO3-2-u1-X06"},{"t":"노인의 비율","mis":"SO3-2-u1-X08"},{"t":"출산을 돕는 제도","mis":"SO3-2-u1-X07"}],"explanation":["아이가 줄어요.","학교에 다닐 어린이예요.","학생 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#3','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C4',1,'mc','auto','인공지능을 활용한 다양한 기술이 사회 전반에 폭넓은 영향을 미치는 현상을 무엇이라고 하나요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"mc","stem":"인공지능을 활용한 다양한 기술이 사회 전반에 폭넓은 영향을 미치는 현상을 무엇이라고 하나요?","options":[{"t":"지능정보화","correct":true},{"t":"세계화","mis":"SO3-2-u1-X18"},{"t":"고령화","mis":"SO3-2-u1-X18"},{"t":"저출산","mis":"SO3-2-u1-X18"}],"explanation":["인공지능이에요.","넓은 영향이에요.","지능정보화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#4','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C5',1,'mc','auto','세계화로 나타난 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X15']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"mc","stem":"세계화로 나타난 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"다른 나라 영화를 우리나라에서 봐요","correct":true},{"t":"먼 나라 소식을 전혀 알 수 없어요","mis":"SO3-2-u1-X15"},{"t":"우리 마을 채소만 먹어요","mis":"SO3-2-u1-X15"},{"t":"다른 나라와 물건을 주고받지 않아요","mis":"SO3-2-u1-X15"}],"explanation":["여러 나라가 이어져요.","영화도 들어와요.","볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#5','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C7',1,'mc','auto','한 사회의 사람들이 지닌 공통의 생활 양식을 가리키는 말은 무엇인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X21']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"mc","stem":"한 사회의 사람들이 지닌 공통의 생활 양식을 가리키는 말은 무엇인가요?","options":[{"t":"문화","correct":true},{"t":"편견","mis":"SO3-2-u1-X20"},{"t":"규범","mis":"SO3-2-u1-X21"},{"t":"비율","mis":"SO3-2-u1-X21"}],"explanation":["공통의 생활 양식이에요.","사회마다 있어요.","문화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#6','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C8',1,'mc','auto','부모나 자녀, 형제 등과 같이 살지 않고 혼자 사는 경우를 무엇이라고 하나요?',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"mc","stem":"부모나 자녀, 형제 등과 같이 살지 않고 혼자 사는 경우를 무엇이라고 하나요?","options":[{"t":"1인 가구","correct":true},{"t":"이주민","mis":"SO3-2-u1-X24"},{"t":"반려동물","mis":"SO3-2-u1-X24"},{"t":"대가족","mis":"SO3-2-u1-X24"}],"explanation":["혼자 살아요.","한 사람이에요.","1인 가구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#7','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C9',1,'mc','auto','편견을 가지고 대상을 다르게 대우하는 것을 무엇이라고 하나요?',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"mc","stem":"편견을 가지고 대상을 다르게 대우하는 것을 무엇이라고 하나요?","options":[{"t":"차별","correct":true},{"t":"편견","mis":"SO3-2-u1-X27"},{"t":"존중","mis":"SO3-2-u1-X27"},{"t":"배려","mis":"SO3-2-u1-X27"}],"explanation":["행동이에요.","다르게 대해요.","차별이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#8','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C10',1,'mc','auto','서로 다른 문화를 가진 사람들과 더불어 살아갈 때 필요한 태도로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X30']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C10","difficulty":1,"kind":"mc","stem":"서로 다른 문화를 가진 사람들과 더불어 살아갈 때 필요한 태도로 알맞은 것은 무엇인가요?","options":[{"t":"서로 다른 문화를 이해하고 존중해요","correct":true},{"t":"외국인 이주민을 무시해요","mis":"SO3-2-u1-X30"},{"t":"1인 가구를 이상하게 생각해요","mis":"SO3-2-u1-X30"},{"t":"반려동물과 사는 사람을 비난해요","mis":"SO3-2-u1-X30"}],"explanation":["바람직한 태도예요.","이해해요.","존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#9','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C2',2,'mc','auto','신문 ①에서 학생 수가 줄어든 까닭과 가장 관계있는 사회 변화는 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"mc","stem":"신문 ①에서 학생 수가 줄어든 까닭과 가장 관계있는 사회 변화는 무엇인가요?","options":[{"t":"저출산","correct":true},{"t":"고령화","mis":"SO3-2-u1-X18"},{"t":"지능정보화","mis":"SO3-2-u1-X18"},{"t":"세계화","mis":"SO3-2-u1-X18"}],"explanation":["학생이 줄었어요.","아이가 줄었어요.","저출산이에요."],"asset":{"type":"passage","lines":["우리 학교는 옛날에 한 학년에 반이 아주 많았다.","지금은 학생이 줄어 한 학년에 두 반뿐이다.","근처 어린이집 한 곳은 원생이 부족해 문을 닫았다."],"title":"신문 ① — 우리 학교가 달라졌어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#10','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C3',2,'mc','auto','신문 ②의 모습과 가장 관계있는 사회 변화는 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"mc","stem":"신문 ②의 모습과 가장 관계있는 사회 변화는 무엇인가요?","options":[{"t":"고령화","correct":true},{"t":"저출산","mis":"SO3-2-u1-X18"},{"t":"지능정보화","mis":"SO3-2-u1-X18"},{"t":"세계화","mis":"SO3-2-u1-X18"}],"explanation":["어르신들이에요.","노인이 많아졌어요.","고령화예요."],"asset":{"type":"passage","lines":["동네에 노인 복지관이 새로 문을 열었다.","복지관에서는 노인을 위한 배움 프로그램과 운동 교실이 열린다.","동네 도서관에서는 일자리를 찾은 할아버지가 책 정리를 돕는다."],"title":"신문 ② — 동네 어르신들의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#11','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C4',2,'mc','auto','신문 ③에서 지능정보화로 편리해진 점은 무엇인가요?',ARRAY['SO3-2-u1-X12','SO3-2-u1-X11']::text[],false,'{"seq":11,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"mc","stem":"신문 ③에서 지능정보화로 편리해진 점은 무엇인가요?","options":[{"t":"인공지능 학습 프로그램으로 공부해요","correct":true},{"t":"가짜 뉴스를 믿고 퍼뜨렸어요","mis":"SO3-2-u1-X12"},{"t":"인터넷 약속을 정했어요","mis":"SO3-2-u1-X12"},{"t":"수학 시간이 없어졌어요","mis":"SO3-2-u1-X11"}],"explanation":["편리해진 점이에요.","공부를 도와요.","학습 프로그램이에요."],"asset":{"type":"passage","lines":["우리 반은 인공지능 학습 프로그램으로 수학을 공부한다.","그런데 가짜 뉴스를 그대로 믿고 대화방에 퍼뜨린 일이 있었다.","그래서 우리 반은 인터넷 사용 약속을 함께 정했다."],"title":"신문 ③ — 인공지능과 함께하는 우리 반"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#12','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C5',2,'mc','auto','신문 ④에서 우리 동네에서 다른 나라로 「나간」 모습은 무엇인가요?',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":12,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"mc","stem":"신문 ④에서 우리 동네에서 다른 나라로 「나간」 모습은 무엇인가요?","options":[{"t":"동네 회사가 다른 나라에 공장을 지었어요","correct":true},{"t":"다른 나라 과일 가게가 생겼어요","mis":"SO3-2-u1-X16"},{"t":"다른 나라 과일을 사 먹어요","mis":"SO3-2-u1-X16"},{"t":"아무것도 나가지 않았어요","mis":"SO3-2-u1-X16"}],"explanation":["우리 동네 회사예요.","다른 나라에 지었어요.","공장이에요."],"asset":{"type":"passage","lines":["동네 시장에 다른 나라 과일을 파는 가게가 생겼다.","우리 동네의 한 회사는 다른 나라에 공장을 지었다.","다른 나라 친구에게 한국어를 가르쳐 주는 형도 있다."],"title":"신문 ④ — 세계와 이어진 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#13','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C7',2,'mc','auto','신문 ⑤를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X22','SO3-2-u1-X20']::text[],false,'{"seq":13,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"mc","stem":"신문 ⑤를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"모두 생일을 축하하지만 축하하는 방법은 가족마다 달라요","correct":true},{"t":"생일을 축하하는 방법은 모두 똑같아요","mis":"SO3-2-u1-X22"},{"t":"미역국을 먹는 가족만 알맞아요","mis":"SO3-2-u1-X22"},{"t":"생일 축하는 문화가 아니에요","mis":"SO3-2-u1-X20"}],"explanation":["모두 축하해요.","방법이 달라요.","비슷한 점과 다른 점이에요."],"asset":{"type":"passage","lines":["친구 가네 가족은 생일에 미역국을 끓여 먹는다.","친구 나네 가족은 생일에 국수를 먹는다.","친구 다네 가족은 생일에 케이크에 촛불을 켠다."],"title":"신문 ⑤ — 우리 반 생일 축하 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#14','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C8',2,'mc','auto','신문 ⑥에서 베트남 음식점이 생긴 것과 가장 관계있는 사람들은 누구인가요?',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":14,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"mc","stem":"신문 ⑥에서 베트남 음식점이 생긴 것과 가장 관계있는 사람들은 누구인가요?","options":[{"t":"외국인 이주민","correct":true},{"t":"1인 가구","mis":"SO3-2-u1-X24"},{"t":"반려동물과 함께 사는 사람","mis":"SO3-2-u1-X24"},{"t":"노인","mis":"SO3-2-u1-X24"}],"explanation":["다른 나라 음식이에요.","이주민이 늘었어요.","외국인 이주민이에요."],"asset":{"type":"passage","lines":["동네에 베트남 음식점과 반려동물 놀이터가 생겼다.","혼자 사는 이웃을 위한 1인분 반찬 가게도 늘었다.","반려견 짖는 소리 때문에 이웃끼리 다툰 일도 있었다."],"title":"신문 ⑥ — 우리 동네의 다양한 문화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#15','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C9',2,'mc','auto','신문 ⑦에서 몇몇 친구가 한 행동은 무엇에 해당하나요?',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":15,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"mc","stem":"신문 ⑦에서 몇몇 친구가 한 행동은 무엇에 해당하나요?","options":[{"t":"차별","correct":true},{"t":"존중","mis":"SO3-2-u1-X27"},{"t":"배려","mis":"SO3-2-u1-X27"},{"t":"관심","mis":"SO3-2-u1-X27"}],"explanation":["끼워 주지 않았어요.","다르게 대했어요.","차별이에요."],"asset":{"type":"passage","lines":["새로 전학 온 친구는 아직 우리말이 서툴다.","몇몇 친구가 말이 다르다고 놀이에 끼워 주지 않았다.","선생님과 우리 반은 함께 지킬 약속을 만들었다."],"title":"신문 ⑦ — 우리 반에서 생긴 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#16','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C11',2,'mc','auto','신문 ⑧의 축제 계획에서 「프로그램」에 해당하는 것은 무엇인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":16,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"mc","stem":"신문 ⑧의 축제 계획에서 「프로그램」에 해당하는 것은 무엇인가요?","options":[{"t":"여러 나라 인사말 배우기","correct":true},{"t":"학교 강당","mis":"SO3-2-u1-X32"},{"t":"세계 문화 나눔 축제","mis":"SO3-2-u1-X32"},{"t":"초청하는 글","mis":"SO3-2-u1-X32"}],"explanation":["축제에서 하는 활동이에요.","배우고 그려요.","인사말 배우기예요."],"asset":{"type":"passage","lines":["하늘반은 「세계 문화 나눔 축제」를 계획했다.","프로그램 — 여러 나라 인사말 배우기, 세계 음식 그림 그리기","장소 — 학교 강당 · 우리 반이 초청하는 글을 써서 나눠 준다."],"title":"신문 ⑧ — 하늘반 축제 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#17','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C6',3,'mc','auto','사회 변화와 그에 맞는 모습을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":17,"concept":"SO3-2-u1-C6","difficulty":3,"kind":"mc","stem":"사회 변화와 그에 맞는 모습을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"고령화 — 노인 복지관 · 지능정보화 — 배달 로봇 · 세계화 — 세계 음식 가게","correct":true},{"t":"고령화 — 배달 로봇 · 지능정보화 — 세계 음식 가게 · 세계화 — 노인 복지관","mis":"SO3-2-u1-X18"},{"t":"고령화 — 세계 음식 가게 · 지능정보화 — 노인 복지관 · 세계화 — 배달 로봇","mis":"SO3-2-u1-X18"},{"t":"세 사회 변화는 모두 같은 모습이에요","mis":"SO3-2-u1-X18"}],"explanation":["노인이에요.","인공지능이에요.","여러 나라예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#18','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C4',3,'mc','auto','지능정보화와 세계화를 대하는 태도에서 비슷한 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X13','SO3-2-u1-X17','SO3-2-u1-X19']::text[],false,'{"seq":18,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"mc","stem":"지능정보화와 세계화를 대하는 태도에서 비슷한 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"좋은 점은 누리거나 받아들이고, 문제는 따져 보며 보완해요","correct":true},{"t":"좋은 점만 보고 문제는 무시해요","mis":"SO3-2-u1-X13"},{"t":"문제가 있으니 모두 거부해요","mis":"SO3-2-u1-X17"},{"t":"나와는 관계없으니 신경 쓰지 않아요","mis":"SO3-2-u1-X19"}],"explanation":["좋은 점이 있어요.","문제도 있어요.","따져 보며 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#19','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C7',3,'mc','auto','「다른 나라의 학교는 새 학년이 9월에 시작하니 이상해」라는 생각에 대한 판단으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X22','SO3-2-u1-X21']::text[],false,'{"seq":19,"concept":"SO3-2-u1-C7","difficulty":3,"kind":"mc","stem":"「다른 나라의 학교는 새 학년이 9월에 시작하니 이상해」라는 생각에 대한 판단으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"새 학년이 시작하는 때는 사회마다 다를 뿐 이상한 것이 아니에요","correct":true},{"t":"우리 학교만 알맞으니 맞는 생각이에요","mis":"SO3-2-u1-X22"},{"t":"어느 나라나 새 학년은 똑같이 시작해요","mis":"SO3-2-u1-X22"},{"t":"새 학년이 시작하는 때는 문화가 아니에요","mis":"SO3-2-u1-X21"}],"explanation":["다를 수 있어요.","이상한 게 아니에요.","문화의 다양성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#20','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C9',3,'mc','auto','다양한 문화가 퍼지며 나타난 모습을 「좋아진 점」과 「생긴 문제」로 바르게 나눈 것은 무엇인가요?',ARRAY['SO3-2-u1-X28','SO3-2-u1-X26']::text[],false,'{"seq":20,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"mc","stem":"다양한 문화가 퍼지며 나타난 모습을 「좋아진 점」과 「생긴 문제」로 바르게 나눈 것은 무엇인가요?","options":[{"t":"좋아진 점 — 반려동물 관련 직업 증가 · 생긴 문제 — 이웃 간 소음 갈등","correct":true},{"t":"좋아진 점 — 이웃 간 소음 갈등 · 생긴 문제 — 반려동물 관련 직업 증가","mis":"SO3-2-u1-X28"},{"t":"좋아진 점 — 편견과 차별 · 생긴 문제 — 문화 경험 기회 증가","mis":"SO3-2-u1-X28"},{"t":"두 가지 모두 좋아진 점이에요","mis":"SO3-2-u1-X26"}],"explanation":["직업이 늘었어요.","다툼이 생겼어요.","나누어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#21','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C10',3,'mc','auto','다양한 문화가 존중받는 사회를 만드는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X30','SO3-2-u1-X31','SO3-2-u1-X19']::text[],false,'{"seq":21,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"다양한 문화가 존중받는 사회를 만드는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"모두가 바람직한 태도를 갖고, 우리 사회도 문제를 해결하려고 노력해요","correct":true},{"t":"바람직하지 못한 태도도 조금은 괜찮아요","mis":"SO3-2-u1-X30"},{"t":"우리 문화만 소중히 여겨요","mis":"SO3-2-u1-X31"},{"t":"나라만 노력하면 돼요","mis":"SO3-2-u1-X19"}],"explanation":["모두의 태도예요.","사회도 노력해요.","함께해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#22','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C2',3,'mc','auto','「1970년에는 101만 명, 2020년에는 27만 명」이 태어났다는 자료로 알 수 있는 것은 무엇인가요?',ARRAY['SO3-2-u1-X04','SO3-2-u1-X05']::text[],false,'{"seq":22,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"mc","stem":"「1970년에는 101만 명, 2020년에는 27만 명」이 태어났다는 자료로 알 수 있는 것은 무엇인가요?","options":[{"t":"태어나는 아이의 수가 크게 줄었어요","correct":true},{"t":"태어나는 아이의 수가 늘었어요","mis":"SO3-2-u1-X04"},{"t":"변하지 않았어요","mis":"SO3-2-u1-X05"},{"t":"2020년이 더 많아요","mis":"SO3-2-u1-X05"}],"explanation":["두 수를 견줘요.","뒤가 더 작아요.","크게 줄었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#23','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C6',4,'mc','auto','신문 ①~④를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X19','SO3-2-u1-X01','SO3-2-u1-X18']::text[],false,'{"seq":23,"concept":"SO3-2-u1-C6","difficulty":4,"kind":"mc","stem":"신문 ①~④를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"저출산, 고령화, 지능정보화, 세계화로 우리 동네의 생활 모습도 달라지고 있어요","correct":true},{"t":"사회 변화는 먼 곳의 일이에요","mis":"SO3-2-u1-X19"},{"t":"우리 동네는 변하지 않았어요","mis":"SO3-2-u1-X01"},{"t":"한 가지 변화만 일어났어요","mis":"SO3-2-u1-X18"}],"explanation":["①은 학생이에요.","②는 노인, ③은 인공지능이에요.","④는 세계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#24','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C2',4,'essay','teacher','신문 ①의 모습이 나타난 까닭을 사회 변화와 이어 쓰고, 이 문제를 해결하기 위한 노력을 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u1-C2","difficulty":4,"kind":"essay","stem":"신문 ①의 모습이 나타난 까닭을 사회 변화와 이어 쓰고, 이 문제를 해결하기 위한 노력을 하나 쓰세요.","answer_guide":{"answer":"예: 태어나는 아이의 수가 줄어드는 저출산 때문에 학생과 원생이 줄어 반이 줄고 어린이집이 문을 닫았어요. 아이를 낳고 키우는 데 필요한 돈과 물품을 지원하면 부담이 줄어 도움이 될 수 있어요.","scoring_points":["저출산과 이어 까닭을 썼는가","해결 노력을 하나 썼는가","노력이 문제를 어떻게 돕는지 썼는가"]},"explanation":["학생이 줄었어요.","저출산이에요.","노력을 써요."],"asset":{"type":"passage","lines":["우리 학교는 옛날에 한 학년에 반이 아주 많았다.","지금은 학생이 줄어 한 학년에 두 반뿐이다.","근처 어린이집 한 곳은 원생이 부족해 문을 닫았다."],"title":"신문 ① — 우리 학교가 달라졌어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_a#25','soc',3,2,'u1','','g3_2_soc_u1_review_a','unit_review','SO3-2-u1-C7',4,'essay','teacher','신문 ⑤를 보고 세 가족의 생일 축하 모습에서 비슷한 점과 다른 점을 쓰고, 이것으로 알 수 있는 문화의 특징을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u1-C7","difficulty":4,"kind":"essay","stem":"신문 ⑤를 보고 세 가족의 생일 축하 모습에서 비슷한 점과 다른 점을 쓰고, 이것으로 알 수 있는 문화의 특징을 쓰세요.","answer_guide":{"answer":"예: 세 가족 모두 생일을 맞은 사람을 축하한다는 점은 비슷해요. 하지만 미역국, 국수, 케이크처럼 축하하는 방법은 달라요. 이것으로 문화는 비슷한 점도 있고 다른 점도 있다는 것을 알 수 있어요.","scoring_points":["비슷한 점을 썼는가","다른 점을 썼는가","문화의 특징으로 이었는가"]},"explanation":["하는 일을 봐요.","방법을 봐요.","특징을 써요."],"asset":{"type":"passage","lines":["친구 가네 가족은 생일에 미역국을 끓여 먹는다.","친구 나네 가족은 생일에 국수를 먹는다.","친구 다네 가족은 생일에 케이크에 촛불을 켠다."],"title":"신문 ⑤ — 우리 반 생일 축하 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#1','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C1',1,'sa','auto','옛날 학교에서 학생이 많아 나누어 수업한 반을 「오전반, ○○반」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"sa","stem":"옛날 학교에서 학생이 많아 나누어 수업한 반을 「오전반, ○○반」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["오후"],"explanation":["오전의 짝이에요.","◯후예요.","오후예요."],"mis":"SO3-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#2','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C3',1,'sa','auto','교과서에서 노인은 몇 세 이상인 사람인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"sa","stem":"교과서에서 노인은 몇 세 이상인 사람인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["60이 넘어요.","6◯예요.","65예요."],"mis":"SO3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#3','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C4',1,'sa','auto','인터넷이나 스마트폰을 지나치게 이용해 문제가 되는 상태를 「인터넷·스마트폰 ○○○」이라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"sa","stem":"인터넷이나 스마트폰을 지나치게 이용해 문제가 되는 상태를 「인터넷·스마트폰 ○○○」이라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["과의존"],"explanation":["너무 기대요.","과◯◯이에요.","과의존이에요."],"mis":"SO3-2-u1-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#4','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C5',1,'sa','auto','대한민국과 관련 있는 것들이 다른 나라에서 인기를 얻는 현상을 가리키는 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"sa","stem":"대한민국과 관련 있는 것들이 다른 나라에서 인기를 얻는 현상을 가리키는 두 글자 낱말을 쓰세요.","answer":["한류"],"explanation":["한국의 물결이에요.","한◯예요.","한류예요."],"mis":"SO3-2-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#5','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C7',1,'sa','auto','옷, 음식, 집을 함께 이르는 말을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"sa","stem":"옷, 음식, 집을 함께 이르는 말을 세 글자로 쓰세요.","answer":["의식주"],"explanation":["옷·밥·집이에요.","의◯◯예요.","의식주예요."],"mis":"SO3-2-u1-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#6','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C8',1,'sa','auto','다른 지역에서 옮겨 와 사는 사람을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"sa","stem":"다른 지역에서 옮겨 와 사는 사람을 세 글자로 쓰세요.","answer":["이주민"],"explanation":["옮겨 와 살아요.","이◯◯이에요.","이주민이에요."],"mis":"SO3-2-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#7','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C9',1,'sa','auto','나와 다르고 익숙하지 않은 것에 대해 한쪽으로 치우친 생각을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"sa","stem":"나와 다르고 익숙하지 않은 것에 대해 한쪽으로 치우친 생각을 두 글자로 쓰세요.","answer":["편견"],"explanation":["생각이에요.","편◯이에요.","편견이에요."],"mis":"SO3-2-u1-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#8','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C10',1,'sa','auto','편견과 차별을 막는 제도를 만들고 관련 기관을 운영하는 곳은 「국가 ○○ 위원회」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-2-u1-C10","difficulty":1,"kind":"sa","stem":"편견과 차별을 막는 제도를 만들고 관련 기관을 운영하는 곳은 「국가 ○○ 위원회」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["인권"],"explanation":["사람의 권리예요.","인◯이에요.","인권이에요."],"mis":"SO3-2-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#9','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C1',2,'mc','auto','신문 ①의 모습을 사회 변화의 원인과 이은 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X02','SO3-2-u1-X01']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C1","difficulty":2,"kind":"mc","stem":"신문 ①의 모습을 사회 변화의 원인과 이은 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"사람 수의 변화로 학교와 어린이집의 모습이 달라졌어요","correct":true},{"t":"과학 기술의 발달로 학생이 줄었어요","mis":"SO3-2-u1-X02"},{"t":"다른 나라와의 교류로 어린이집이 문을 닫았어요","mis":"SO3-2-u1-X02"},{"t":"학교의 모습은 변하지 않았어요","mis":"SO3-2-u1-X01"}],"explanation":["학생과 원생이 줄었어요.","사람 수예요.","모습이 달라졌어요."],"asset":{"type":"passage","lines":["우리 학교는 옛날에 한 학년에 반이 아주 많았다.","지금은 학생이 줄어 한 학년에 두 반뿐이다.","근처 어린이집 한 곳은 원생이 부족해 문을 닫았다."],"title":"신문 ① — 우리 학교가 달라졌어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#10','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C3',2,'mc','auto','신문 ②에서 고령화에 대비하는 노력에 해당하는 것은 무엇인가요?',ARRAY['SO3-2-u1-X10']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"mc","stem":"신문 ②에서 고령화에 대비하는 노력에 해당하는 것은 무엇인가요?","options":[{"t":"노인에게 알맞은 일자리를 마련해 주는 일","correct":true},{"t":"복지관을 없애는 일","mis":"SO3-2-u1-X10"},{"t":"배움 프로그램을 줄이는 일","mis":"SO3-2-u1-X10"},{"t":"노인이 도서관에 오지 못하게 하는 일","mis":"SO3-2-u1-X10"}],"explanation":["도서관 할아버지예요.","일자리예요.","마련해 줘요."],"asset":{"type":"passage","lines":["동네에 노인 복지관이 새로 문을 열었다.","복지관에서는 노인을 위한 배움 프로그램과 운동 교실이 열린다.","동네 도서관에서는 일자리를 찾은 할아버지가 책 정리를 돕는다."],"title":"신문 ② — 동네 어르신들의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#11','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C4',2,'mc','auto','신문 ③에서 하늘반이 정할 인터넷 사용 약속으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X14','SO3-2-u1-X13']::text[],false,'{"seq":11,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"mc","stem":"신문 ③에서 하늘반이 정할 인터넷 사용 약속으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"인터넷에서 본 정보를 무조건 믿지 않고 맞는지 다시 살펴봐요","correct":true},{"t":"재미있는 정보는 바로 친구들에게 퍼뜨려요","mis":"SO3-2-u1-X14"},{"t":"개인 정보를 반 누리집에 모두 올려요","mis":"SO3-2-u1-X14"},{"t":"인터넷은 아예 쓰지 않아요","mis":"SO3-2-u1-X13"}],"explanation":["가짜 뉴스가 있었어요.","그대로 믿지 않아요.","다시 살펴봐요."],"asset":{"type":"passage","lines":["우리 반은 인공지능 학습 프로그램으로 수학을 공부한다.","그런데 가짜 뉴스를 그대로 믿고 대화방에 퍼뜨린 일이 있었다.","그래서 우리 반은 인터넷 사용 약속을 함께 정했다."],"title":"신문 ③ — 인공지능과 함께하는 우리 반"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#12','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C5',2,'mc','auto','신문 ④의 모습을 모두 이어 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X15','SO3-2-u1-X16']::text[],false,'{"seq":12,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"mc","stem":"신문 ④의 모습을 모두 이어 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리 동네도 세계 여러 나라와 서로 주고받으며 연결되어 있어요","correct":true},{"t":"우리 동네는 다른 나라와 관계가 없어요","mis":"SO3-2-u1-X15"},{"t":"다른 나라 것이 들어오기만 해요","mis":"SO3-2-u1-X16"},{"t":"우리 동네 것은 다른 나라로 나가지 않아요","mis":"SO3-2-u1-X16"}],"explanation":["들어온 것이 있어요.","나간 것도 있어요.","연결되어 있어요."],"asset":{"type":"passage","lines":["동네 시장에 다른 나라 과일을 파는 가게가 생겼다.","우리 동네의 한 회사는 다른 나라에 공장을 지었다.","다른 나라 친구에게 한국어를 가르쳐 주는 형도 있다."],"title":"신문 ④ — 세계와 이어진 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#13','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C7',2,'mc','auto','신문 ⑤의 세 가족 이야기에서 「비슷한 점」은 무엇인가요?',ARRAY['SO3-2-u1-X22']::text[],false,'{"seq":13,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"mc","stem":"신문 ⑤의 세 가족 이야기에서 「비슷한 점」은 무엇인가요?","options":[{"t":"모두 생일을 맞은 사람을 축하해요","correct":true},{"t":"모두 미역국을 먹어요","mis":"SO3-2-u1-X22"},{"t":"모두 국수를 먹어요","mis":"SO3-2-u1-X22"},{"t":"아무도 생일을 축하하지 않아요","mis":"SO3-2-u1-X22"}],"explanation":["하는 일을 봐요.","축하해요.","그것이 비슷해요."],"asset":{"type":"passage","lines":["친구 가네 가족은 생일에 미역국을 끓여 먹는다.","친구 나네 가족은 생일에 국수를 먹는다.","친구 다네 가족은 생일에 케이크에 촛불을 켠다."],"title":"신문 ⑤ — 우리 반 생일 축하 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#14','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C9',2,'mc','auto','신문 ⑥에서 반려동물과 함께 사는 사람이 늘며 생긴 「문제」는 무엇인가요?',ARRAY['SO3-2-u1-X28']::text[],false,'{"seq":14,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"mc","stem":"신문 ⑥에서 반려동물과 함께 사는 사람이 늘며 생긴 「문제」는 무엇인가요?","options":[{"t":"반려견 짖는 소리 때문에 이웃끼리 다툰 일","correct":true},{"t":"반려동물 놀이터가 생긴 일","mis":"SO3-2-u1-X28"},{"t":"1인분 반찬 가게가 늘어난 일","mis":"SO3-2-u1-X28"},{"t":"베트남 음식점이 생긴 일","mis":"SO3-2-u1-X28"}],"explanation":["문제를 골라요.","소음이에요.","이웃 다툼이에요."],"asset":{"type":"passage","lines":["동네에 베트남 음식점과 반려동물 놀이터가 생겼다.","혼자 사는 이웃을 위한 1인분 반찬 가게도 늘었다.","반려견 짖는 소리 때문에 이웃끼리 다툰 일도 있었다."],"title":"신문 ⑥ — 우리 동네의 다양한 문화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#15','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C10',2,'mc','auto','신문 ⑦에서 하늘반이 함께 지킬 약속으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X30','SO3-2-u1-X31']::text[],false,'{"seq":15,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"mc","stem":"신문 ⑦에서 하늘반이 함께 지킬 약속으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"말이 서툰 친구에게 먼저 다가가 함께 놀아요","correct":true},{"t":"말이 서툰 친구는 놀이에서 빼요","mis":"SO3-2-u1-X30"},{"t":"우리말을 잘하는 친구끼리만 놀아요","mis":"SO3-2-u1-X31"},{"t":"친구의 말을 흉내 내며 놀려요","mis":"SO3-2-u1-X30"}],"explanation":["친구를 존중해요.","먼저 다가가요.","함께 놀아요."],"asset":{"type":"passage","lines":["새로 전학 온 친구는 아직 우리말이 서툴다.","몇몇 친구가 말이 다르다고 놀이에 끼워 주지 않았다.","선생님과 우리 반은 함께 지킬 약속을 만들었다."],"title":"신문 ⑦ — 우리 반에서 생긴 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#16','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C11',2,'mc','auto','신문 ⑧의 축제 주제에 어울리는 프로그램을 하나 더 넣는다면 무엇이 가장 알맞은가요?',ARRAY['SO3-2-u1-X32','SO3-2-u1-X31']::text[],false,'{"seq":16,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"mc","stem":"신문 ⑧의 축제 주제에 어울리는 프로그램을 하나 더 넣는다면 무엇이 가장 알맞은가요?","options":[{"t":"여러 나라의 놀이를 함께 해 보기","correct":true},{"t":"1인분 반찬 만들기","mis":"SO3-2-u1-X32"},{"t":"반려견 예절 배우기","mis":"SO3-2-u1-X32"},{"t":"우리나라 놀이만 하기","mis":"SO3-2-u1-X31"}],"explanation":["세계 문화예요.","여러 나라예요.","놀이를 함께 해요."],"asset":{"type":"passage","lines":["하늘반은 「세계 문화 나눔 축제」를 계획했다.","프로그램 — 여러 나라 인사말 배우기, 세계 음식 그림 그리기","장소 — 학교 강당 · 우리 반이 초청하는 글을 써서 나눠 준다."],"title":"신문 ⑧ — 하늘반 축제 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#17','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C6',3,'error','auto','사회 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X19']::text[],false,'{"seq":17,"concept":"SO3-2-u1-C6","difficulty":3,"kind":"error","stem":"사회 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「사회 변화는 우리 생활과 관계가 없어.」","correct":true,"mis_target":"SO3-2-u1-X19"},{"t":"친구 가 — 「사회 변화로 생활 모습이 달라져.」","mis":"SO3-2-u1-X19"},{"t":"친구 다 — 「문제를 해결하려면 모두 함께 노력해야 해.」","mis":"SO3-2-u1-X19"}],"explanation":["생활이 달라져요.","관계가 있어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#18','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C5',3,'error','auto','세계화로 달라진 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":18,"concept":"SO3-2-u1-C5","difficulty":3,"kind":"error","stem":"세계화로 달라진 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「다른 나라 생활 양식은 모두 받아들이지 않는 게 좋아.」","correct":true,"mis_target":"SO3-2-u1-X17"},{"t":"친구 가 — 「장단점을 따져 받아들여야 해.」","mis":"SO3-2-u1-X17"},{"t":"친구 나 — 「세계 여러 나라의 문제에 관심을 가져야 해.」","mis":"SO3-2-u1-X17"}],"explanation":["모두 거부해야 할까요?","따져 받아들여요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#19','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C7',3,'error','auto','문화의 뜻을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X21','SO3-2-u1-X23']::text[],false,'{"seq":19,"concept":"SO3-2-u1-C7","difficulty":3,"kind":"error","stem":"문화의 뜻을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「졸려서 잠을 자는 것도 문화야.」","correct":true,"mis_target":"SO3-2-u1-X20"},{"t":"친구 나 — 「규범도 문화에 들어가.」","mis":"SO3-2-u1-X21"},{"t":"친구 다 — 「환경에 따라 생활 양식이 달라.」","mis":"SO3-2-u1-X23"}],"explanation":["타고난 행동이에요.","문화가 아니에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#20','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C9',3,'error','auto','다양한 문화의 영향을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X26','SO3-2-u1-X29']::text[],false,'{"seq":20,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"error","stem":"다양한 문화의 영향을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「문제가 생기는 문화는 우리 사회에서 없애야 해.」","correct":true,"mis_target":"SO3-2-u1-X26"},{"t":"친구 가 — 「좋은 영향과 문제가 함께 나타나.」","mis":"SO3-2-u1-X26"},{"t":"친구 다 — 「문제는 함께 노력해서 풀어 가야 해.」","mis":"SO3-2-u1-X29"}],"explanation":["없애야 할까요?","함께 풀어 가요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#21','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C10',3,'error','auto','다양한 문화를 존중하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X30','SO3-2-u1-X31']::text[],false,'{"seq":21,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"error","stem":"다양한 문화를 존중하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「1인 가구 사람들은 이상해.」","correct":true,"mis_target":"SO3-2-u1-X30"},{"t":"친구 나 — 「다른 문화의 어려움에 관심을 갖자.」","mis":"SO3-2-u1-X30"},{"t":"친구 다 — 「서로 다름을 인정하자.」","mis":"SO3-2-u1-X31"}],"explanation":["이상하다고 볼까요?","바람직하지 못해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#22','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C3',3,'error','auto','「100명이 사는 마을」 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u1-X08']::text[],false,'{"seq":22,"concept":"SO3-2-u1-C3","difficulty":3,"kind":"error","stem":"「100명이 사는 마을」 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「노인의 수가 늘었을 뿐 비율은 그대로야.」","correct":true,"mis_target":"SO3-2-u1-X08"},{"t":"친구 가 — 「100명 가운데 노인이 점점 많아져.」","mis":"SO3-2-u1-X08"},{"t":"친구 나 — 「노인이 차지하는 비율이 높아지고 있어.」","mis":"SO3-2-u1-X08"}],"explanation":["모두 100명이에요.","노인이 늘면 비율도 높아져요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#23','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C9',4,'mc','auto','신문 ⑥과 ⑦을 함께 볼 때 가장 알맞은 결론은 무엇인가요?',ARRAY['SO3-2-u1-X26','SO3-2-u1-X29','SO3-2-u1-X31']::text[],false,'{"seq":23,"concept":"SO3-2-u1-C9","difficulty":4,"kind":"mc","stem":"신문 ⑥과 ⑦을 함께 볼 때 가장 알맞은 결론은 무엇인가요?","options":[{"t":"다양한 문화가 늘며 문제가 생기기도 하지만, 존중하는 태도와 함께하는 노력으로 풀어 갈 수 있어요","correct":true},{"t":"문제가 생기니 다양한 문화는 없어야 해요","mis":"SO3-2-u1-X26"},{"t":"문제는 저절로 사라져요","mis":"SO3-2-u1-X29"},{"t":"우리 문화만 지키면 돼요","mis":"SO3-2-u1-X31"}],"explanation":["⑥은 동네예요.","⑦은 우리 반이에요.","존중하고 노력해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#24','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C3',4,'essay','teacher','신문 ②에서 고령화로 달라진 모습 두 가지를 찾아 쓰고, 노인이 안정된 생활을 하도록 우리 사회가 할 수 있는 노력을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u1-C3","difficulty":4,"kind":"essay","stem":"신문 ②에서 고령화로 달라진 모습 두 가지를 찾아 쓰고, 노인이 안정된 생활을 하도록 우리 사회가 할 수 있는 노력을 쓰세요.","answer_guide":{"answer":"예: 동네에 노인 복지관이 새로 생겼고, 일자리를 찾은 할아버지가 도서관에서 일해요. 우리 사회는 노인을 위한 복지 제도를 운영하고, 노인에게 알맞은 일자리를 더 마련할 수 있어요.","scoring_points":["달라진 모습 두 가지를 찾았는가","노력을 썼는가","노인의 안정된 생활과 이었는가"]},"explanation":["복지관을 찾아요.","일하는 할아버지예요.","노력을 써요."],"asset":{"type":"passage","lines":["동네에 노인 복지관이 새로 문을 열었다.","복지관에서는 노인을 위한 배움 프로그램과 운동 교실이 열린다.","동네 도서관에서는 일자리를 찾은 할아버지가 책 정리를 돕는다."],"title":"신문 ② — 동네 어르신들의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_b#25','soc',3,2,'u1','','g3_2_soc_u1_review_b','unit_review','SO3-2-u1-C9',4,'essay','teacher','신문 ⑥에서 다양한 문화가 늘며 나타난 좋은 점과 문제를 하나씩 쓰고, 문제를 줄이기 위해 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u1-C9","difficulty":4,"kind":"essay","stem":"신문 ⑥에서 다양한 문화가 늘며 나타난 좋은 점과 문제를 하나씩 쓰고, 문제를 줄이기 위해 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 반려동물 놀이터가 생겨 반려견이 안전하게 뛰어놀 수 있게 된 것은 좋은 점이에요. 반려견 짖는 소리 때문에 이웃끼리 다툰 것은 문제예요. 반려동물 예절을 지키고 이웃끼리 서로 배려하면 다툼을 줄일 수 있어요.","scoring_points":["좋은 점을 썼는가","문제를 썼는가","문제를 줄일 방법을 썼는가"]},"explanation":["좋은 점을 찾아요.","문제도 찾아요.","방법을 써요."],"asset":{"type":"passage","lines":["동네에 베트남 음식점과 반려동물 놀이터가 생겼다.","혼자 사는 이웃을 위한 1인분 반찬 가게도 늘었다.","반려견 짖는 소리 때문에 이웃끼리 다툰 일도 있었다."],"title":"신문 ⑥ — 우리 동네의 다양한 문화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#1','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C1',1,'ox','auto','사회 곳곳에는 사라지는 모습, 새로 생기는 모습, 바뀌는 모습이 있어요.',ARRAY['SO3-2-u1-X01']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"ox","stem":"사회 곳곳에는 사라지는 모습, 새로 생기는 모습, 바뀌는 모습이 있어요.","answer":"O","reason_options":[{"t":"사회는 끊임없이 변하기 때문에","correct":true},{"t":"사회의 모습은 변하지 않기 때문에","mis":"SO3-2-u1-X01"}],"mis":"SO3-2-u1-X01","explanation":["사회는 변해요.","여러 모습이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#2','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C3',1,'ox','auto','고령화는 전체 사람 수에서 노인이 차지하는 비율이 높아지는 현상이에요.',ARRAY['SO3-2-u1-X08']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C3","difficulty":1,"kind":"ox","stem":"고령화는 전체 사람 수에서 노인이 차지하는 비율이 높아지는 현상이에요.","answer":"O","reason_options":[{"t":"노인의 수가 아니라 전체에서 차지하는 정도가 커지는 것이기 때문에","correct":true},{"t":"노인의 수가 줄어드는 현상이기 때문에","mis":"SO3-2-u1-X08"}],"mis":"SO3-2-u1-X08","explanation":["비율이에요.","높아져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#3','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C4',1,'ox','auto','자신의 개인 정보는 인터넷에서 함부로 공유하지 않아요.',ARRAY['SO3-2-u1-X14']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"ox","stem":"자신의 개인 정보는 인터넷에서 함부로 공유하지 않아요.","answer":"O","reason_options":[{"t":"다른 사람이 내 개인 정보를 함부로 쓰는 일을 막을 수 있기 때문에","correct":true},{"t":"개인 정보는 널리 알릴수록 좋기 때문에","mis":"SO3-2-u1-X14"}],"mis":"SO3-2-u1-X14","explanation":["내 정보를 지켜요.","함부로 올리지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#4','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C5',1,'ox','auto','세계화로 감염병이 전 세계로 빠르게 퍼질 수 있어요.',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"ox","stem":"세계화로 감염병이 전 세계로 빠르게 퍼질 수 있어요.","answer":"O","reason_options":[{"t":"여러 나라를 오가는 사람이 많아졌기 때문에","correct":true},{"t":"세계화와 감염병은 관계가 없기 때문에","mis":"SO3-2-u1-X17"}],"mis":"SO3-2-u1-X17","explanation":["사람이 오가요.","병도 옮겨요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#5','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C7',1,'ox','auto','배가 고파서 음식을 먹는 것은 문화예요.',ARRAY['SO3-2-u1-X20']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"ox","stem":"배가 고파서 음식을 먹는 것은 문화예요.","answer":"X","reason_options":[{"t":"태어날 때부터 누구나 하게 되는 행동은 문화가 아니기 때문에","correct":true},{"t":"사람이 하는 모든 행동이 문화이기 때문에","mis":"SO3-2-u1-X20"}],"mis":"SO3-2-u1-X20","explanation":["누구나 해요.","타고난 행동이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#6','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C8',1,'ox','auto','오늘날 우리 사회에는 다양한 문화가 나타나고 있어요.',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"ox","stem":"오늘날 우리 사회에는 다양한 문화가 나타나고 있어요.","answer":"O","reason_options":[{"t":"외국인 이주민, 1인 가구, 반려동물과 함께 사는 사람이 늘었기 때문에","correct":true},{"t":"우리 사회에는 한 가지 문화만 있기 때문에","mis":"SO3-2-u1-X25"}],"mis":"SO3-2-u1-X25","explanation":["여러 사람들이 늘었어요.","문화가 다양해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#7','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C9',1,'ox','auto','다양한 문화가 퍼지면서 좋은 영향과 함께 문제도 나타나요.',ARRAY['SO3-2-u1-X26']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"ox","stem":"다양한 문화가 퍼지면서 좋은 영향과 함께 문제도 나타나요.","answer":"O","reason_options":[{"t":"문화를 경험할 기회가 늘었지만 편견과 차별 같은 문제도 생기기 때문에","correct":true},{"t":"다양한 문화는 좋은 영향만 주기 때문에","mis":"SO3-2-u1-X26"}],"mis":"SO3-2-u1-X26","explanation":["두 면이 있어요.","좋은 점과 문제예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#8','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C10',1,'ox','auto','한국어에 서툰 외국인을 위해 한국 생활에 필요한 정보를 다양한 언어로 알려 줘요.',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C10","difficulty":1,"kind":"ox","stem":"한국어에 서툰 외국인을 위해 한국 생활에 필요한 정보를 다양한 언어로 알려 줘요.","answer":"O","reason_options":[{"t":"말이 달라도 필요한 정보를 얻을 수 있게 돕기 때문에","correct":true},{"t":"외국인에게는 정보를 주지 않아도 되기 때문에","mis":"SO3-2-u1-X29"}],"mis":"SO3-2-u1-X29","explanation":["말이 서툴러요.","여러 언어로 알려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#9','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C2',2,'ox','auto','신문 ①처럼 저출산이 계속되면 앞으로 일할 수 있는 사람의 수도 줄어들 수 있어요.',ARRAY['SO3-2-u1-X06']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"ox","stem":"신문 ①처럼 저출산이 계속되면 앞으로 일할 수 있는 사람의 수도 줄어들 수 있어요.","answer":"O","reason_options":[{"t":"오늘 태어나는 아이가 자라 일할 사람이 되기 때문에","correct":true},{"t":"아이가 줄어도 일할 사람은 늘어나기 때문에","mis":"SO3-2-u1-X06"}],"mis":"SO3-2-u1-X06","explanation":["아이가 자라요.","일할 사람이 돼요.","그래서 O예요."],"asset":{"type":"passage","lines":["우리 학교는 옛날에 한 학년에 반이 아주 많았다.","지금은 학생이 줄어 한 학년에 두 반뿐이다.","근처 어린이집 한 곳은 원생이 부족해 문을 닫았다."],"title":"신문 ① — 우리 학교가 달라졌어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#10','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C3',2,'ox','auto','신문 ②처럼 노인을 위한 시설과 프로그램이 늘어나는 것은 노인이 차지하는 비율이 높아졌기 때문이에요.',ARRAY['SO3-2-u1-X08']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"ox","stem":"신문 ②처럼 노인을 위한 시설과 프로그램이 늘어나는 것은 노인이 차지하는 비율이 높아졌기 때문이에요.","answer":"O","reason_options":[{"t":"노인이 많아지면서 노인을 위한 시설과 프로그램이 더 필요해졌기 때문에","correct":true},{"t":"노인의 비율이 낮아졌기 때문에","mis":"SO3-2-u1-X08"}],"mis":"SO3-2-u1-X08","explanation":["노인이 많아졌어요.","더 필요해요.","그래서 O예요."],"asset":{"type":"passage","lines":["동네에 노인 복지관이 새로 문을 열었다.","복지관에서는 노인을 위한 배움 프로그램과 운동 교실이 열린다.","동네 도서관에서는 일자리를 찾은 할아버지가 책 정리를 돕는다."],"title":"신문 ② — 동네 어르신들의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#11','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C4',2,'ox','auto','신문 ③에서 가짜 뉴스를 퍼뜨린 일은 지능정보화로 생겨난 문제와 관계있어요.',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":11,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"ox","stem":"신문 ③에서 가짜 뉴스를 퍼뜨린 일은 지능정보화로 생겨난 문제와 관계있어요.","answer":"O","reason_options":[{"t":"인공지능이 만든 그럴듯한 거짓 정보가 사람들을 속이기도 하기 때문에","correct":true},{"t":"가짜 뉴스는 지능정보화와 관계가 없기 때문에","mis":"SO3-2-u1-X12"}],"mis":"SO3-2-u1-X12","explanation":["거짓 정보예요.","빠르게 퍼져요.","그래서 O예요."],"asset":{"type":"passage","lines":["우리 반은 인공지능 학습 프로그램으로 수학을 공부한다.","그런데 가짜 뉴스를 그대로 믿고 대화방에 퍼뜨린 일이 있었다.","그래서 우리 반은 인터넷 사용 약속을 함께 정했다."],"title":"신문 ③ — 인공지능과 함께하는 우리 반"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#12','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C5',2,'ox','auto','신문 ④의 형처럼 다른 나라 친구에게 한국어를 가르쳐 주는 것도 세계화의 모습이에요.',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":12,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"ox","stem":"신문 ④의 형처럼 다른 나라 친구에게 한국어를 가르쳐 주는 것도 세계화의 모습이에요.","answer":"O","reason_options":[{"t":"우리 말과 글이 다른 나라 사람에게 퍼져 나가는 교류이기 때문에","correct":true},{"t":"세계화는 물건이 오가는 것만 말하기 때문에","mis":"SO3-2-u1-X16"}],"mis":"SO3-2-u1-X16","explanation":["한국어를 알려요.","교류예요.","그래서 O예요."],"asset":{"type":"passage","lines":["동네 시장에 다른 나라 과일을 파는 가게가 생겼다.","우리 동네의 한 회사는 다른 나라에 공장을 지었다.","다른 나라 친구에게 한국어를 가르쳐 주는 형도 있다."],"title":"신문 ④ — 세계와 이어진 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#13','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C7',2,'ox','auto','신문 ⑤에서 생일에 국수를 먹는 것은 잘못된 문화예요.',ARRAY['SO3-2-u1-X22']::text[],false,'{"seq":13,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"ox","stem":"신문 ⑤에서 생일에 국수를 먹는 것은 잘못된 문화예요.","answer":"X","reason_options":[{"t":"축하하는 방법은 가족과 사회마다 다를 뿐 잘못된 것이 아니기 때문에","correct":true},{"t":"미역국을 먹는 것만 알맞은 문화이기 때문에","mis":"SO3-2-u1-X22"}],"mis":"SO3-2-u1-X22","explanation":["방법이 다를 뿐이에요.","잘못이 아니에요.","그래서 X예요."],"asset":{"type":"passage","lines":["친구 가네 가족은 생일에 미역국을 끓여 먹는다.","친구 나네 가족은 생일에 국수를 먹는다.","친구 다네 가족은 생일에 케이크에 촛불을 켠다."],"title":"신문 ⑤ — 우리 반 생일 축하 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#14','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C8',2,'ox','auto','신문 ⑥의 동네에는 여러 문화가 함께 나타나고 있어요.',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":14,"concept":"SO3-2-u1-C8","difficulty":2,"kind":"ox","stem":"신문 ⑥의 동네에는 여러 문화가 함께 나타나고 있어요.","answer":"O","reason_options":[{"t":"이주민, 1인 가구, 반려동물과 관련한 모습이 모두 있기 때문에","correct":true},{"t":"한 동네에는 한 문화만 있기 때문에","mis":"SO3-2-u1-X25"}],"mis":"SO3-2-u1-X25","explanation":["세 가지가 있어요.","함께 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["동네에 베트남 음식점과 반려동물 놀이터가 생겼다.","혼자 사는 이웃을 위한 1인분 반찬 가게도 늘었다.","반려견 짖는 소리 때문에 이웃끼리 다툰 일도 있었다."],"title":"신문 ⑥ — 우리 동네의 다양한 문화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#15','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C9',2,'ox','auto','신문 ⑦에서 「말이 다르니 우리와 놀 수 없을 거야」라고 생각한 것은 편견이에요.',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":15,"concept":"SO3-2-u1-C9","difficulty":2,"kind":"ox","stem":"신문 ⑦에서 「말이 다르니 우리와 놀 수 없을 거야」라고 생각한 것은 편견이에요.","answer":"O","reason_options":[{"t":"익숙하지 않은 것에 대해 공정하지 못하고 치우친 생각이기 때문에","correct":true},{"t":"생각은 편견이 될 수 없기 때문에","mis":"SO3-2-u1-X27"}],"mis":"SO3-2-u1-X27","explanation":["생각이에요.","치우쳤어요.","그래서 O예요."],"asset":{"type":"passage","lines":["새로 전학 온 친구는 아직 우리말이 서툴다.","몇몇 친구가 말이 다르다고 놀이에 끼워 주지 않았다.","선생님과 우리 반은 함께 지킬 약속을 만들었다."],"title":"신문 ⑦ — 우리 반에서 생긴 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#16','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C11',2,'ox','auto','신문 ⑧의 축제는 서로 다른 문화를 이해하고 존중하는 마음을 키우는 데 도움이 돼요.',ARRAY['SO3-2-u1-X31']::text[],false,'{"seq":16,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"ox","stem":"신문 ⑧의 축제는 서로 다른 문화를 이해하고 존중하는 마음을 키우는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"여러 나라의 문화를 함께 경험하고 나누기 때문에","correct":true},{"t":"축제는 문화와 관계가 없기 때문에","mis":"SO3-2-u1-X31"}],"mis":"SO3-2-u1-X31","explanation":["함께 경험해요.","이해해요.","그래서 O예요."],"asset":{"type":"passage","lines":["하늘반은 「세계 문화 나눔 축제」를 계획했다.","프로그램 — 여러 나라 인사말 배우기, 세계 음식 그림 그리기","장소 — 학교 강당 · 우리 반이 초청하는 글을 써서 나눠 준다."],"title":"신문 ⑧ — 하늘반 축제 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#17','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C2',3,'ox','auto','저출산과 고령화는 함께 나타나기도 해요.',ARRAY['SO3-2-u1-X18']::text[],false,'{"seq":17,"concept":"SO3-2-u1-C2","difficulty":3,"kind":"ox","stem":"저출산과 고령화는 함께 나타나기도 해요.","answer":"O","reason_options":[{"t":"태어나는 아이는 줄고 노인은 오래 살아 노인이 차지하는 비율이 더 높아지기 때문에","correct":true},{"t":"두 변화는 서로 아무 관계가 없기 때문에","mis":"SO3-2-u1-X18"}],"mis":"SO3-2-u1-X18","explanation":["아이는 줄어요.","노인은 늘어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#18','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C4',3,'ox','auto','인공지능이 사람의 일을 대신 하면서 일자리가 줄어드는 것은 지능정보화로 편리해진 점이에요.',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":18,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"ox","stem":"인공지능이 사람의 일을 대신 하면서 일자리가 줄어드는 것은 지능정보화로 편리해진 점이에요.","answer":"X","reason_options":[{"t":"일자리가 줄어드는 것은 생겨난 문제이기 때문에","correct":true},{"t":"일자리가 줄면 모두 쉴 수 있어 편리하기 때문에","mis":"SO3-2-u1-X12"}],"mis":"SO3-2-u1-X12","explanation":["일자리가 줄어요.","문제예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#19','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C7',3,'ox','auto','추운 지역과 햇볕이 강한 지역의 옷차림이 다른 것은 지역의 환경에 따라 생활 양식이 달라지기 때문이에요.',ARRAY['SO3-2-u1-X23']::text[],false,'{"seq":19,"concept":"SO3-2-u1-C7","difficulty":3,"kind":"ox","stem":"추운 지역과 햇볕이 강한 지역의 옷차림이 다른 것은 지역의 환경에 따라 생활 양식이 달라지기 때문이에요.","answer":"O","reason_options":[{"t":"몸을 보호한다는 까닭은 같지만 환경에 맞게 입는 옷이 달라지기 때문에","correct":true},{"t":"한 지역의 옷만 알맞은 옷이기 때문에","mis":"SO3-2-u1-X23"}],"mis":"SO3-2-u1-X23","explanation":["환경이 달라요.","옷차림도 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#20','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C9',3,'ox','auto','「피부색이 다르다고 반장 선거에 나오지 못하게 했다」는 것은 생각에 그친 편견이 아니라 행동으로 옮긴 차별이에요.',ARRAY['SO3-2-u1-X27']::text[],false,'{"seq":20,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"ox","stem":"「피부색이 다르다고 반장 선거에 나오지 못하게 했다」는 것은 생각에 그친 편견이 아니라 행동으로 옮긴 차별이에요.","answer":"O","reason_options":[{"t":"치우친 생각을 행동으로 옮겨 다르게 대우했기 때문에","correct":true},{"t":"행동으로 옮기면 더 이상 문제가 아니기 때문에","mis":"SO3-2-u1-X27"}],"mis":"SO3-2-u1-X27","explanation":["나오지 못하게 했어요.","행동이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#21','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C10',3,'ox','auto','누구나 쓰기 쉽게 만든 유니버설 디자인은 다양한 사람들이 함께 살아가는 데 도움이 돼요.',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":21,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"ox","stem":"누구나 쓰기 쉽게 만든 유니버설 디자인은 다양한 사람들이 함께 살아가는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"나이, 국적, 언어, 장애 등과 관계없이 모두가 편하게 쓸 수 있기 때문에","correct":true},{"t":"특별한 사람만 쓸 수 있게 만든 것이기 때문에","mis":"SO3-2-u1-X29"}],"mis":"SO3-2-u1-X29","explanation":["누구나 써요.","함께 살아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#22','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C8',3,'ox','auto','외국인 이주민 수가 111만 명에서 213만 명으로 바뀐 것은 이주민이 늘어났다는 뜻이에요.',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":22,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"ox","stem":"외국인 이주민 수가 111만 명에서 213만 명으로 바뀐 것은 이주민이 늘어났다는 뜻이에요.","answer":"O","reason_options":[{"t":"뒤의 수가 앞의 수보다 크기 때문에","correct":true},{"t":"수가 커지면 줄어든 것이기 때문에","mis":"SO3-2-u1-X05"}],"mis":"SO3-2-u1-X05","explanation":["두 수를 견줘요.","뒤가 더 커요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#23','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C7',4,'mc','auto','신문 ⑤와 ⑧을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X22','SO3-2-u1-X32']::text[],false,'{"seq":23,"concept":"SO3-2-u1-C7","difficulty":4,"kind":"mc","stem":"신문 ⑤와 ⑧을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"문화는 저마다 다르고, 축제처럼 서로의 문화를 나누면 더 잘 이해할 수 있어요","correct":true},{"t":"다른 문화는 알 필요가 없어요","mis":"SO3-2-u1-X22"},{"t":"모든 문화는 똑같아요","mis":"SO3-2-u1-X22"},{"t":"축제는 문화와 관계가 없어요","mis":"SO3-2-u1-X32"}],"explanation":["⑤는 생일이에요.","⑧은 축제예요.","나누면 이해해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#24','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C4',4,'essay','teacher','신문 ③에서 지능정보화로 편리해진 점과 생겨난 문제를 하나씩 쓰고, 하늘반이 정할 인터넷 사용 약속을 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u1-C4","difficulty":4,"kind":"essay","stem":"신문 ③에서 지능정보화로 편리해진 점과 생겨난 문제를 하나씩 쓰고, 하늘반이 정할 인터넷 사용 약속을 하나 쓰세요.","answer_guide":{"answer":"예: 인공지능 학습 프로그램으로 공부할 수 있게 된 것은 편리해진 점이에요. 가짜 뉴스를 그대로 믿고 퍼뜨린 것은 생겨난 문제예요. 하늘반은 「인터넷에서 본 정보는 맞는지 다시 살펴보고 함부로 퍼뜨리지 않아요」라는 약속을 정할 수 있어요.","scoring_points":["편리해진 점을 썼는가","생겨난 문제를 썼는가","문제에 맞는 약속을 썼는가"]},"explanation":["누려요.","보완해요.","약속을 써요."],"asset":{"type":"passage","lines":["우리 반은 인공지능 학습 프로그램으로 수학을 공부한다.","그런데 가짜 뉴스를 그대로 믿고 대화방에 퍼뜨린 일이 있었다.","그래서 우리 반은 인터넷 사용 약속을 함께 정했다."],"title":"신문 ③ — 인공지능과 함께하는 우리 반"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_c#25','soc',3,2,'u1','','g3_2_soc_u1_review_c','unit_review','SO3-2-u1-C10',4,'essay','teacher','신문 ⑦의 일이 왜 바람직하지 않은지 「편견」과 「차별」이라는 말을 넣어 쓰고, 내가 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u1-C10","difficulty":4,"kind":"essay","stem":"신문 ⑦의 일이 왜 바람직하지 않은지 「편견」과 「차별」이라는 말을 넣어 쓰고, 내가 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 말이 다르니 함께 놀 수 없다고 생각한 것은 편견이고, 그래서 놀이에 끼워 주지 않은 것은 차별이에요. 나는 전학 온 친구에게 먼저 다가가 함께 놀고, 우리말을 천천히 알려 줄 거예요.","scoring_points":["편견을 바르게 썼는가","차별을 바르게 썼는가","내가 할 수 있는 일을 썼는가"]},"explanation":["생각은 편견이에요.","행동은 차별이에요.","할 일을 써요."],"asset":{"type":"passage","lines":["새로 전학 온 친구는 아직 우리말이 서툴다.","몇몇 친구가 말이 다르다고 놀이에 끼워 주지 않았다.","선생님과 우리 반은 함께 지킬 약속을 만들었다."],"title":"신문 ⑦ — 우리 반에서 생긴 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#1','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C1',1,'blank','auto','사람들이 예전보다 오래 살게 된 것을 평균 (    )의 증가라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u1-X02']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"blank","stem":"사람들이 예전보다 오래 살게 된 것을 평균 (    )의 증가라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"수명","correct":true},{"t":"키","mis":"SO3-2-u1-X02"},{"t":"몸무게","mis":"SO3-2-u1-X02"},{"t":"나이 차","mis":"SO3-2-u1-X02"}],"explanation":["얼마나 사는지예요.","수◯이에요.","수명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#2','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C2',1,'mc','auto','저출산 문제를 해결하려는 노력으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X07']::text[],false,'{"seq":2,"concept":"SO3-2-u1-C2","difficulty":1,"kind":"mc","stem":"저출산 문제를 해결하려는 노력으로 알맞은 것은 무엇인가요?","options":[{"t":"안전하고 쾌적한 보육 시설을 만들어요","correct":true},{"t":"학교의 문을 닫아요","mis":"SO3-2-u1-X07"},{"t":"아이를 키우는 가정의 요금을 더 받아요","mis":"SO3-2-u1-X07"},{"t":"병원의 수를 줄여요","mis":"SO3-2-u1-X07"}],"explanation":["아이를 키우기 쉽게요.","맡길 곳이에요.","보육 시설이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#3','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C4',1,'mc','auto','지능정보화로 생겨난 문제로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X12']::text[],false,'{"seq":3,"concept":"SO3-2-u1-C4","difficulty":1,"kind":"mc","stem":"지능정보화로 생겨난 문제로 알맞은 것은 무엇인가요?","options":[{"t":"사이버 범죄","correct":true},{"t":"배달 로봇","mis":"SO3-2-u1-X12"},{"t":"맞춤 교육","mis":"SO3-2-u1-X12"},{"t":"안전 운전 도움","mis":"SO3-2-u1-X12"}],"explanation":["문제를 골라요.","인터넷에서 일어나요.","사이버 범죄예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#4','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C5',1,'mc','auto','다른 나라에서 한국어를 배우려는 사람들에게 한국어를 가르치는 곳은 어디인가요?',ARRAY['SO3-2-u1-X16']::text[],false,'{"seq":4,"concept":"SO3-2-u1-C5","difficulty":1,"kind":"mc","stem":"다른 나라에서 한국어를 배우려는 사람들에게 한국어를 가르치는 곳은 어디인가요?","options":[{"t":"세종 학당","correct":true},{"t":"노인 복지관","mis":"SO3-2-u1-X16"},{"t":"보육 시설","mis":"SO3-2-u1-X16"},{"t":"반려동물 놀이터","mis":"SO3-2-u1-X16"}],"explanation":["한국어를 가르쳐요.","세종대왕 이름이 들어가요.","세종 학당이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#5','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C7',1,'mc','auto','문화에 들어가는 것끼리 모은 것은 무엇인가요?',ARRAY['SO3-2-u1-X20']::text[],false,'{"seq":5,"concept":"SO3-2-u1-C7","difficulty":1,"kind":"mc","stem":"문화에 들어가는 것끼리 모은 것은 무엇인가요?","options":[{"t":"말과 글, 음악, 종교, 규범","correct":true},{"t":"하품하기, 기지개 켜기","mis":"SO3-2-u1-X20"},{"t":"졸릴 때 자기, 깨어나기","mis":"SO3-2-u1-X20"},{"t":"배고플 때 먹기, 목마를 때 마시기","mis":"SO3-2-u1-X20"}],"explanation":["함께 만든 것이에요.","타고난 행동은 빼요.","말과 글·음악이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#6','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C8',1,'mc','auto','사람과 더불어 살아가며 친밀감과 안정감을 주는 동물을 무엇이라고 하나요?',ARRAY['SO3-2-u1-X24']::text[],false,'{"seq":6,"concept":"SO3-2-u1-C8","difficulty":1,"kind":"mc","stem":"사람과 더불어 살아가며 친밀감과 안정감을 주는 동물을 무엇이라고 하나요?","options":[{"t":"반려동물","correct":true},{"t":"야생 동물","mis":"SO3-2-u1-X24"},{"t":"멸종 동물","mis":"SO3-2-u1-X24"},{"t":"이주민","mis":"SO3-2-u1-X24"}],"explanation":["함께 살아요.","가족 같아요.","반려동물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#7','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C9',1,'mc','auto','1인 가구가 늘어나며 좋아진 점으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X28']::text[],false,'{"seq":7,"concept":"SO3-2-u1-C9","difficulty":1,"kind":"mc","stem":"1인 가구가 늘어나며 좋아진 점으로 알맞은 것은 무엇인가요?","options":[{"t":"작은 가전제품과 적은 양을 포장한 상품이 많아졌어요","correct":true},{"t":"이웃 간 소음 갈등이 생겼어요","mis":"SO3-2-u1-X28"},{"t":"외로움을 느끼는 사람이 생겼어요","mis":"SO3-2-u1-X28"},{"t":"버려지는 동물이 생겼어요","mis":"SO3-2-u1-X28"}],"explanation":["좋아진 점이에요.","혼자 쓰기 좋아요.","작은 제품이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#8','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C11',1,'mc','auto','축제 초대장을 만드는 차례로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":8,"concept":"SO3-2-u1-C11","difficulty":1,"kind":"mc","stem":"축제 초대장을 만드는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"주제 → 프로그램 → 내용과 장소 → 초청하는 글","correct":true},{"t":"초청하는 글 → 주제 → 장소 → 프로그램","mis":"SO3-2-u1-X32"},{"t":"장소 → 초청하는 글 → 주제 → 프로그램","mis":"SO3-2-u1-X32"},{"t":"프로그램 → 초청하는 글 → 장소 → 주제","mis":"SO3-2-u1-X32"}],"explanation":["주제가 먼저예요.","프로그램을 계획해요.","초청 글이 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#9','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C2',2,'mc','auto','신문 ①의 문제를 해결하는 데 도움이 되는 노력으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X07','SO3-2-u1-X18']::text[],false,'{"seq":9,"concept":"SO3-2-u1-C2","difficulty":2,"kind":"mc","stem":"신문 ①의 문제를 해결하는 데 도움이 되는 노력으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"아이를 낳고 키우는 데 필요한 돈과 물품을 지원해요","correct":true},{"t":"남은 어린이집도 문을 닫아요","mis":"SO3-2-u1-X07"},{"t":"한 학년에 한 반만 두도록 정해요","mis":"SO3-2-u1-X07"},{"t":"노인 복지관을 더 지어요","mis":"SO3-2-u1-X18"}],"explanation":["아이를 키우기 쉽게요.","부담을 덜어요.","지원해요."],"asset":{"type":"passage","lines":["우리 학교는 옛날에 한 학년에 반이 아주 많았다.","지금은 학생이 줄어 한 학년에 두 반뿐이다.","근처 어린이집 한 곳은 원생이 부족해 문을 닫았다."],"title":"신문 ① — 우리 학교가 달라졌어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#10','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C3',2,'mc','auto','신문 ②의 할아버지처럼 일하는 노인이 늘어난 것을 가장 바르게 설명한 것은 무엇인가요?',ARRAY['SO3-2-u1-X10','SO3-2-u1-X18']::text[],false,'{"seq":10,"concept":"SO3-2-u1-C3","difficulty":2,"kind":"mc","stem":"신문 ②의 할아버지처럼 일하는 노인이 늘어난 것을 가장 바르게 설명한 것은 무엇인가요?","options":[{"t":"오래 살게 되면서 일하거나 일자리를 찾는 노인이 늘어난 고령화의 모습이에요","correct":true},{"t":"노인은 일을 할 수 없어요","mis":"SO3-2-u1-X10"},{"t":"세계화로 다른 나라에서 온 모습이에요","mis":"SO3-2-u1-X18"},{"t":"저출산 때문에만 생긴 모습이에요","mis":"SO3-2-u1-X18"}],"explanation":["오래 살아요.","일하는 노인이 늘었어요.","고령화예요."],"asset":{"type":"passage","lines":["동네에 노인 복지관이 새로 문을 열었다.","복지관에서는 노인을 위한 배움 프로그램과 운동 교실이 열린다.","동네 도서관에서는 일자리를 찾은 할아버지가 책 정리를 돕는다."],"title":"신문 ② — 동네 어르신들의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#11','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C4',2,'mc','auto','신문 ③을 읽고 지능정보화를 대하는 태도로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X13']::text[],false,'{"seq":11,"concept":"SO3-2-u1-C4","difficulty":2,"kind":"mc","stem":"신문 ③을 읽고 지능정보화를 대하는 태도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학습 프로그램은 잘 쓰고, 가짜 뉴스 같은 문제는 약속으로 보완해요","correct":true},{"t":"문제가 있으니 학습 프로그램을 버려요","mis":"SO3-2-u1-X13"},{"t":"편리하니 약속은 필요 없어요","mis":"SO3-2-u1-X13"},{"t":"가짜 뉴스는 저절로 사라져요","mis":"SO3-2-u1-X13"}],"explanation":["누려요.","보완해요.","둘 다 해요."],"asset":{"type":"passage","lines":["우리 반은 인공지능 학습 프로그램으로 수학을 공부한다.","그런데 가짜 뉴스를 그대로 믿고 대화방에 퍼뜨린 일이 있었다.","그래서 우리 반은 인터넷 사용 약속을 함께 정했다."],"title":"신문 ③ — 인공지능과 함께하는 우리 반"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#12','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C5',2,'mc','auto','신문 ④처럼 다른 나라 물건이 많아질 때 가져야 할 태도로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X17']::text[],false,'{"seq":12,"concept":"SO3-2-u1-C5","difficulty":2,"kind":"mc","stem":"신문 ④처럼 다른 나라 물건이 많아질 때 가져야 할 태도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"장단점을 따져 받아들이고 우리 생활 양식도 소중히 여겨요","correct":true},{"t":"우리 것은 모두 잊어요","mis":"SO3-2-u1-X17"},{"t":"다른 나라 것은 절대 쓰지 않아요","mis":"SO3-2-u1-X17"},{"t":"무조건 다른 나라 것만 따라요","mis":"SO3-2-u1-X17"}],"explanation":["무조건이 아니에요.","따져 받아들여요.","우리 것도 소중해요."],"asset":{"type":"passage","lines":["동네 시장에 다른 나라 과일을 파는 가게가 생겼다.","우리 동네의 한 회사는 다른 나라에 공장을 지었다.","다른 나라 친구에게 한국어를 가르쳐 주는 형도 있다."],"title":"신문 ④ — 세계와 이어진 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#13','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C7',2,'mc','auto','신문 ⑤의 생일 축하 모습을 문화라고 할 수 있는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X20','SO3-2-u1-X21']::text[],false,'{"seq":13,"concept":"SO3-2-u1-C7","difficulty":2,"kind":"mc","stem":"신문 ⑤의 생일 축하 모습을 문화라고 할 수 있는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"가족과 사회가 함께 만들어 이어 온 생활 양식이기 때문이에요","correct":true},{"t":"배가 고프면 누구나 먹기 때문이에요","mis":"SO3-2-u1-X20"},{"t":"한 사람만 하는 버릇이기 때문이에요","mis":"SO3-2-u1-X20"},{"t":"생일에만 하니까 문화가 아니에요","mis":"SO3-2-u1-X21"}],"explanation":["함께 만들었어요.","이어 왔어요.","생활 양식이에요."],"asset":{"type":"passage","lines":["친구 가네 가족은 생일에 미역국을 끓여 먹는다.","친구 나네 가족은 생일에 국수를 먹는다.","친구 다네 가족은 생일에 케이크에 촛불을 켠다."],"title":"신문 ⑤ — 우리 반 생일 축하 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#14','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C10',2,'mc','auto','신문 ⑥의 이웃 다툼을 줄이기 위한 노력으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X30','SO3-2-u1-X29']::text[],false,'{"seq":14,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"mc","stem":"신문 ⑥의 이웃 다툼을 줄이기 위한 노력으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"반려동물 예절을 지키고 서로 배려해요","correct":true},{"t":"반려동물을 기르는 이웃을 비난해요","mis":"SO3-2-u1-X30"},{"t":"반려견을 목줄 없이 산책시켜요","mis":"SO3-2-u1-X29"},{"t":"다툼은 저절로 사라지니 그냥 둬요","mis":"SO3-2-u1-X29"}],"explanation":["서로 배려해요.","예절을 지켜요.","함께 노력해요."],"asset":{"type":"passage","lines":["동네에 베트남 음식점과 반려동물 놀이터가 생겼다.","혼자 사는 이웃을 위한 1인분 반찬 가게도 늘었다.","반려견 짖는 소리 때문에 이웃끼리 다툰 일도 있었다."],"title":"신문 ⑥ — 우리 동네의 다양한 문화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#15','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C10',2,'mc','auto','신문 ⑦의 친구가 한국 생활에 필요한 정보를 얻기 어려울 때 도움이 되는 우리 사회의 노력은 무엇인가요?',ARRAY['SO3-2-u1-X29']::text[],false,'{"seq":15,"concept":"SO3-2-u1-C10","difficulty":2,"kind":"mc","stem":"신문 ⑦의 친구가 한국 생활에 필요한 정보를 얻기 어려울 때 도움이 되는 우리 사회의 노력은 무엇인가요?","options":[{"t":"필요한 정보를 다양한 언어로 알려 줘요","correct":true},{"t":"반려견에게 목줄을 채워요","mis":"SO3-2-u1-X29"},{"t":"1인분 반찬을 팔아요","mis":"SO3-2-u1-X29"},{"t":"노인 일자리를 마련해요","mis":"SO3-2-u1-X29"}],"explanation":["말이 서툴러요.","여러 언어가 필요해요.","다양한 언어로 알려요."],"asset":{"type":"passage","lines":["새로 전학 온 친구는 아직 우리말이 서툴다.","몇몇 친구가 말이 다르다고 놀이에 끼워 주지 않았다.","선생님과 우리 반은 함께 지킬 약속을 만들었다."],"title":"신문 ⑦ — 우리 반에서 생긴 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#16','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C11',2,'mc','auto','신문 ⑧처럼 초대장을 만들 때 장소를 정하는 것은 언제인가요?',ARRAY['SO3-2-u1-X32']::text[],false,'{"seq":16,"concept":"SO3-2-u1-C11","difficulty":2,"kind":"mc","stem":"신문 ⑧처럼 초대장을 만들 때 장소를 정하는 것은 언제인가요?","options":[{"t":"프로그램을 계획한 다음","correct":true},{"t":"가장 먼저","mis":"SO3-2-u1-X32"},{"t":"초청하는 글을 쓴 다음","mis":"SO3-2-u1-X32"},{"t":"주제를 정하기 전","mis":"SO3-2-u1-X32"}],"explanation":["주제가 먼저예요.","프로그램 다음이에요.","그때 장소를 정해요."],"asset":{"type":"passage","lines":["하늘반은 「세계 문화 나눔 축제」를 계획했다.","프로그램 — 여러 나라 인사말 배우기, 세계 음식 그림 그리기","장소 — 학교 강당 · 우리 반이 초청하는 글을 써서 나눠 준다."],"title":"신문 ⑧ — 하늘반 축제 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#17','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C1',3,'mc','auto','사회 변화에 대한 설명으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X02','SO3-2-u1-X01']::text[],false,'{"seq":17,"concept":"SO3-2-u1-C1","difficulty":3,"kind":"mc","stem":"사회 변화에 대한 설명으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여러 원인이 얽혀 사회가 변하고 그에 따라 생활 모습도 달라져요","correct":true},{"t":"사회는 한 가지 원인으로만 변해요","mis":"SO3-2-u1-X02"},{"t":"사회가 변해도 생활은 그대로예요","mis":"SO3-2-u1-X01"},{"t":"사회의 모습은 사라지기만 해요","mis":"SO3-2-u1-X01"}],"explanation":["원인이 여러 가지예요.","사회가 변해요.","생활도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#18','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C4',3,'mc','auto','우리 사회가 지능정보화에 대응하려고 하는 노력으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X14','SO3-2-u1-X13']::text[],false,'{"seq":18,"concept":"SO3-2-u1-C4","difficulty":3,"kind":"mc","stem":"우리 사회가 지능정보화에 대응하려고 하는 노력으로 알맞은 것은 무엇인가요?","options":[{"t":"달라질 직업 환경에 대응하기 위한 교육을 해요","correct":true},{"t":"개인 정보를 널리 알려요","mis":"SO3-2-u1-X14"},{"t":"사이버 범죄를 그냥 둬요","mis":"SO3-2-u1-X13"},{"t":"인공지능 교육을 모두 없애요","mis":"SO3-2-u1-X13"}],"explanation":["직업이 달라져요.","미리 배워요.","교육을 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#19','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C8',3,'mc','auto','외국인 이주민과 1인 가구가 늘어난 까닭을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X25']::text[],false,'{"seq":19,"concept":"SO3-2-u1-C8","difficulty":3,"kind":"mc","stem":"외국인 이주민과 1인 가구가 늘어난 까닭을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"외국인 이주민 — 세계화의 영향 · 1인 가구 — 결혼에 관한 생각 변화와 혼자 사는 노인 증가","correct":true},{"t":"외국인 이주민 — 혼자 사는 노인 증가 · 1인 가구 — 세계화의 영향","mis":"SO3-2-u1-X25"},{"t":"두 사람들 모두 줄어들고 있어요","mis":"SO3-2-u1-X25"},{"t":"두 사람들은 늘어난 까닭이 없어요","mis":"SO3-2-u1-X25"}],"explanation":["이주민은 세계화예요.","1인 가구는 생각 변화예요.","노인도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#20','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C10',3,'mc','auto','1인 가구의 어려움과 그에 맞는 노력을 바르게 이은 것은 무엇인가요?',ARRAY['SO3-2-u1-X29','SO3-2-u1-X26']::text[],false,'{"seq":20,"concept":"SO3-2-u1-C10","difficulty":3,"kind":"mc","stem":"1인 가구의 어려움과 그에 맞는 노력을 바르게 이은 것은 무엇인가요?","options":[{"t":"도움을 청할 사람이 없을 수 있어요 — 안전하고 편안하게 살 수 있도록 지원해요","correct":true},{"t":"도움을 청할 사람이 없어요 — 반려견에 목줄을 채워요","mis":"SO3-2-u1-X29"},{"t":"외로움을 느껴요 — 다양한 언어로 정보를 알려요","mis":"SO3-2-u1-X29"},{"t":"어려움이 없어요 — 노력이 필요 없어요","mis":"SO3-2-u1-X26"}],"explanation":["혼자 사는 어려움이에요.","맞는 노력을 골라요.","안전을 지원해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#21','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C11',3,'mc','auto','다양한 문화를 알리는 축제를 열면 좋은 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X31','SO3-2-u1-X30','SO3-2-u1-X32']::text[],false,'{"seq":21,"concept":"SO3-2-u1-C11","difficulty":3,"kind":"mc","stem":"다양한 문화를 알리는 축제를 열면 좋은 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"서로 다른 문화를 직접 경험하며 이해하고 존중하게 돼요","correct":true},{"t":"한 가지 문화만 남게 돼요","mis":"SO3-2-u1-X31"},{"t":"다른 문화를 놀릴 기회가 생겨요","mis":"SO3-2-u1-X30"},{"t":"축제는 문화와 관계없어요","mis":"SO3-2-u1-X32"}],"explanation":["직접 경험해요.","이해해요.","존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#22','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C9',3,'mc','auto','반려동물로 이웃 간에 갈등이 생긴 까닭 가운데 가장 많은 것과 그다음으로 많은 것을 차례대로 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":22,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"mc","stem":"반려동물로 이웃 간에 갈등이 생긴 까닭 가운데 가장 많은 것과 그다음으로 많은 것을 차례대로 짝지은 것은 무엇인가요?","options":[{"t":"소음 — 배설물","correct":true},{"t":"냄새 — 소음","mis":"SO3-2-u1-X05"},{"t":"배설물 — 소음","mis":"SO3-2-u1-X05"},{"t":"물림 — 냄새","mis":"SO3-2-u1-X05"}],"explanation":["소음이 첫째예요.","그다음을 떠올려요.","배설물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#23','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C1',4,'mc','auto','「사회 변화와 다양한 문화」 단원을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X01','SO3-2-u1-X19','SO3-2-u1-X26']::text[],false,'{"seq":23,"concept":"SO3-2-u1-C1","difficulty":4,"kind":"mc","stem":"「사회 변화와 다양한 문화」 단원을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"사회는 여러 원인으로 변하며 생활 모습이 달라지고, 다양한 문화가 늘어나는 사회에서는 서로 다름을 인정하고 존중해야 해요","correct":true},{"t":"사회는 변하지 않고 문화도 하나뿐이에요","mis":"SO3-2-u1-X01"},{"t":"사회 변화로 생긴 문제는 나라만 해결해요","mis":"SO3-2-u1-X19"},{"t":"다양한 문화가 퍼지면 좋은 점만 생겨요","mis":"SO3-2-u1-X26"}],"explanation":["사회 변화예요.","다양한 문화예요.","존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#24','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C5',4,'essay','teacher','신문 ④에서 세계화의 모습 두 가지를 찾아 쓰고, 세계화에 대응하는 바람직한 태도를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u1-C5","difficulty":4,"kind":"essay","stem":"신문 ④에서 세계화의 모습 두 가지를 찾아 쓰고, 세계화에 대응하는 바람직한 태도를 쓰세요.","answer_guide":{"answer":"예: 동네 시장에 다른 나라 과일 가게가 생겼고, 동네 회사가 다른 나라에 공장을 지었어요. 다른 나라의 생활 양식을 무조건 따르지 않고 장단점을 따져 받아들이며, 우리 생활 양식도 소중히 여겨야 해요.","scoring_points":["세계화의 모습 두 가지를 찾았는가","들어오고 나가는 모습이 드러났는가","바람직한 태도를 썼는가"]},"explanation":["들어온 것이 있어요.","나간 것도 있어요.","태도를 써요."],"asset":{"type":"passage","lines":["동네 시장에 다른 나라 과일을 파는 가게가 생겼다.","우리 동네의 한 회사는 다른 나라에 공장을 지었다.","다른 나라 친구에게 한국어를 가르쳐 주는 형도 있다."],"title":"신문 ④ — 세계와 이어진 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u1_review_d#25','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C11',4,'essay','teacher','신문 ⑧처럼 우리 반이 다양한 문화를 알리는 축제를 연다면 주제, 프로그램, 장소를 정하고 초청하는 글을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u1-C11","difficulty":4,"kind":"essay","stem":"신문 ⑧처럼 우리 반이 다양한 문화를 알리는 축제를 연다면 주제, 프로그램, 장소를 정하고 초청하는 글을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 주제는 「우리 동네 반려동물 축제」, 프로그램은 나의 반려동물 소개하기와 반려동물 예절 배우기, 장소는 학교 운동장이에요. 반려동물과 함께 사는 이웃을 이해하는 즐거운 축제에 여러분을 초대합니다. 다음 주 토요일, 학교 운동장에서 함께해요.","scoring_points":["주제·프로그램·장소를 정했는가","초청하는 글을 두 문장으로 썼는가","다양한 문화의 이해·존중이 드러났는가"]},"explanation":["주제를 정해요.","프로그램과 장소예요.","초청 글을 써요."],"asset":{"type":"passage","lines":["하늘반은 「세계 문화 나눔 축제」를 계획했다.","프로그램 — 여러 나라 인사말 배우기, 세계 음식 그림 그리기","장소 — 학교 강당 · 우리 반이 초청하는 글을 써서 나눠 준다."],"title":"신문 ⑧ — 하늘반 축제 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
